fn mace_mh1_trace_timings_enabled() -> bool {
    static TRACE_TIMINGS: OnceLock<bool> = OnceLock::new();
    *TRACE_TIMINGS.get_or_init(|| std::env::var_os("LLMLIP_MACE_MH1_TRACE_TIMINGS").is_some())
}

fn mace_mh1_disable_prepared_product_plan() -> bool {
    static DISABLED: OnceLock<bool> = OnceLock::new();
    *DISABLED.get_or_init(|| std::env::var_os("LLMLIP_MACE_MH1_DISABLE_PREPARED_PRODUCT").is_some())
}

#[allow(dead_code)]
fn mace_mh1_post_scatter_vjp_join_enabled() -> bool {
    static POST_SCATTER_VJP_JOIN: OnceLock<bool> = OnceLock::new();
    *POST_SCATTER_VJP_JOIN
        .get_or_init(|| std::env::var_os("LLMLIP_MACE_MH1_POST_SCATTER_VJP_JOIN").is_some())
}

fn mace_mh1_f32_edge_mlp_projected_linear0_enabled() -> bool {
    static PROJECTED_LINEAR0: OnceLock<bool> = OnceLock::new();
    *PROJECTED_LINEAR0.get_or_init(|| {
        std::env::var("LLMLIP_MACE_MH1_F32_EDGE_MLP_PROJECTED_LINEAR0")
            .map(|value| value != "0" && !value.eq_ignore_ascii_case("false"))
            .unwrap_or(true)
    })
}

#[cfg(feature = "parallel")]
fn mace_mh1_f32_edge_mlp_projected_join_enabled() -> bool {
    static PROJECTED_JOIN: OnceLock<bool> = OnceLock::new();
    *PROJECTED_JOIN.get_or_init(|| {
        std::env::var("LLMLIP_MACE_MH1_F32_EDGE_MLP_PROJECTED_JOIN")
            .map(|value| value != "0" && !value.eq_ignore_ascii_case("false"))
            .unwrap_or(true)
    })
}

fn mace_mh1_trace_stage(label: &str, start: Option<Instant>) {
    if let Some(start) = start {
        eprintln!(
            "mace_mh1_trace {label} {:.6} ms",
            start.elapsed().as_secs_f64() * 1000.0
        );
    }
}

// Must stay compiled for every BLAS backend whose dispatch call sites are
// active: the older paths gate on accelerate/intel-mkl/libxsmm, while the f32
// fast paths gate on accelerate/(intel-mkl|openblas); this is the union.
#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "libxsmm"),
        target_os = "linux",
        target_arch = "x86_64"
    ),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
fn mace_mh1_blas_dispatch_threshold() -> usize {
    static BLAS_DISPATCH_THRESHOLD: OnceLock<usize> = OnceLock::new();
    *BLAS_DISPATCH_THRESHOLD.get_or_init(|| {
        std::env::var("LLMLIP_MACE_MH1_BLAS_MIN_ROWS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|&value| value > 0)
            .unwrap_or(16)
    })
}

