#[derive(Clone, Debug)]
pub struct MaceMh1Model {
    summary: MaceMh1Summary,
    runtime_state: Option<MaceMh1RuntimeState>,
}

#[derive(Clone, Debug)]
struct MaceMh1Summary {
    selected_model: String,
    source_key: String,
    runtime_status: String,
    default_head: String,
    heads: Vec<String>,
    requested_heads: Vec<String>,
    missing_requested_heads: Vec<String>,
    type_names: Vec<String>,
    atomic_numbers: Vec<u8>,
    cutoff: f64,
    l_max: usize,
    artifact_sha256: String,
    state_dict_tensor_count: usize,
}

#[derive(Clone, Debug)]
struct MaceMh1RuntimeState {
    tensors: BTreeMap<String, MaceMh1ExternalTensor>,
    #[allow(dead_code)]
    f32_tensors: BTreeMap<String, Vec<f32>>,
    product0_scalar_entries: Option<MaceScalarSymmetricContractionEntries>,
    product0_vector_entries: Option<MaceVectorSymmetricContractionEntries>,
    product1_scalar_entries: Option<MaceScalarSymmetricContractionEntries>,
    product0_plan: Option<MaceScalarVectorSingleElementProductPlan>,
    product1_plan: Option<MaceScalarSingleElementProductPlan>,
}

#[derive(Clone, Debug)]
struct MaceMh1EdgeInputBoundary {
    edge_count: usize,
    edge_src: Vec<usize>,
    edge_dst: Vec<usize>,
    edge_vectors: Vec<[f64; 3]>,
    edge_distances: Vec<f64>,
    edge_src_atomic_numbers: Vec<usize>,
    edge_dst_atomic_numbers: Vec<usize>,
    edge_attrs: Vec<f64>,
    edge_feats: Vec<f64>,
    edge_cutoff: Vec<f64>,
    pair_node_energy: Vec<f64>,
}

#[derive(Clone, Debug)]
pub struct MaceMh1PreparedInput {
    type_ids: Vec<usize>,
    cell: Option<Cell>,
    pbc: [bool; 3],
    node_embedding: Vec<f64>,
    edge_boundary: MaceMh1EdgeInputBoundary,
}

impl MaceMh1PreparedInput {
    #[must_use]
    pub fn atom_count(&self) -> usize {
        self.type_ids.len()
    }

    #[must_use]
    pub fn edge_count(&self) -> usize {
        self.edge_boundary.edge_count
    }
}

