impl MaceMh1Interaction0PostScatterBoundary {
    fn linear_residual_len(&self) -> usize {
        self.forward_cache_f32
            .as_deref()
            .map_or(self.linear_residual.len(), |cache| {
                cache.linear_1_message.len()
            })
    }

    fn linear_1_message_len(&self) -> usize {
        self.forward_cache_f32
            .as_deref()
            .map_or(self.linear_1_message.len(), |cache| {
                cache.linear_1_message.len()
            })
    }

    fn density_denominator_len(&self) -> usize {
        self.forward_cache_f32
            .as_deref()
            .map_or(self.density_denominator.len(), |cache| {
                cache.density_denominator.len()
            })
    }

    fn density_normalized_message_len(&self) -> usize {
        self.forward_cache_f32
            .as_deref()
            .map_or(self.density_normalized_message.len(), |cache| {
                cache.linear_1_message.len()
            })
    }

    fn residual_message_len(&self) -> usize {
        self.forward_cache_f32
            .as_deref()
            .map_or(self.residual_message.len(), |cache| {
                cache.residual_message.len()
            })
    }

    fn nonlinear_message_len(&self) -> usize {
        self.forward_cache_f32
            .as_deref()
            .and_then(|cache| {
                post_scatter_len_from_cache_rows(
                    cache.residual_message.len(),
                    MACE_MH1_INTERACTION0_NONLIN_DIM,
                    MACE_MH1_INTERACTION0_OUT_DIM,
                )
            })
            .unwrap_or(self.nonlinear_message.len())
    }

    fn linear_2_message_len(&self) -> usize {
        self.forward_cache_f32
            .as_deref()
            .and_then(|cache| {
                post_scatter_len_from_cache_rows(
                    cache.residual_message.len(),
                    MACE_MH1_INTERACTION0_NONLIN_DIM,
                    MACE_MH1_INTERACTION0_OUT_DIM,
                )
            })
            .unwrap_or(self.linear_2_message.len())
    }

    fn reshaped_message_len(&self) -> usize {
        self.forward_cache_f32
            .as_deref()
            .map_or(self.reshaped_message.len(), |cache| {
                cache.reshaped_message.len()
            })
    }
}

