fn post_scatter_len_from_cache_rows(
    input_len: usize,
    input_row_dim: usize,
    output_row_dim: usize,
) -> Option<usize> {
    if input_row_dim == 0 || !input_len.is_multiple_of(input_row_dim) {
        return None;
    }
    input_len
        .checked_div(input_row_dim)?
        .checked_mul(output_row_dim)
}

