    #[allow(dead_code)]
    fn interaction0_conv_tp_boundary(
        &self,
        edge_input: &MaceMh1EdgeInputBoundary,
        interaction_input: &MaceMh1Interaction0InputBoundary,
        edge_mlp: &MaceMh1Interaction0EdgeMlpBoundary,
    ) -> Result<MaceMh1Interaction0ConvTpBoundary, MaceMh1Error> {
        self.interaction0_conv_tp_boundary_with_capture(
            edge_input,
            interaction_input,
            edge_mlp,
            true,
        )
    }

    fn interaction0_conv_tp_boundary_with_capture(
        &self,
        edge_input: &MaceMh1EdgeInputBoundary,
        interaction_input: &MaceMh1Interaction0InputBoundary,
        edge_mlp: &MaceMh1Interaction0EdgeMlpBoundary,
        capture_edge_messages: bool,
    ) -> Result<MaceMh1Interaction0ConvTpBoundary, MaceMh1Error> {
        let plan = mace_mh1_interaction0_conv_tp_plan()?;
        if plan.input1_dim() != MACE_MH1_INTERACTION0_CHANNELS
            || plan.input2_dim() != MACE_MH1_SH_DIM
            || plan.output_dim() != MACE_MH1_INTERACTION0_TP_OUTPUT_DIM
            || plan.weight_numel != MACE_MH1_INTERACTION0_TP_WEIGHT_DIM
        {
            return Err(invalid(
                "MACE-MH-1 interaction-0 conv_tp plan shape mismatch",
            ));
        }
        let node_count = checked_row_count(
            "interactions.0.linear_up",
            interaction_input.linear_up.len(),
            MACE_MH1_INTERACTION0_CHANNELS,
        )?;
        if edge_input.edge_src.len() != edge_input.edge_count
            || edge_input.edge_dst.len() != edge_input.edge_count
        {
            return Err(invalid(
                "MACE-MH-1 interaction-0 edge index boundary length mismatch",
            ));
        }
        if edge_input.edge_attrs.len() != edge_input.edge_count * MACE_MH1_SH_DIM {
            return Err(invalid(
                "MACE-MH-1 interaction-0 edge attribute boundary length mismatch",
            ));
        }
        if edge_mlp.conv_tp_weights.len()
            != edge_input.edge_count * MACE_MH1_INTERACTION0_TP_WEIGHT_DIM
        {
            return Err(invalid(
                "MACE-MH-1 interaction-0 TP weight boundary length mismatch",
            ));
        }
        let output_mask = self.f64_tensor(
            "interactions.0.conv_tp.output_mask",
            &[MACE_MH1_INTERACTION0_TP_OUTPUT_DIM],
        )?;
        let can_direct_scatter =
            !capture_edge_messages && output_mask.iter().all(|&mask| mask == 1.0);
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1
            && edge_input.edge_count >= MACE_MH1_CONV_TP_VJP_PARALLEL_MIN_EDGES
        {
            let (edge_messages, scatter_message) = mace_mh1_conv_tp_forward_scatter_parallel(
                "interactions.0.conv_tp",
                plan,
                MACE_MH1_INTERACTION0_CHANNELS,
                MACE_MH1_INTERACTION0_TP_OUTPUT_DIM,
                MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
                edge_input,
                &interaction_input.linear_up,
                &edge_mlp.conv_tp_weights,
                output_mask,
                node_count,
                capture_edge_messages,
                can_direct_scatter,
            )?;
            return Ok(MaceMh1Interaction0ConvTpBoundary {
                edge_messages,
                scatter_message,
                forward_cache_f32: None,
            });
        }
        let mut edge_messages = if capture_edge_messages {
            vec![0.0; edge_input.edge_count * MACE_MH1_INTERACTION0_TP_OUTPUT_DIM]
        } else {
            Vec::new()
        };
        let mut scatter_message = vec![0.0; node_count * MACE_MH1_INTERACTION0_TP_OUTPUT_DIM];
        let mut scatter_comp = if can_direct_scatter {
            Vec::new()
        } else {
            vec![0.0; scatter_message.len()]
        };
        let mut scratch_message = vec![0.0; MACE_MH1_INTERACTION0_TP_OUTPUT_DIM];
        let mut message_compensation = vec![0.0; MACE_MH1_INTERACTION0_TP_OUTPUT_DIM];
        let layouts = plan.checked_layouts()?;
        for edge in 0..edge_input.edge_count {
            let src = edge_input.edge_src[edge];
            let dst = edge_input.edge_dst[edge];
            if src >= node_count {
                return Err(invalid(format!(
                    "MACE-MH-1 edge {edge} source index {src} is out of range for {node_count} linear-up rows"
                )));
            }
            if dst >= node_count {
                return Err(invalid(format!(
                    "MACE-MH-1 edge {edge} target index {dst} is out of range for {node_count} scatter rows"
                )));
            }
            let source_row = &interaction_input.linear_up
                [src * MACE_MH1_INTERACTION0_CHANNELS..(src + 1) * MACE_MH1_INTERACTION0_CHANNELS];
            let edge_attr =
                &edge_input.edge_attrs[edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM];
            let weights = &edge_mlp.conv_tp_weights[edge * MACE_MH1_INTERACTION0_TP_WEIGHT_DIM
                ..(edge + 1) * MACE_MH1_INTERACTION0_TP_WEIGHT_DIM];
            let scatter_base = dst * MACE_MH1_INTERACTION0_TP_OUTPUT_DIM;
            if can_direct_scatter {
                let scatter_row = &mut scatter_message
                    [scatter_base..scatter_base + MACE_MH1_INTERACTION0_TP_OUTPUT_DIM];
                mace_mh1_conv_tp_forward_accumulate_interaction0_unmasked(
                    plan,
                    source_row,
                    edge_attr,
                    weights,
                    scatter_row,
                );
                continue;
            }
            let message = if capture_edge_messages {
                &mut edge_messages[edge * MACE_MH1_INTERACTION0_TP_OUTPUT_DIM
                    ..(edge + 1) * MACE_MH1_INTERACTION0_TP_OUTPUT_DIM]
            } else {
                scratch_message.fill(0.0);
                &mut scratch_message
            };
            plan.forward_accumulate_with_layouts_and_compensation(
                &layouts,
                source_row,
                edge_attr,
                Some(weights),
                message,
                &mut message_compensation,
            )?;
            for (value, &mask) in message.iter_mut().zip(output_mask) {
                *value *= mask;
            }
            for (i, &value) in message.iter().enumerate() {
                mace_mh1_kahan_add(
                    &mut scatter_message[scatter_base + i],
                    &mut scatter_comp[scatter_base + i],
                    value,
                );
            }
        }
        Ok(MaceMh1Interaction0ConvTpBoundary {
            edge_messages,
            scatter_message,
            forward_cache_f32: None,
        })
    }

    #[allow(dead_code)]
    fn interaction0_conv_tp_boundary_f32_promoted(
        &self,
        edge_input: &MaceMh1EdgeInputBoundary,
        interaction_input: &MaceMh1Interaction0InputBoundary,
        edge_mlp: &MaceMh1Interaction0EdgeMlpBoundary,
    ) -> Result<MaceMh1Interaction0ConvTpBoundary, MaceMh1Error> {
        let output_mask = self.f64_tensor(
            "interactions.0.conv_tp.output_mask",
            &[MACE_MH1_INTERACTION0_TP_OUTPUT_DIM],
        )?;
        if !output_mask.iter().all(|&mask| mask == 1.0) {
            return self.interaction0_conv_tp_boundary_with_capture(
                edge_input,
                interaction_input,
                edge_mlp,
                false,
            );
        }
        let node_count = checked_row_count(
            "interactions.0.linear_up.f32_promoted",
            interaction_input.linear_up.len(),
            MACE_MH1_INTERACTION0_CHANNELS,
        )?;
        let edge_attrs_f32 = edge_input
            .edge_attrs
            .iter()
            .map(|&value| value as f32)
            .collect::<Vec<_>>();
        let linear_up_f32_owned;
        let linear_up_f32 = if let Some(cache) = interaction_input
            .forward_cache_f32
            .as_deref()
            .filter(|cache| cache.linear_up.len() == interaction_input.linear_up.len())
        {
            cache.linear_up.as_slice()
        } else {
            linear_up_f32_owned = interaction_input
                .linear_up
                .iter()
                .map(|&value| value as f32)
                .collect::<Vec<_>>();
            &linear_up_f32_owned
        };
        let expected_weight_len = edge_input.edge_count * MACE_MH1_INTERACTION0_TP_WEIGHT_DIM;
        let conv_tp_weights_f32_owned;
        let conv_tp_weights_f32 = if let Some(cache) = edge_mlp
            .forward_cache_f32
            .as_deref()
            .filter(|cache| cache.cutoff_conv_tp_weights.len() == expected_weight_len)
        {
            cache.cutoff_conv_tp_weights.as_slice()
        } else {
            if edge_mlp.conv_tp_weights.len() != expected_weight_len {
                return Err(invalid(
                    "MACE-MH-1 interaction-0 f32 TP weight boundary length mismatch",
                ));
            }
            conv_tp_weights_f32_owned = edge_mlp
                .conv_tp_weights
                .iter()
                .map(|&value| value as f32)
                .collect::<Vec<_>>();
            &conv_tp_weights_f32_owned
        };
        let mut scatter_message_f32 =
            vec![0.0_f32; node_count * MACE_MH1_INTERACTION0_TP_OUTPUT_DIM];
        mace_mh1_conv_tp_forward_scatter_unmasked_f32(
            "interactions.0.conv_tp",
            mace_mh1_interaction0_conv_tp_plan()?,
            MACE_MH1_INTERACTION0_CHANNELS,
            MACE_MH1_INTERACTION0_TP_OUTPUT_DIM,
            MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
            &edge_input.edge_src,
            &edge_input.edge_dst,
            &edge_attrs_f32,
            linear_up_f32,
            conv_tp_weights_f32,
            node_count,
            &mut scatter_message_f32,
        )?;
        Ok(MaceMh1Interaction0ConvTpBoundary {
            edge_messages: Vec::new(),
            scatter_message: scatter_message_f32.iter().copied().map(f64::from).collect(),
            forward_cache_f32: Some(Box::new(MaceMh1ConvTpForwardCacheF32 {
                edge_attrs: edge_attrs_f32,
                linear_up: Vec::new(),
                conv_tp_weights: Vec::new(),
                scatter_message: scatter_message_f32,
            })),
        })
    }

    fn interaction0_post_scatter_boundary(
        &self,
        edge_input: &MaceMh1EdgeInputBoundary,
        interaction_input: &MaceMh1Interaction0InputBoundary,
        edge_mlp: &MaceMh1Interaction0EdgeMlpBoundary,
        conv_tp: &MaceMh1Interaction0ConvTpBoundary,
    ) -> Result<MaceMh1Interaction0PostScatterBoundary, MaceMh1Error> {
        let node_count = checked_row_count(
            "interactions.0.linear_up",
            interaction_input.linear_up.len(),
            MACE_MH1_INTERACTION0_CHANNELS,
        )?;
        if conv_tp.scatter_message.len() != node_count * MACE_MH1_INTERACTION0_TP_OUTPUT_DIM {
            return Err(invalid(
                "MACE-MH-1 interaction-0 scatter-message boundary length mismatch",
            ));
        }
        if edge_mlp.edge_density.len() != edge_input.edge_count {
            return Err(invalid(
                "MACE-MH-1 interaction-0 edge-density boundary length mismatch",
            ));
        }
        if edge_input.edge_dst.len() != edge_input.edge_count {
            return Err(invalid(
                "MACE-MH-1 interaction-0 edge-dst boundary length mismatch",
            ));
        }

        let linear_residual = self.mace_mh1_equivariant_linear_rows(
            "interactions.0.linear_res",
            &interaction_input.linear_up,
            MACE_MH1_INTERACTION0_CHANNELS,
            MACE_MH1_INTERACTION0_NONLIN_DIM,
            &mace_mh1_interaction0_linear_res_instructions(),
        )?;
        let linear_1_message = self.mace_mh1_equivariant_linear_rows(
            "interactions.0.linear_1",
            &conv_tp.scatter_message,
            MACE_MH1_INTERACTION0_TP_OUTPUT_DIM,
            MACE_MH1_INTERACTION0_NONLIN_DIM,
            &mace_mh1_interaction0_linear_1_instructions(),
        )?;

        let mut node_density = vec![0.0; node_count];
        for (edge, &density) in edge_mlp.edge_density.iter().enumerate() {
            let dst = edge_input.edge_dst[edge];
            if dst >= node_count {
                return Err(invalid(format!(
                    "MACE-MH-1 edge {edge} target index {dst} is out of range for {node_count} density rows"
                )));
            }
            node_density[dst] += density;
        }

        let trace_timings = mace_mh1_trace_timings_enabled();
        let density_start = trace_timings.then(Instant::now);
        let alpha = self.f64_scalar("interactions.0.alpha")?;
        let beta = self.f64_scalar("interactions.0.beta")?;
        let mut density_denominator = vec![0.0; node_count];
        let mut density_normalized_message = vec![0.0; linear_1_message.len()];
        let mut residual_message = vec![0.0; linear_1_message.len()];
        for node in 0..node_count {
            let denominator = node_density[node] * beta + alpha;
            density_denominator[node] = denominator;
        }
        #[cfg(feature = "parallel")]
        let used_parallel_residual = if rayon::current_num_threads() > 2 && node_count >= 16 {
            density_normalized_message
                .par_chunks_mut(MACE_MH1_INTERACTION0_NONLIN_DIM)
                .zip(residual_message.par_chunks_mut(MACE_MH1_INTERACTION0_NONLIN_DIM))
                .enumerate()
                .for_each(|(node, (normalized_row, residual_row))| {
                    let inv_denominator = 1.0 / density_denominator[node];
                    let row_start = node * MACE_MH1_INTERACTION0_NONLIN_DIM;
                    let row_end = row_start + MACE_MH1_INTERACTION0_NONLIN_DIM;
                    let linear_1_row = &linear_1_message[row_start..row_end];
                    let linear_residual_row = &linear_residual[row_start..row_end];
                    for ((normalized_dst, residual_dst), (&linear_1, &linear_residual)) in
                        normalized_row
                            .iter_mut()
                            .zip(residual_row)
                            .zip(linear_1_row.iter().zip(linear_residual_row))
                    {
                        let normalized = linear_1 * inv_denominator;
                        *normalized_dst = normalized;
                        *residual_dst = normalized + linear_residual;
                    }
                });
            true
        } else {
            false
        };
        #[cfg(not(feature = "parallel"))]
        let used_parallel_residual = false;
        if !used_parallel_residual {
            for (node, &denominator) in density_denominator.iter().enumerate().take(node_count) {
                let inv_denominator = 1.0 / denominator;
                let row_start = node * MACE_MH1_INTERACTION0_NONLIN_DIM;
                let row_end = row_start + MACE_MH1_INTERACTION0_NONLIN_DIM;
                for feature in row_start..row_end {
                    let normalized = linear_1_message[feature] * inv_denominator;
                    density_normalized_message[feature] = normalized;
                    residual_message[feature] = normalized + linear_residual[feature];
                }
            }
        }
        mace_mh1_trace_stage(
            "interactions.0.post_scatter_forward.density_residual",
            density_start,
        );

        let output_mask = self.f64_tensor(
            "interactions.0.equivariant_nonlin.mul.output_mask",
            &[MACE_MH1_INTERACTION0_OUT_DIM - MACE_MH1_INTERACTION0_RESHAPED_CHANNELS],
        )?;
        let (nonlinear_message, nonlinear_sigmoid) =
            mace_mh1_interaction_equivariant_nonlin_with_sigmoid_cache(
                &residual_message,
                output_mask,
                "interactions.0.equivariant_nonlin",
            )?;
        let linear_2_message = self.mace_mh1_equivariant_linear_rows(
            "interactions.0.linear_2",
            &nonlinear_message,
            MACE_MH1_INTERACTION0_OUT_DIM,
            MACE_MH1_INTERACTION0_OUT_DIM,
            &mace_mh1_interaction0_linear_2_instructions(),
        )?;
        let reshaped_message = mace_mh1_reshape_interaction0_message(&linear_2_message)?;

        Ok(MaceMh1Interaction0PostScatterBoundary {
            linear_residual,
            linear_1_message,
            density_denominator,
            density_normalized_message,
            residual_message,
            nonlinear_message,
            linear_2_message,
            reshaped_message,
            forward_cache: Some(Box::new(MaceMh1PostScatterForwardCache {
                nonlinear_sigmoid,
            })),
            forward_cache_f32: None,
        })
    }

    fn interaction0_post_scatter_boundary_f32_promoted(
        &self,
        edge_input: &MaceMh1EdgeInputBoundary,
        interaction_input: &MaceMh1Interaction0InputBoundary,
        edge_mlp: &MaceMh1Interaction0EdgeMlpBoundary,
        conv_tp: &MaceMh1Interaction0ConvTpBoundary,
    ) -> Result<MaceMh1Interaction0PostScatterBoundary, MaceMh1Error> {
        let parts = self.post_scatter_boundary_f32_promoted(
            "interactions.0",
            MACE_MH1_INTERACTION0_CHANNELS,
            MACE_MH1_INTERACTION0_TP_OUTPUT_DIM,
            edge_input,
            conv_tp.forward_cache_f32.as_deref(),
            edge_mlp.forward_cache_f32.as_deref(),
            interaction_input
                .forward_cache_f32
                .as_deref()
                .map(|cache| cache.linear_up.as_slice()),
            &interaction_input.linear_up,
            &edge_mlp.edge_density,
            &conv_tp.scatter_message,
            &mace_mh1_interaction0_linear_res_instructions(),
            &mace_mh1_interaction0_linear_1_instructions(),
            &mace_mh1_interaction0_linear_2_instructions(),
        )?;
        Ok(MaceMh1Interaction0PostScatterBoundary {
            linear_residual: parts.linear_residual,
            linear_1_message: parts.linear_1_message,
            density_denominator: parts.density_denominator,
            density_normalized_message: parts.density_normalized_message,
            residual_message: parts.residual_message,
            nonlinear_message: parts.nonlinear_message,
            linear_2_message: parts.linear_2_message,
            reshaped_message: parts.reshaped_message,
            forward_cache: None,
            forward_cache_f32: parts.forward_cache,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn post_scatter_boundary_f32_promoted(
        &self,
        prefix: &str,
        linear_up_dim: usize,
        scatter_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        conv_tp_forward_cache: Option<&MaceMh1ConvTpForwardCacheF32>,
        edge_mlp_forward_cache: Option<&MaceMh1EdgeMlpForwardCacheF32>,
        linear_up_cache_f32: Option<&[f32]>,
        linear_up: &[f64],
        edge_density: &[f64],
        scatter_message: &[f64],
        linear_res_instructions: &[MaceMh1EquivariantLinearInstruction],
        linear_1_instructions: &[MaceMh1EquivariantLinearInstruction],
        linear_2_instructions: &[MaceMh1EquivariantLinearInstruction],
    ) -> Result<MaceMh1PostScatterF32PromotedParts, MaceMh1Error> {
        debug_assert_eq!(
            MACE_MH1_INTERACTION0_NONLIN_DIM, MACE_MH1_INTERACTION1_NONLIN_DIM,
            "shared MACE-MH-1 f32 post-scatter helper assumes equal nonlinear dims"
        );
        debug_assert_eq!(
            MACE_MH1_INTERACTION0_OUT_DIM, MACE_MH1_INTERACTION1_OUT_DIM,
            "shared MACE-MH-1 f32 post-scatter helper assumes equal output dims"
        );
        debug_assert_eq!(
            MACE_MH1_INTERACTION0_RESHAPED_CHANNELS, MACE_MH1_INTERACTION1_RESHAPED_CHANNELS,
            "shared MACE-MH-1 f32 post-scatter helper assumes equal reshaped channels"
        );
        debug_assert_eq!(
            MACE_MH1_INTERACTION0_RESHAPED_COMPONENTS, MACE_MH1_SH_DIM,
            "shared MACE-MH-1 f32 post-scatter helper assumes interaction-0 reshapes over SH components"
        );
        let node_count = checked_row_count(
            &format!("{prefix}.linear_up.f32_promoted"),
            linear_up.len(),
            linear_up_dim,
        )?;
        if scatter_message.len() != node_count * scatter_dim {
            return Err(invalid(format!(
                "{prefix} f32 scatter-message length {} does not match node_count {node_count} * scatter_dim {scatter_dim}",
                scatter_message.len()
            )));
        }
        let edge_density_len = edge_mlp_forward_cache
            .map_or(edge_density.len(), |cache| cache.cutoff_edge_density.len());
        if edge_density_len != edge_input.edge_count {
            return Err(invalid(format!(
                "{prefix} f32 edge-density length {} does not match edge_count {}",
                edge_density_len, edge_input.edge_count
            )));
        }
        if edge_input.edge_dst.len() != edge_input.edge_count {
            return Err(invalid(format!(
                "{prefix} f32 edge-dst length {} does not match edge_count {}",
                edge_input.edge_dst.len(),
                edge_input.edge_count
            )));
        }

        let linear_up_f32_owned;
        let linear_up_f32 = if let Some(cache) =
            linear_up_cache_f32.filter(|cache| cache.len() == linear_up.len())
        {
            cache
        } else if let Some(cache) =
            conv_tp_forward_cache.filter(|cache| cache.linear_up.len() == linear_up.len())
        {
            cache.linear_up.as_slice()
        } else {
            linear_up_f32_owned = linear_up
                .iter()
                .map(|&value| value as f32)
                .collect::<Vec<_>>();
            &linear_up_f32_owned
        };
        let scatter_message_f32_owned;
        let scatter_message_f32 = if let Some(cache) = conv_tp_forward_cache
            .filter(|cache| cache.scatter_message.len() == scatter_message.len())
        {
            cache.scatter_message.as_slice()
        } else {
            scatter_message_f32_owned = scatter_message
                .iter()
                .map(|&value| value as f32)
                .collect::<Vec<_>>();
            &scatter_message_f32_owned
        };
        let edge_density_f32_owned;
        let edge_density_f32 = if let Some(cache) = edge_mlp_forward_cache
            .filter(|cache| cache.cutoff_edge_density.len() == edge_input.edge_count)
        {
            cache.cutoff_edge_density.as_slice()
        } else {
            if edge_density.len() != edge_input.edge_count {
                return Err(invalid(format!(
                    "{prefix} f32 edge-density sidecar length {} does not match edge_count {}",
                    edge_density.len(),
                    edge_input.edge_count
                )));
            }
            edge_density_f32_owned = edge_density
                .iter()
                .map(|&value| value as f32)
                .collect::<Vec<_>>();
            &edge_density_f32_owned
        };

        let trace_timings = mace_mh1_trace_timings_enabled();
        let linear_res_job = || {
            let stage_start = trace_timings.then(Instant::now);
            let result = self.mace_mh1_equivariant_linear_rows_f32(
                &format!("{prefix}.linear_res"),
                linear_up_f32,
                linear_up_dim,
                MACE_MH1_INTERACTION0_NONLIN_DIM,
                linear_res_instructions,
            );
            mace_mh1_trace_stage(
                &format!("{prefix}.post_scatter_forward.linear_res"),
                stage_start,
            );
            result
        };
        let linear_1_job = || {
            let stage_start = trace_timings.then(Instant::now);
            let result = self.mace_mh1_equivariant_linear_rows_f32(
                &format!("{prefix}.linear_1"),
                scatter_message_f32,
                scatter_dim,
                MACE_MH1_INTERACTION0_NONLIN_DIM,
                linear_1_instructions,
            );
            mace_mh1_trace_stage(
                &format!("{prefix}.post_scatter_forward.linear_1"),
                stage_start,
            );
            result
        };
        #[cfg(feature = "parallel")]
        let (linear_residual_f32, linear_1_message_f32) = if rayon::current_num_threads() > 2 {
            let stage_start = trace_timings.then(Instant::now);
            let (linear_res_result, linear_1_result) = rayon::join(linear_res_job, linear_1_job);
            let result = (linear_res_result?, linear_1_result?);
            mace_mh1_trace_stage(
                &format!("{prefix}.post_scatter_forward.parallel_linear01"),
                stage_start,
            );
            result
        } else {
            (linear_res_job()?, linear_1_job()?)
        };
        #[cfg(not(feature = "parallel"))]
        let (linear_residual_f32, linear_1_message_f32) = (linear_res_job()?, linear_1_job()?);

        let density_start = trace_timings.then(Instant::now);
        let mut node_density = vec![0.0_f32; node_count];
        for (edge, &density) in edge_density_f32.iter().enumerate() {
            let dst = edge_input.edge_dst[edge];
            if dst >= node_count {
                return Err(invalid(format!(
                    "{prefix} f32 edge {edge} target index {dst} is out of range for {node_count} density rows"
                )));
            }
            node_density[dst] += density;
        }

        let alpha = self.f32_scalar(&format!("{prefix}.alpha"))?;
        let beta = self.f32_scalar(&format!("{prefix}.beta"))?;
        let mut density_denominator_f32 = vec![0.0_f32; node_count];
        let mut residual_message_f32 = vec![0.0_f32; linear_1_message_f32.len()];
        for node in 0..node_count {
            let denominator = node_density[node] * beta + alpha;
            density_denominator_f32[node] = denominator;
        }
        #[cfg(feature = "parallel")]
        let used_parallel_residual = if rayon::current_num_threads() > 2 && node_count >= 16 {
            residual_message_f32
                .par_chunks_mut(MACE_MH1_INTERACTION0_NONLIN_DIM)
                .enumerate()
                .for_each(|(node, residual_row)| {
                    let denominator = density_denominator_f32[node];
                    let row_start = node * MACE_MH1_INTERACTION0_NONLIN_DIM;
                    let row_end = row_start + MACE_MH1_INTERACTION0_NONLIN_DIM;
                    let linear_1_row = &linear_1_message_f32[row_start..row_end];
                    let linear_residual_row = &linear_residual_f32[row_start..row_end];
                    for ((dst, &linear_1), &linear_residual) in residual_row
                        .iter_mut()
                        .zip(linear_1_row)
                        .zip(linear_residual_row)
                    {
                        *dst = linear_1 / denominator + linear_residual;
                    }
                });
            true
        } else {
            false
        };
        #[cfg(not(feature = "parallel"))]
        let used_parallel_residual = false;
        if !used_parallel_residual {
            for (node, &denominator) in density_denominator_f32.iter().enumerate().take(node_count)
            {
                let row_start = node * MACE_MH1_INTERACTION0_NONLIN_DIM;
                let row_end = row_start + MACE_MH1_INTERACTION0_NONLIN_DIM;
                for feature in row_start..row_end {
                    residual_message_f32[feature] =
                        linear_1_message_f32[feature] / denominator + linear_residual_f32[feature];
                }
            }
        }
        mace_mh1_trace_stage(
            &format!("{prefix}.post_scatter_forward.density_residual"),
            density_start,
        );

        let output_mask = self.f32_tensor(
            &format!("{prefix}.equivariant_nonlin.mul.output_mask"),
            &[MACE_MH1_INTERACTION0_OUT_DIM - MACE_MH1_INTERACTION0_RESHAPED_CHANNELS],
        )?;
        let nonlin_start = trace_timings.then(Instant::now);
        let (nonlinear_message_f32, nonlinear_sigmoid_f32) =
            mace_mh1_interaction_equivariant_nonlin_f32_with_sigmoid_cache(
                &residual_message_f32,
                output_mask,
                &format!("{prefix}.equivariant_nonlin.f32_promoted"),
            )?;
        mace_mh1_trace_stage(
            &format!("{prefix}.post_scatter_forward.nonlin"),
            nonlin_start,
        );
        let linear_2_start = trace_timings.then(Instant::now);
        let linear_2_message_f32 = self.mace_mh1_equivariant_linear_rows_f32(
            &format!("{prefix}.linear_2"),
            &nonlinear_message_f32,
            MACE_MH1_INTERACTION0_OUT_DIM,
            MACE_MH1_INTERACTION0_OUT_DIM,
            linear_2_instructions,
        )?;
        mace_mh1_trace_stage(
            &format!("{prefix}.post_scatter_forward.linear_2"),
            linear_2_start,
        );
        let reshape_start = trace_timings.then(Instant::now);
        let reshaped_message_f32 = mace_mh1_reshape_interaction_message_f32(
            &linear_2_message_f32,
            &format!("{prefix}.reshape.f32_promoted"),
        )?;
        mace_mh1_trace_stage(
            &format!("{prefix}.post_scatter_forward.reshape"),
            reshape_start,
        );

        Ok(MaceMh1PostScatterF32PromotedParts {
            linear_residual: Vec::new(),
            linear_1_message: Vec::new(),
            density_denominator: Vec::new(),
            density_normalized_message: Vec::new(),
            residual_message: Vec::new(),
            nonlinear_message: Vec::new(),
            linear_2_message: Vec::new(),
            reshaped_message: Vec::new(),
            forward_cache: Some(Box::new(MaceMh1PostScatterForwardCacheF32 {
                linear_1_message: linear_1_message_f32,
                density_denominator: density_denominator_f32,
                residual_message: residual_message_f32,
                nonlinear_sigmoid: nonlinear_sigmoid_f32,
                reshaped_message: reshaped_message_f32,
            })),
        })
    }

    fn interaction0_product0_boundary(
        &self,
        post_scatter: &MaceMh1Interaction0PostScatterBoundary,
        interaction_input: &MaceMh1Interaction0InputBoundary,
    ) -> Result<MaceMh1Product0Boundary, MaceMh1Error> {
        let node_count = checked_row_count(
            "products.0.symmetric_contractions input",
            post_scatter.reshaped_message.len(),
            MACE_MH1_INTERACTION0_RESHAPED_CHANNELS * MACE_MH1_INTERACTION0_RESHAPED_COMPONENTS,
        )?;
        if interaction_input.skip_connection.len() != node_count * MACE_MH1_PRODUCT0_OUT_DIM {
            return Err(invalid(
                "MACE-MH-1 product0 skip-connection boundary length mismatch",
            ));
        }

        let node_attrs_used = vec![1.0; node_count * MACE_MH1_PRODUCT0_NODE_ATTR_DIM];
        let mut symmetric_contractions = vec![0.0; node_count * MACE_MH1_PRODUCT0_OUT_DIM];
        if Self::use_parallel_prepared_product_plan(node_count) {
            self.product0_prepared_plan()?
                .forward(&post_scatter.reshaped_message, &mut symmetric_contractions)?;
        } else {
            self.product0_symmetric_contraction()?.forward(
                &post_scatter.reshaped_message,
                &node_attrs_used,
                &mut symmetric_contractions,
            )?;
        }

        let linear_output = self.mace_mh1_equivariant_linear_rows(
            "products.0.linear",
            &symmetric_contractions,
            MACE_MH1_PRODUCT0_OUT_DIM,
            MACE_MH1_PRODUCT0_OUT_DIM,
            &mace_mh1_product0_linear_instructions(),
        )?;
        let mut output = linear_output.clone();
        for (out, &skip) in output.iter_mut().zip(&interaction_input.skip_connection) {
            *out += skip;
        }
        let readout0_full = self.mace_mh1_equivariant_linear_rows(
            "readouts.0.linear",
            &output,
            MACE_MH1_PRODUCT0_OUT_DIM,
            MACE_MH1_NUM_HEADS,
            &mace_mh1_readout0_linear_instructions(),
        )?;

        Ok(MaceMh1Product0Boundary {
            node_attrs_used,
            symmetric_contractions,
            linear_output,
            output,
            readout0_full,
            forward_cache_f32: None,
        })
    }

    #[allow(dead_code)]
    fn interaction0_product0_boundary_f32_promoted(
        &self,
        post_scatter: &MaceMh1Interaction0PostScatterBoundary,
        interaction_input: &MaceMh1Interaction0InputBoundary,
    ) -> Result<MaceMh1Product0Boundary, MaceMh1Error> {
        self.interaction0_product0_boundary_f32_promoted_with_sidecars(
            post_scatter,
            interaction_input,
            true,
        )
    }

    fn interaction0_product0_boundary_f32_promoted_with_sidecars(
        &self,
        post_scatter: &MaceMh1Interaction0PostScatterBoundary,
        interaction_input: &MaceMh1Interaction0InputBoundary,
        materialize_f64_sidecars: bool,
    ) -> Result<MaceMh1Product0Boundary, MaceMh1Error> {
        let node_count = checked_row_count(
            "products.0.f32 symmetric_contractions input",
            post_scatter.reshaped_message_len(),
            MACE_MH1_INTERACTION0_RESHAPED_CHANNELS * MACE_MH1_INTERACTION0_RESHAPED_COMPONENTS,
        )?;
        if interaction_input.skip_connection.len() != node_count * MACE_MH1_PRODUCT0_OUT_DIM {
            return Err(invalid(
                "MACE-MH-1 product0 f32 skip-connection boundary length mismatch",
            ));
        }

        let reshaped_f32_owned;
        let reshaped_f32 = if let Some(cache) = post_scatter
            .forward_cache_f32
            .as_deref()
            .filter(|cache| cache.reshaped_message.len() == post_scatter.reshaped_message_len())
        {
            cache.reshaped_message.as_slice()
        } else {
            reshaped_f32_owned = post_scatter
                .reshaped_message
                .iter()
                .map(|&value| value as f32)
                .collect::<Vec<_>>();
            &reshaped_f32_owned
        };
        let node_attrs_used = vec![1.0; node_count * MACE_MH1_PRODUCT0_NODE_ATTR_DIM];
        let mut symmetric_contractions_f32 = vec![0.0_f32; node_count * MACE_MH1_PRODUCT0_OUT_DIM];
        self.product0_prepared_plan()?
            .forward_f32(reshaped_f32, &mut symmetric_contractions_f32)?;

        let linear_output_f32 = self.mace_mh1_equivariant_linear_rows_f32(
            "products.0.linear",
            &symmetric_contractions_f32,
            MACE_MH1_PRODUCT0_OUT_DIM,
            MACE_MH1_PRODUCT0_OUT_DIM,
            &mace_mh1_product0_linear_instructions(),
        )?;
        let skip_connection_f32_owned;
        let skip_connection_f32 = if let Some(cache) = interaction_input
            .forward_cache_f32
            .as_deref()
            .filter(|cache| cache.skip_connection.len() == interaction_input.skip_connection.len())
        {
            cache.skip_connection.as_slice()
        } else {
            skip_connection_f32_owned = interaction_input
                .skip_connection
                .iter()
                .map(|&value| value as f32)
                .collect::<Vec<_>>();
            &skip_connection_f32_owned
        };
        let mut output_f32 = linear_output_f32.clone();
        for (out, &skip) in output_f32.iter_mut().zip(skip_connection_f32) {
            *out += skip;
        }
        let readout0_full_f32 = self.mace_mh1_equivariant_linear_rows_f32(
            "readouts.0.linear",
            &output_f32,
            MACE_MH1_PRODUCT0_OUT_DIM,
            MACE_MH1_NUM_HEADS,
            &mace_mh1_readout0_linear_instructions(),
        )?;
        let symmetric_contractions_len = symmetric_contractions_f32.len();
        let linear_output_len = linear_output_f32.len();
        let output_len = output_f32.len();
        let readout0_full_len = readout0_full_f32.len();

        let symmetric_contractions = if materialize_f64_sidecars {
            symmetric_contractions_f32
                .iter()
                .copied()
                .map(f64::from)
                .collect()
        } else {
            vec![0.0; symmetric_contractions_len]
        };
        let linear_output = if materialize_f64_sidecars {
            linear_output_f32.iter().copied().map(f64::from).collect()
        } else {
            vec![0.0; linear_output_len]
        };
        let output = if materialize_f64_sidecars {
            output_f32.iter().copied().map(f64::from).collect()
        } else {
            vec![0.0; output_len]
        };
        let readout0_full = if materialize_f64_sidecars {
            readout0_full_f32.iter().copied().map(f64::from).collect()
        } else {
            vec![0.0; readout0_full_len]
        };

        Ok(MaceMh1Product0Boundary {
            node_attrs_used,
            symmetric_contractions,
            linear_output,
            output,
            readout0_full,
            forward_cache_f32: Some(Box::new(MaceMh1Product0ForwardCacheF32 {
                output: output_f32,
                readout0_full: readout0_full_f32,
            })),
        })
    }

