    #[allow(dead_code)]
    fn interaction1_edge_mlp_boundary(
        &self,
        edge_input: &MaceMh1EdgeInputBoundary,
        interaction_input: &MaceMh1Interaction1InputBoundary,
    ) -> Result<MaceMh1Interaction1EdgeMlpBoundary, MaceMh1Error> {
        self.interaction1_edge_mlp_boundary_with_forward_cache(edge_input, interaction_input, true)
    }

    fn interaction1_edge_mlp_boundary_with_forward_cache(
        &self,
        edge_input: &MaceMh1EdgeInputBoundary,
        interaction_input: &MaceMh1Interaction1InputBoundary,
        capture_forward_cache: bool,
    ) -> Result<MaceMh1Interaction1EdgeMlpBoundary, MaceMh1Error> {
        let source_rows = checked_row_count(
            "interactions.1.source_embedding",
            interaction_input.source_embedding.len(),
            MACE_MH1_NODE_CHANNELS,
        )?;
        let target_rows = checked_row_count(
            "interactions.1.target_embedding",
            interaction_input.target_embedding.len(),
            MACE_MH1_NODE_CHANNELS,
        )?;
        if edge_input.edge_src.len() != edge_input.edge_count {
            return Err(invalid(format!(
                "MACE-MH-1 edge_src length {} does not match edge_count {}",
                edge_input.edge_src.len(),
                edge_input.edge_count
            )));
        }
        if edge_input.edge_dst.len() != edge_input.edge_count {
            return Err(invalid(format!(
                "MACE-MH-1 edge_dst length {} does not match edge_count {}",
                edge_input.edge_dst.len(),
                edge_input.edge_count
            )));
        }
        if edge_input.edge_feats.len() != edge_input.edge_count * MACE_MH1_NUM_BESSEL {
            return Err(invalid(format!(
                "MACE-MH-1 edge_feats length {} does not match edge_count {} and feature dim {}",
                edge_input.edge_feats.len(),
                edge_input.edge_count,
                MACE_MH1_NUM_BESSEL
            )));
        }
        if edge_input.edge_cutoff.len() != edge_input.edge_count {
            return Err(invalid(format!(
                "MACE-MH-1 edge_cutoff length {} does not match edge_count {}",
                edge_input.edge_cutoff.len(),
                edge_input.edge_count
            )));
        }
        let mut augmented =
            vec![0.0; edge_input.edge_count * MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM];
        for edge in 0..edge_input.edge_count {
            let src = edge_input.edge_src[edge];
            let dst = edge_input.edge_dst[edge];
            if src >= source_rows {
                return Err(invalid(format!(
                    "MACE-MH-1 edge {edge} source index {src} is out of range for {source_rows} interaction-1 source rows"
                )));
            }
            if dst >= target_rows {
                return Err(invalid(format!(
                    "MACE-MH-1 edge {edge} target index {dst} is out of range for {target_rows} interaction-1 target rows"
                )));
            }
            let augmented_row = &mut augmented[edge * MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM
                ..(edge + 1) * MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM];
            augmented_row[..MACE_MH1_NUM_BESSEL].copy_from_slice(
                &edge_input.edge_feats
                    [edge * MACE_MH1_NUM_BESSEL..(edge + 1) * MACE_MH1_NUM_BESSEL],
            );
            let source_offset = MACE_MH1_NUM_BESSEL;
            augmented_row[source_offset..source_offset + MACE_MH1_NODE_CHANNELS].copy_from_slice(
                &interaction_input.source_embedding
                    [src * MACE_MH1_NODE_CHANNELS..(src + 1) * MACE_MH1_NODE_CHANNELS],
            );
            let target_offset = source_offset + MACE_MH1_NODE_CHANNELS;
            augmented_row[target_offset..target_offset + MACE_MH1_NODE_CHANNELS].copy_from_slice(
                &interaction_input.target_embedding
                    [dst * MACE_MH1_NODE_CHANNELS..(dst + 1) * MACE_MH1_NODE_CHANNELS],
            );
        }
        let capture_forward_cache = capture_forward_cache
            && edge_input.edge_count <= MACE_MH1_EDGE_MLP_FORWARD_CACHE_MAX_EDGES;
        let (mut conv_tp_weights, conv_tp_weights_cache) = if capture_forward_cache {
            self.interaction1_conv_tp_weights_with_cache(&augmented)?
        } else {
            (self.interaction1_conv_tp_weights(&augmented)?, None)
        };
        mace_mh1_scale_rows_by_cutoff_f64(
            edge_input.edge_count,
            MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
            &edge_input.edge_cutoff,
            &mut conv_tp_weights,
        );
        let (mut edge_density, density_cache) = if capture_forward_cache {
            self.interaction1_edge_density_with_cache(&augmented)?
        } else {
            (self.interaction1_edge_density(&augmented)?, None)
        };
        for (value, &cutoff) in edge_density.iter_mut().zip(&edge_input.edge_cutoff) {
            *value *= cutoff;
        }
        let forward_cache = match (conv_tp_weights_cache, density_cache) {
            (Some(conv_tp_weights), Some(density)) => Some(Box::new(MaceMh1EdgeMlpForwardCache {
                conv_tp_weights,
                density,
            })),
            _ => None,
        };
        Ok(MaceMh1Interaction1EdgeMlpBoundary {
            augmented_edge_feats: augmented,
            conv_tp_weights,
            edge_density,
            forward_cache,
            forward_cache_f32: None,
        })
    }

    fn interaction1_conv_tp_weights(&self, augmented: &[f64]) -> Result<Vec<f64>, MaceMh1Error> {
        let prefix = "interactions.1.conv_tp_weights.net";
        let mut rows = self.torch_linear_rows(
            &format!("{prefix}.0"),
            augmented,
            MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
        )?;
        rows = self.layer_norm_rows(
            &format!("{prefix}.1"),
            &rows,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
        )?;
        apply_silu(&mut rows);
        rows = self.torch_linear_rows(
            &format!("{prefix}.3"),
            &rows,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
        )?;
        rows = self.layer_norm_rows(
            &format!("{prefix}.4"),
            &rows,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
        )?;
        apply_silu(&mut rows);
        rows = self.torch_linear_rows(
            &format!("{prefix}.6"),
            &rows,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
        )?;
        rows = self.layer_norm_rows(
            &format!("{prefix}.7"),
            &rows,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
        )?;
        apply_silu(&mut rows);
        self.torch_linear_rows(
            &format!("{prefix}.9"),
            &rows,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
            MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
        )
    }

    fn interaction1_conv_tp_weights_with_cache(
        &self,
        augmented: &[f64],
    ) -> Result<(Vec<f64>, Option<MaceMh1EdgeMlpConvTpWeightsCache>), MaceMh1Error> {
        self.edge_mlp_conv_tp_weights_forward_with_cache(
            "interactions.1.conv_tp_weights.net",
            augmented,
            MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
            MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
        )
    }

    fn interaction1_edge_density(&self, augmented: &[f64]) -> Result<Vec<f64>, MaceMh1Error> {
        let prefix = "interactions.1.density_fn.net";
        let mut rows = self.torch_linear_rows(
            &format!("{prefix}.0"),
            augmented,
            MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
        )?;
        rows = self.layer_norm_rows(
            &format!("{prefix}.1"),
            &rows,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
        )?;
        apply_silu(&mut rows);
        let raw = self.torch_linear_rows(
            &format!("{prefix}.3"),
            &rows,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
            1,
        )?;
        Ok(raw.iter().map(|value| (value * value).tanh()).collect())
    }

    fn interaction1_edge_density_with_cache(
        &self,
        augmented: &[f64],
    ) -> Result<(Vec<f64>, Option<MaceMh1EdgeMlpDensityCache>), MaceMh1Error> {
        self.edge_mlp_density_forward_with_cache(
            "interactions.1.density_fn.net",
            augmented,
            MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
        )
    }

