    fn one_hot_embedding(
        &self,
        prefix: &str,
        type_ids: &[usize],
        out_dim: usize,
    ) -> Result<Vec<f64>, MaceMh1Error> {
        let weights =
            self.f64_tensor(&format!("{prefix}.weight"), &[MACE_MH1_NUM_TYPES * out_dim])?;
        let output_mask = self.f64_tensor(&format!("{prefix}.output_mask"), &[out_dim])?;
        let path_weight = 1.0 / (MACE_MH1_NUM_TYPES as f64).sqrt();
        let mut output = vec![0.0; type_ids.len() * out_dim];
        for (node, &type_id) in type_ids.iter().enumerate() {
            if type_id >= MACE_MH1_NUM_TYPES {
                return Err(invalid(format!(
                    "MACE-MH-1 type id {type_id} is out of range"
                )));
            }
            let weight_row = &weights[type_id * out_dim..(type_id + 1) * out_dim];
            let output_row = &mut output[node * out_dim..(node + 1) * out_dim];
            for ((out, &weight), &mask) in output_row.iter_mut().zip(weight_row).zip(output_mask) {
                *out = weight * path_weight * mask;
            }
        }
        Ok(output)
    }

