    fn masked_linear_rows(
        &self,
        prefix: &str,
        input: &[f64],
        input_dim: usize,
        output_dim: usize,
    ) -> Result<Vec<f64>, MaceMh1Error> {
        if !input.len().is_multiple_of(input_dim) {
            return Err(invalid(format!(
                "{prefix} input length {} is not divisible by input_dim {input_dim}",
                input.len()
            )));
        }
        let rows = input.len() / input_dim;
        let weights = self.f64_tensor(&format!("{prefix}.weight"), &[input_dim * output_dim])?;
        let output_mask = self.f64_tensor(&format!("{prefix}.output_mask"), &[output_dim])?;
        let path_weight = 1.0 / (input_dim as f64).sqrt();
        let mut output = vec![0.0; rows * output_dim];

        #[cfg(any(
            all(feature = "accelerate-blas", target_os = "macos"),
            all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
            all(
                feature = "openblas",
                target_os = "linux",
                any(target_arch = "x86_64", target_arch = "aarch64")
            )
        ))]
        {
            blas_backend::dense_forward(input, rows, input_dim, weights, &mut output, path_weight);
            for output_row in output.chunks_exact_mut(output_dim) {
                for (value, &mask) in output_row.iter_mut().zip(output_mask) {
                    *value *= mask;
                }
            }
        }

        #[cfg(not(any(
            all(feature = "accelerate-blas", target_os = "macos"),
            all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
            all(
                feature = "openblas",
                target_os = "linux",
                any(target_arch = "x86_64", target_arch = "aarch64")
            )
        )))]
        {
            for row in 0..rows {
                let input_row = &input[row * input_dim..(row + 1) * input_dim];
                let output_row = &mut output[row * output_dim..(row + 1) * output_dim];
                for out_feature in 0..output_dim {
                    let mut value = 0.0;
                    for (in_feature, &input_value) in input_row.iter().enumerate() {
                        value += input_value * weights[in_feature * output_dim + out_feature];
                    }
                    output_row[out_feature] = value * path_weight * output_mask[out_feature];
                }
            }
        }
        Ok(output)
    }

