    #[allow(dead_code)]
    fn product0_output_vjp_to_interaction0_edges(
        &self,
        forward: &MaceMh1ForwardCache,
        bar_product0_output: &[f64],
        bar_interaction0_linear_up: &mut [f64],
        bar_conv_tp0_scatter_message: &mut [f64],
        bar_edge_mlp0_edge_density: &mut [f64],
    ) -> Result<(), MaceMh1Error> {
        let product0_tail =
            self.product0_output_vjp_to_post_scatter0_tail(forward, bar_product0_output)?;

        let bar_edge_density = self.post_scatter_layer_vjp(
            "interactions.0",
            MACE_MH1_INTERACTION0_CHANNELS,
            MACE_MH1_INTERACTION0_TP_OUTPUT_DIM,
            &mace_mh1_interaction0_linear_res_instructions(),
            &mace_mh1_interaction0_linear_1_instructions(),
            &forward.edge_boundary.edge_dst,
            forward.edge_boundary.edge_count,
            &forward.post_scatter0.linear_1_message,
            &forward.post_scatter0.density_denominator,
            &product0_tail.bar_post_scatter0_residual_message,
            bar_interaction0_linear_up,
            bar_conv_tp0_scatter_message,
        )?;
        for (dst, src) in bar_edge_mlp0_edge_density.iter_mut().zip(bar_edge_density) {
            *dst += src;
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn conv_tp_layer_vjp(
        &self,
        prefix: &str,
        plan: &TensorProductPlan,
        specialization: MaceMh1ConvTpSpecialization,
        linear_up_dim: usize,
        tp_output_dim: usize,
        tp_weight_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        linear_up: &[f64],
        conv_tp_weights: &[f64],
        bar_scatter_message: &[f64],
        bar_linear_up: &mut [f64],
        bar_edge_attrs: &mut [f64],
        bar_conv_tp_weights: &mut [f64],
    ) -> Result<(), MaceMh1Error> {
        let node_count = checked_row_count(
            &format!("{prefix}.linear_up.vjp"),
            linear_up.len(),
            linear_up_dim,
        )?;
        if edge_input.edge_src.len() != edge_input.edge_count
            || edge_input.edge_dst.len() != edge_input.edge_count
        {
            return Err(invalid(format!("{prefix} edge index length mismatch")));
        }
        if edge_input.edge_attrs.len() != edge_input.edge_count * MACE_MH1_SH_DIM {
            return Err(invalid(format!("{prefix} edge_attrs length mismatch")));
        }
        if conv_tp_weights.len() != edge_input.edge_count * tp_weight_dim {
            return Err(invalid(format!("{prefix} conv_tp_weights length mismatch")));
        }
        if bar_scatter_message.len() != node_count * tp_output_dim {
            return Err(invalid(format!(
                "{prefix} bar_scatter_message length {} does not match node_count {node_count} * tp_output_dim {tp_output_dim}",
                bar_scatter_message.len()
            )));
        }
        if bar_linear_up.len() != linear_up.len() {
            return Err(invalid(format!("{prefix} bar_linear_up length mismatch")));
        }
        if bar_edge_attrs.len() != edge_input.edge_attrs.len() {
            return Err(invalid(format!("{prefix} bar_edge_attrs length mismatch")));
        }
        if bar_conv_tp_weights.len() != conv_tp_weights.len() {
            return Err(invalid(format!(
                "{prefix} bar_conv_tp_weights length mismatch"
            )));
        }
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1
            && edge_input.edge_count >= MACE_MH1_CONV_TP_VJP_PARALLEL_MIN_EDGES
        {
            return self.conv_tp_layer_vjp_parallel(
                prefix,
                plan,
                specialization,
                linear_up_dim,
                tp_output_dim,
                tp_weight_dim,
                edge_input,
                linear_up,
                conv_tp_weights,
                bar_scatter_message,
                bar_linear_up,
                bar_edge_attrs,
                bar_conv_tp_weights,
            );
        }
        let output_mask = self.f64_tensor(&format!("{prefix}.output_mask"), &[tp_output_dim])?;
        let output_mask_all_one = output_mask.iter().all(|&mask| mask == 1.0);
        let unmasked_kernel = if output_mask_all_one {
            Some(mace_mh1_conv_tp_vjp_kernel_for(specialization)?)
        } else {
            None
        };
        let layouts = if !output_mask_all_one
            || matches!(unmasked_kernel, Some(MaceMh1ConvTpVjpKernel::Generic))
        {
            Some(plan.checked_layouts()?)
        } else {
            None
        };
        let mut bar_source = vec![0.0; linear_up_dim];
        let mut bar_edge_attr = vec![0.0; MACE_MH1_SH_DIM];
        let mut bar_source_comp = vec![0.0; linear_up_dim];
        let mut bar_edge_attr_comp = vec![0.0; MACE_MH1_SH_DIM];
        let mut bar_linear_up_comp = vec![0.0; bar_linear_up.len()];
        for edge in 0..edge_input.edge_count {
            let src = edge_input.edge_src[edge];
            let dst = edge_input.edge_dst[edge];
            if src >= node_count || dst >= node_count {
                return Err(invalid(format!(
                    "{prefix} edge {edge} index {src}->{dst} is out of range for {node_count} nodes"
                )));
            }
            let source_row = &linear_up[src * linear_up_dim..(src + 1) * linear_up_dim];
            let edge_attr =
                &edge_input.edge_attrs[edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM];
            let weights = &conv_tp_weights[edge * tp_weight_dim..(edge + 1) * tp_weight_dim];
            let scatter_bar = &bar_scatter_message[dst * tp_output_dim..(dst + 1) * tp_output_dim];
            bar_source.fill(0.0);
            bar_edge_attr.fill(0.0);
            let bar_weight_row =
                &mut bar_conv_tp_weights[edge * tp_weight_dim..(edge + 1) * tp_weight_dim];
            if let Some(kernel) = unmasked_kernel {
                match kernel {
                    MaceMh1ConvTpVjpKernel::Interaction0Direct => {
                        mace_mh1_conv_tp_vjp_from_scatter_bar_interaction0_direct(
                            source_row,
                            edge_attr,
                            weights,
                            scatter_bar,
                            &mut bar_source,
                            &mut bar_edge_attr,
                            bar_weight_row,
                        );
                    }
                    MaceMh1ConvTpVjpKernel::Prepared(prepared) => {
                        mace_mh1_conv_tp_vjp_from_scatter_bar_prepared(
                            prepared,
                            source_row,
                            edge_attr,
                            weights,
                            scatter_bar,
                            &mut bar_source,
                            &mut bar_edge_attr,
                            bar_weight_row,
                        );
                    }
                    MaceMh1ConvTpVjpKernel::Generic => {
                        let Some(layouts) = layouts.as_ref() else {
                            return Err(invalid(format!(
                                "{prefix} generic Conv-TP VJP layouts were not prepared"
                            )));
                        };
                        mace_mh1_conv_tp_vjp_from_scatter_bar_unmasked_fast(
                            plan,
                            layouts,
                            source_row,
                            edge_attr,
                            weights,
                            scatter_bar,
                            &mut bar_source,
                            &mut bar_edge_attr,
                            bar_weight_row,
                        );
                    }
                }
            } else {
                let Some(layouts) = layouts.as_ref() else {
                    return Err(invalid(format!(
                        "{prefix} masked Conv-TP VJP layouts were not prepared"
                    )));
                };
                mace_mh1_conv_tp_vjp_from_scatter_bar_masked(
                    plan,
                    layouts,
                    source_row,
                    edge_attr,
                    weights,
                    scatter_bar,
                    output_mask,
                    &mut bar_source,
                    &mut bar_edge_attr,
                    bar_weight_row,
                    &mut bar_source_comp,
                    &mut bar_edge_attr_comp,
                );
            }
            let lu_base = src * linear_up_dim;
            for (i, &source_bar) in bar_source.iter().enumerate() {
                mace_mh1_kahan_add(
                    &mut bar_linear_up[lu_base + i],
                    &mut bar_linear_up_comp[lu_base + i],
                    source_bar,
                );
            }
            let bar_edge_attr_row =
                &mut bar_edge_attrs[edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM];
            for (dst_value, &attr_bar) in bar_edge_attr_row.iter_mut().zip(&bar_edge_attr) {
                *dst_value += attr_bar;
            }
        }
        Ok(())
    }

    #[allow(dead_code, clippy::too_many_arguments)]
    fn conv_tp_layer_vjp_f32_promoted(
        &self,
        prefix: &str,
        plan: &TensorProductPlan,
        specialization: MaceMh1ConvTpSpecialization,
        linear_up_dim: usize,
        tp_output_dim: usize,
        tp_weight_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        linear_up: &[f64],
        conv_tp_weights: &[f64],
        bar_scatter_message: &[f64],
        bar_linear_up: &mut [f64],
        bar_edge_attrs: &mut [f64],
        bar_conv_tp_weights: &mut [f64],
    ) -> Result<(), MaceMh1Error> {
        let mut bar_linear_up_f32 = vec![0.0_f32; bar_linear_up.len()];
        let mut bar_edge_attrs_f32 = vec![0.0_f32; bar_edge_attrs.len()];
        let mut bar_conv_tp_weights_f32 = vec![0.0_f32; bar_conv_tp_weights.len()];
        let bar_scatter_message_f32 = bar_scatter_message
            .iter()
            .map(|&value| value as f32)
            .collect::<Vec<_>>();
        self.conv_tp_layer_vjp_f32_raw(
            prefix,
            plan,
            specialization,
            linear_up_dim,
            tp_output_dim,
            tp_weight_dim,
            edge_input,
            None,
            None,
            None,
            linear_up,
            conv_tp_weights,
            &bar_scatter_message_f32,
            &mut bar_linear_up_f32,
            &mut bar_edge_attrs_f32,
            &mut bar_conv_tp_weights_f32,
        )?;
        for (dst, src) in bar_linear_up.iter_mut().zip(bar_linear_up_f32) {
            *dst += f64::from(src);
        }
        for (dst, src) in bar_edge_attrs.iter_mut().zip(bar_edge_attrs_f32) {
            *dst += f64::from(src);
        }
        for (dst, src) in bar_conv_tp_weights.iter_mut().zip(bar_conv_tp_weights_f32) {
            *dst += f64::from(src);
        }
        Ok(())
    }

    #[allow(dead_code, clippy::too_many_arguments)]
    fn conv_tp_layer_vjp_f32_raw(
        &self,
        prefix: &str,
        plan: &TensorProductPlan,
        specialization: MaceMh1ConvTpSpecialization,
        linear_up_dim: usize,
        tp_output_dim: usize,
        tp_weight_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        forward_cache: Option<&MaceMh1ConvTpForwardCacheF32>,
        linear_up_cache_f32: Option<&[f32]>,
        conv_tp_weights_cache_f32: Option<&[f32]>,
        linear_up: &[f64],
        conv_tp_weights: &[f64],
        bar_scatter_message: &[f32],
        bar_linear_up: &mut [f32],
        bar_edge_attrs: &mut [f32],
        bar_conv_tp_weights: &mut [f32],
    ) -> Result<(), MaceMh1Error> {
        let node_count = checked_row_count(
            &format!("{prefix}.linear_up.f32_promoted_vjp"),
            linear_up.len(),
            linear_up_dim,
        )?;
        if bar_linear_up.len() != linear_up.len() {
            return Err(invalid(format!(
                "{prefix}.f32_promoted bar_linear_up length mismatch"
            )));
        }
        if bar_edge_attrs.len() != edge_input.edge_attrs.len() {
            return Err(invalid(format!(
                "{prefix}.f32_promoted bar_edge_attrs length mismatch"
            )));
        }
        let expected_conv_tp_weights_len = conv_tp_weights_cache_f32
            .map(|cache| cache.len())
            .or_else(|| {
                forward_cache
                    .map(|cache| cache.conv_tp_weights.len())
                    .filter(|&len| len != 0)
            })
            .unwrap_or(conv_tp_weights.len());
        if expected_conv_tp_weights_len != edge_input.edge_count * tp_weight_dim {
            return Err(invalid(format!(
                "{prefix}.f32_promoted conv_tp_weights length mismatch"
            )));
        }
        if bar_conv_tp_weights.len() != expected_conv_tp_weights_len {
            return Err(invalid(format!(
                "{prefix}.f32_promoted bar_conv_tp_weights length mismatch"
            )));
        }

        let output_mask = self.f64_tensor(&format!("{prefix}.output_mask"), &[tp_output_dim])?;
        if !output_mask.iter().all(|&mask| mask == 1.0) {
            let bar_scatter_message_f64 = bar_scatter_message
                .iter()
                .map(|&value| f64::from(value))
                .collect::<Vec<_>>();
            let mut local_bar_linear_up = vec![0.0; linear_up.len()];
            let mut local_bar_edge_attrs = vec![0.0; edge_input.edge_attrs.len()];
            let mut local_bar_conv_tp_weights = vec![0.0; expected_conv_tp_weights_len];
            if conv_tp_weights.len() != expected_conv_tp_weights_len {
                return Err(invalid(format!(
                    "{prefix}.f32_promoted f64 fallback conv_tp_weights length mismatch"
                )));
            }
            self.conv_tp_layer_vjp(
                prefix,
                plan,
                specialization,
                linear_up_dim,
                tp_output_dim,
                tp_weight_dim,
                edge_input,
                linear_up,
                conv_tp_weights,
                &bar_scatter_message_f64,
                &mut local_bar_linear_up,
                &mut local_bar_edge_attrs,
                &mut local_bar_conv_tp_weights,
            )?;
            for (dst, src) in bar_linear_up.iter_mut().zip(local_bar_linear_up) {
                *dst += src as f32;
            }
            for (dst, src) in bar_edge_attrs.iter_mut().zip(local_bar_edge_attrs) {
                *dst += src as f32;
            }
            for (dst, src) in bar_conv_tp_weights
                .iter_mut()
                .zip(local_bar_conv_tp_weights)
            {
                *dst += src as f32;
            }
            return Ok(());
        }
        if bar_scatter_message.len() != node_count * tp_output_dim {
            return Err(invalid(format!(
                "{prefix}.f32_promoted bar_scatter_message length {} does not match node_count {node_count} * tp_output_dim {tp_output_dim}",
                bar_scatter_message.len()
            )));
        }

        let edge_attrs_f32_owned;
        let edge_attrs_f32 = if let Some(cache) =
            forward_cache.filter(|cache| cache.edge_attrs.len() == edge_input.edge_attrs.len())
        {
            cache.edge_attrs.as_slice()
        } else {
            edge_attrs_f32_owned = edge_input
                .edge_attrs
                .iter()
                .map(|&value| value as f32)
                .collect::<Vec<_>>();
            &edge_attrs_f32_owned
        };
        let linear_up_f32_owned;
        let linear_up_f32 = if let Some(cache) =
            linear_up_cache_f32.filter(|cache| cache.len() == linear_up.len())
        {
            cache
        } else if let Some(cache) =
            forward_cache.filter(|cache| cache.linear_up.len() == linear_up.len())
        {
            cache.linear_up.as_slice()
        } else {
            linear_up_f32_owned = linear_up
                .iter()
                .map(|&value| value as f32)
                .collect::<Vec<_>>();
            &linear_up_f32_owned
        };
        let conv_tp_weights_f32_owned;
        let conv_tp_weights_f32 = if let Some(cache) =
            conv_tp_weights_cache_f32.filter(|cache| cache.len() == expected_conv_tp_weights_len)
        {
            cache
        } else if let Some(cache) = forward_cache
            .filter(|cache| cache.conv_tp_weights.len() == expected_conv_tp_weights_len)
        {
            cache.conv_tp_weights.as_slice()
        } else {
            if conv_tp_weights.len() != expected_conv_tp_weights_len {
                return Err(invalid(format!(
                    "{prefix}.f32_promoted conv_tp_weights sidecar length mismatch"
                )));
            }
            conv_tp_weights_f32_owned = conv_tp_weights
                .iter()
                .map(|&value| value as f32)
                .collect::<Vec<_>>();
            &conv_tp_weights_f32_owned
        };

        mace_mh1_conv_tp_vjp_from_scatter_bar_unmasked_f32(
            prefix,
            specialization,
            plan,
            linear_up_dim,
            tp_output_dim,
            tp_weight_dim,
            &edge_input.edge_src,
            &edge_input.edge_dst,
            edge_attrs_f32,
            linear_up_f32,
            conv_tp_weights_f32,
            bar_scatter_message,
            node_count,
            bar_linear_up,
            bar_edge_attrs,
            bar_conv_tp_weights,
        )?;

        Ok(())
    }

    #[cfg(feature = "parallel")]
    #[allow(clippy::too_many_arguments)]
    fn conv_tp_layer_vjp_parallel(
        &self,
        prefix: &str,
        plan: &TensorProductPlan,
        specialization: MaceMh1ConvTpSpecialization,
        linear_up_dim: usize,
        tp_output_dim: usize,
        tp_weight_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        linear_up: &[f64],
        conv_tp_weights: &[f64],
        bar_scatter_message: &[f64],
        bar_linear_up: &mut [f64],
        bar_edge_attrs: &mut [f64],
        bar_conv_tp_weights: &mut [f64],
    ) -> Result<(), MaceMh1Error> {
        let node_count = linear_up.len() / linear_up_dim;
        let output_mask = self.f64_tensor(&format!("{prefix}.output_mask"), &[tp_output_dim])?;
        let output_mask_all_one = output_mask.iter().all(|&mask| mask == 1.0);
        let unmasked_kernel = if output_mask_all_one {
            Some(mace_mh1_conv_tp_vjp_kernel_for(specialization)?)
        } else {
            None
        };
        let layouts = if !output_mask_all_one
            || matches!(unmasked_kernel, Some(MaceMh1ConvTpVjpKernel::Generic))
        {
            Some(plan.checked_layouts()?)
        } else {
            None
        };
        let target_chunks = rayon::current_num_threads().max(1);
        let chunk_len = edge_input.edge_count.div_ceil(target_chunks).max(1);
        let ranges = (0..edge_input.edge_count)
            .step_by(chunk_len)
            .map(|start| (start, (start + chunk_len).min(edge_input.edge_count)))
            .collect::<Vec<_>>();

        let partials = ranges
            .into_par_iter()
            .map(
                |(edge_start, edge_end)| -> Result<MaceMh1ConvTpLayerVjpChunk, MaceMh1Error> {
                    let edge_len = edge_end - edge_start;
                    let mut local_bar_linear_up = vec![0.0; linear_up.len()];
                    let mut local_bar_edge_attrs = vec![0.0; edge_len * MACE_MH1_SH_DIM];
                    let mut local_bar_conv_tp_weights = vec![0.0; edge_len * tp_weight_dim];
                    let mut bar_source = vec![0.0; linear_up_dim];
                    let mut bar_edge_attr = vec![0.0; MACE_MH1_SH_DIM];
                    let mut bar_source_comp = vec![0.0; linear_up_dim];
                    let mut bar_edge_attr_comp = vec![0.0; MACE_MH1_SH_DIM];

                    for edge in edge_start..edge_end {
                        let src = edge_input.edge_src[edge];
                        let dst = edge_input.edge_dst[edge];
                        if src >= node_count || dst >= node_count {
                            return Err(invalid(format!(
                                "{prefix} edge {edge} index {src}->{dst} is out of range for {node_count} nodes"
                            )));
                        }
                        let source_row =
                            &linear_up[src * linear_up_dim..(src + 1) * linear_up_dim];
                        let edge_attr = &edge_input.edge_attrs
                            [edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM];
                        let weights =
                            &conv_tp_weights[edge * tp_weight_dim..(edge + 1) * tp_weight_dim];
                        let scatter_bar =
                            &bar_scatter_message[dst * tp_output_dim..(dst + 1) * tp_output_dim];
                        bar_source.fill(0.0);
                        bar_edge_attr.fill(0.0);
                        let local_edge = edge - edge_start;
                        let bar_weight_row = &mut local_bar_conv_tp_weights
                            [local_edge * tp_weight_dim..(local_edge + 1) * tp_weight_dim];
                        if let Some(kernel) = unmasked_kernel {
                            match kernel {
                                MaceMh1ConvTpVjpKernel::Interaction0Direct => {
                                    mace_mh1_conv_tp_vjp_from_scatter_bar_interaction0_direct(
                                        source_row,
                                        edge_attr,
                                        weights,
                                        scatter_bar,
                                        &mut bar_source,
                                        &mut bar_edge_attr,
                                        bar_weight_row,
                                    );
                                }
                                MaceMh1ConvTpVjpKernel::Prepared(prepared) => {
                                    mace_mh1_conv_tp_vjp_from_scatter_bar_prepared(
                                        prepared,
                                        source_row,
                                        edge_attr,
                                        weights,
                                        scatter_bar,
                                        &mut bar_source,
                                        &mut bar_edge_attr,
                                        bar_weight_row,
                                    );
                                }
                                MaceMh1ConvTpVjpKernel::Generic => {
                                    let Some(layouts) = layouts.as_ref() else {
                                        return Err(invalid(format!(
                                            "{prefix} generic Conv-TP VJP layouts were not prepared"
                                        )));
                                    };
                                    mace_mh1_conv_tp_vjp_from_scatter_bar_unmasked_fast(
                                        plan,
                                        layouts,
                                        source_row,
                                        edge_attr,
                                        weights,
                                        scatter_bar,
                                        &mut bar_source,
                                        &mut bar_edge_attr,
                                        bar_weight_row,
                                    );
                                }
                            }
                        } else {
                            let Some(layouts) = layouts.as_ref() else {
                                return Err(invalid(format!(
                                    "{prefix} masked Conv-TP VJP layouts were not prepared"
                                )));
                            };
                            mace_mh1_conv_tp_vjp_from_scatter_bar_masked(
                                plan,
                                layouts,
                                source_row,
                                edge_attr,
                                weights,
                                scatter_bar,
                                output_mask,
                                &mut bar_source,
                                &mut bar_edge_attr,
                                bar_weight_row,
                                &mut bar_source_comp,
                                &mut bar_edge_attr_comp,
                            );
                        }
                        let local_bar_linear_up_row = &mut local_bar_linear_up
                            [src * linear_up_dim..(src + 1) * linear_up_dim];
                        for (dst_value, &source_bar) in
                            local_bar_linear_up_row.iter_mut().zip(&bar_source)
                        {
                            *dst_value += source_bar;
                        }
                        let local_bar_edge_attr_row = &mut local_bar_edge_attrs
                            [local_edge * MACE_MH1_SH_DIM..(local_edge + 1) * MACE_MH1_SH_DIM];
                        for (dst_value, &attr_bar) in
                            local_bar_edge_attr_row.iter_mut().zip(&bar_edge_attr)
                        {
                            *dst_value += attr_bar;
                        }
                    }

                    Ok(MaceMh1ConvTpLayerVjpChunk {
                        edge_start,
                        edge_end,
                        bar_linear_up: local_bar_linear_up,
                        bar_edge_attrs: local_bar_edge_attrs,
                        bar_conv_tp_weights: local_bar_conv_tp_weights,
                    })
                },
            )
            .collect::<Result<Vec<_>, MaceMh1Error>>()?;

        let mut bar_lu_comp = vec![0.0; bar_linear_up.len()];
        for partial in partials {
            for (i, src) in partial.bar_linear_up.into_iter().enumerate() {
                mace_mh1_kahan_add(&mut bar_linear_up[i], &mut bar_lu_comp[i], src);
            }
            let edge_attr_start = partial.edge_start * MACE_MH1_SH_DIM;
            let edge_attr_end = partial.edge_end * MACE_MH1_SH_DIM;
            for (dst, src) in bar_edge_attrs[edge_attr_start..edge_attr_end]
                .iter_mut()
                .zip(partial.bar_edge_attrs)
            {
                *dst += src;
            }
            let weight_start = partial.edge_start * tp_weight_dim;
            let weight_end = partial.edge_end * tp_weight_dim;
            for (dst, src) in bar_conv_tp_weights[weight_start..weight_end]
                .iter_mut()
                .zip(partial.bar_conv_tp_weights)
            {
                *dst += src;
            }
        }

        Ok(())
    }

