    fn edge_mlp_vjp_from_conv_tp(
        &self,
        forward: &MaceMh1ForwardCache,
        conv_tp: MaceMh1ConvTpVjp,
    ) -> Result<MaceMh1EdgeMlpVjp, MaceMh1Error> {
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1
            && forward.edge_boundary.edge_count >= MACE_MH1_EDGE_INPUT_PARALLEL_MIN_EDGES
        {
            return self.edge_mlp_vjp_from_conv_tp_parallel(forward, conv_tp);
        }

        let mut bar_edge_feats = vec![0.0; forward.edge_boundary.edge_feats.len()];
        let mut bar_edge_cutoff = vec![0.0; forward.edge_boundary.edge_cutoff.len()];

        let mut bar_edge_mlp0_augmented_edge_feats =
            vec![0.0; forward.edge_mlp0.augmented_edge_feats_len()];
        self.edge_mlp_layer_vjp(
            "interactions.0",
            MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
            MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM,
            MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
            &forward.edge_boundary,
            &forward.edge_mlp0.augmented_edge_feats,
            &forward.edge_mlp0.conv_tp_weights,
            &forward.edge_mlp0.edge_density,
            forward.edge_mlp0.forward_cache.as_deref(),
            &conv_tp.bar_edge_mlp0_conv_tp_weights,
            &conv_tp.post_scatter.bar_edge_mlp0_edge_density,
            &mut bar_edge_cutoff,
            &mut bar_edge_mlp0_augmented_edge_feats,
        )?;
        let mut bar_interaction0_source_embedding =
            vec![0.0; forward.interaction0.source_embedding.len()];
        let mut bar_interaction0_target_embedding =
            vec![0.0; forward.interaction0.target_embedding.len()];
        decompose_edge_mlp_augmented_bars(
            "interactions.0.edge_mlp.vjp",
            MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
            &forward.edge_boundary,
            &bar_edge_mlp0_augmented_edge_feats,
            &mut bar_edge_feats,
            &mut bar_interaction0_source_embedding,
            &mut bar_interaction0_target_embedding,
        )?;

        let mut bar_edge_mlp1_augmented_edge_feats =
            vec![0.0; forward.edge_mlp1.augmented_edge_feats_len()];
        self.edge_mlp_layer_vjp(
            "interactions.1",
            MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
            MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
            &forward.edge_boundary,
            &forward.edge_mlp1.augmented_edge_feats,
            &forward.edge_mlp1.conv_tp_weights,
            &forward.edge_mlp1.edge_density,
            forward.edge_mlp1.forward_cache.as_deref(),
            &conv_tp.bar_edge_mlp1_conv_tp_weights,
            &conv_tp.post_scatter.bar_edge_mlp1_edge_density,
            &mut bar_edge_cutoff,
            &mut bar_edge_mlp1_augmented_edge_feats,
        )?;
        let mut bar_interaction1_source_embedding =
            vec![0.0; forward.interaction1.source_embedding.len()];
        let mut bar_interaction1_target_embedding =
            vec![0.0; forward.interaction1.target_embedding.len()];
        decompose_edge_mlp_augmented_bars(
            "interactions.1.edge_mlp.vjp",
            MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
            &forward.edge_boundary,
            &bar_edge_mlp1_augmented_edge_feats,
            &mut bar_edge_feats,
            &mut bar_interaction1_source_embedding,
            &mut bar_interaction1_target_embedding,
        )?;

        Ok(MaceMh1EdgeMlpVjp {
            conv_tp,
            bar_edge_feats,
            bar_edge_cutoff,
            bar_edge_mlp0_augmented_edge_feats,
            bar_interaction0_source_embedding,
            bar_interaction0_target_embedding,
            bar_edge_mlp1_augmented_edge_feats,
            bar_interaction1_source_embedding,
            bar_interaction1_target_embedding,
        })
    }

    fn edge_mlp_vjp_from_conv_tp_force_bridge(
        &self,
        forward: &MaceMh1ForwardCache,
        conv_tp: MaceMh1ConvTpVjp,
    ) -> Result<MaceMh1EdgeMlpVjp, MaceMh1Error> {
        let trace_timings = mace_mh1_trace_timings_enabled();
        let total_start = trace_timings.then(Instant::now);
        #[cfg(feature = "parallel")]
        let use_parallel_layers = rayon::current_num_threads() > 1
            && forward.edge_boundary.edge_count >= MACE_MH1_EDGE_INPUT_PARALLEL_MIN_EDGES;
        #[cfg(feature = "parallel")]
        let (layer0, layer1) = if use_parallel_layers {
            let (layer0, layer1) = rayon::join(
                || {
                    self.edge_mlp_layer_vjp_and_decompose_force_bridge(
                        "interactions.0",
                        MaceMh1EdgeMlpDims {
                            input_dim: MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
                            hidden_dim: MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM,
                            tp_weight_dim: MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
                        },
                        &forward.edge_boundary,
                        &forward.edge_mlp0.augmented_edge_feats,
                        &forward.edge_mlp0.conv_tp_weights,
                        &forward.edge_mlp0.edge_density,
                        forward.edge_mlp0.forward_cache.as_deref(),
                        &conv_tp.bar_edge_mlp0_conv_tp_weights,
                        &conv_tp.post_scatter.bar_edge_mlp0_edge_density,
                    )
                },
                || {
                    self.edge_mlp_layer_vjp_and_decompose_force_bridge(
                        "interactions.1",
                        MaceMh1EdgeMlpDims {
                            input_dim: MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
                            hidden_dim: MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
                            tp_weight_dim: MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
                        },
                        &forward.edge_boundary,
                        &forward.edge_mlp1.augmented_edge_feats,
                        &forward.edge_mlp1.conv_tp_weights,
                        &forward.edge_mlp1.edge_density,
                        forward.edge_mlp1.forward_cache.as_deref(),
                        &conv_tp.bar_edge_mlp1_conv_tp_weights,
                        &conv_tp.post_scatter.bar_edge_mlp1_edge_density,
                    )
                },
            );
            (layer0?, layer1?)
        } else {
            let mut stage_start = trace_timings.then(Instant::now);
            let layer0 = self.edge_mlp_layer_vjp_and_decompose_force_bridge(
                "interactions.0",
                MaceMh1EdgeMlpDims {
                    input_dim: MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
                    hidden_dim: MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM,
                    tp_weight_dim: MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
                },
                &forward.edge_boundary,
                &forward.edge_mlp0.augmented_edge_feats,
                &forward.edge_mlp0.conv_tp_weights,
                &forward.edge_mlp0.edge_density,
                forward.edge_mlp0.forward_cache.as_deref(),
                &conv_tp.bar_edge_mlp0_conv_tp_weights,
                &conv_tp.post_scatter.bar_edge_mlp0_edge_density,
            )?;
            mace_mh1_trace_stage("edge_mlp_bridge.layer0_vjp", stage_start);
            stage_start = trace_timings.then(Instant::now);
            let layer1 = self.edge_mlp_layer_vjp_and_decompose_force_bridge(
                "interactions.1",
                MaceMh1EdgeMlpDims {
                    input_dim: MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
                    hidden_dim: MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
                    tp_weight_dim: MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
                },
                &forward.edge_boundary,
                &forward.edge_mlp1.augmented_edge_feats,
                &forward.edge_mlp1.conv_tp_weights,
                &forward.edge_mlp1.edge_density,
                forward.edge_mlp1.forward_cache.as_deref(),
                &conv_tp.bar_edge_mlp1_conv_tp_weights,
                &conv_tp.post_scatter.bar_edge_mlp1_edge_density,
            )?;
            mace_mh1_trace_stage("edge_mlp_bridge.layer1_vjp", stage_start);
            (layer0, layer1)
        };
        #[cfg(not(feature = "parallel"))]
        let (layer0, layer1) = {
            let mut stage_start = trace_timings.then(Instant::now);
            let layer0 = self.edge_mlp_layer_vjp_and_decompose_force_bridge(
                "interactions.0",
                MaceMh1EdgeMlpDims {
                    input_dim: MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
                    hidden_dim: MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM,
                    tp_weight_dim: MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
                },
                &forward.edge_boundary,
                &forward.edge_mlp0.augmented_edge_feats,
                &forward.edge_mlp0.conv_tp_weights,
                &forward.edge_mlp0.edge_density,
                forward.edge_mlp0.forward_cache.as_deref(),
                &conv_tp.bar_edge_mlp0_conv_tp_weights,
                &conv_tp.post_scatter.bar_edge_mlp0_edge_density,
            )?;
            mace_mh1_trace_stage("edge_mlp_bridge.layer0_vjp", stage_start);
            stage_start = trace_timings.then(Instant::now);
            let layer1 = self.edge_mlp_layer_vjp_and_decompose_force_bridge(
                "interactions.1",
                MaceMh1EdgeMlpDims {
                    input_dim: MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
                    hidden_dim: MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
                    tp_weight_dim: MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
                },
                &forward.edge_boundary,
                &forward.edge_mlp1.augmented_edge_feats,
                &forward.edge_mlp1.conv_tp_weights,
                &forward.edge_mlp1.edge_density,
                forward.edge_mlp1.forward_cache.as_deref(),
                &conv_tp.bar_edge_mlp1_conv_tp_weights,
                &conv_tp.post_scatter.bar_edge_mlp1_edge_density,
            )?;
            mace_mh1_trace_stage("edge_mlp_bridge.layer1_vjp", stage_start);
            (layer0, layer1)
        };

        let combine_start = trace_timings.then(Instant::now);
        let mut bar_edge_feats = layer0.bar_edge_feats;
        for (dst, src) in bar_edge_feats.iter_mut().zip(&layer1.bar_edge_feats) {
            *dst += src;
        }
        let mut bar_edge_cutoff = layer0.bar_edge_cutoff;
        for (dst, src) in bar_edge_cutoff.iter_mut().zip(&layer1.bar_edge_cutoff) {
            *dst += src;
        }
        mace_mh1_trace_stage("edge_mlp_bridge.combine", combine_start);
        mace_mh1_trace_stage("edge_mlp_bridge.total", total_start);

        Ok(MaceMh1EdgeMlpVjp {
            conv_tp,
            bar_edge_feats,
            bar_edge_cutoff,
            bar_edge_mlp0_augmented_edge_feats: Vec::new(),
            bar_interaction0_source_embedding: Vec::new(),
            bar_interaction0_target_embedding: Vec::new(),
            bar_edge_mlp1_augmented_edge_feats: Vec::new(),
            bar_interaction1_source_embedding: Vec::new(),
            bar_interaction1_target_embedding: Vec::new(),
        })
    }

