    #[allow(dead_code)]
    fn edge_mlp_vjp_from_conv_tp_f32_bridge(
        &self,
        forward: &MaceMh1ForwardCache,
        conv_tp: MaceMh1ConvTpVjpF32Bridge,
    ) -> Result<MaceMh1EdgeMlpForceVjpF32Bridge, MaceMh1Error> {
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1
            && forward.edge_boundary.edge_count >= MACE_MH1_EDGE_INPUT_PARALLEL_MIN_EDGES
        {
            return self.edge_mlp_vjp_from_conv_tp_parallel_f32_bridge(forward, conv_tp);
        }

        let trace_timings = mace_mh1_trace_timings_enabled();
        let total_start = trace_timings.then(Instant::now);

        #[cfg(feature = "parallel")]
        if let (Some(cache0), Some(cache1)) = (
            forward
                .edge_mlp0
                .forward_cache_f32
                .as_deref()
                .filter(|_| !forward.edge_boundary.edge_cutoff.contains(&0.0)),
            forward
                .edge_mlp1
                .forward_cache_f32
                .as_deref()
                .filter(|_| !forward.edge_boundary.edge_cutoff.contains(&0.0)),
        ) {
            let mut stage_start = trace_timings.then(Instant::now);
            let layer0 = self.edge_mlp_layer_vjp_and_decompose_f32_bridge_radial_cached(
                "interactions.0",
                MaceMh1EdgeMlpDims {
                    input_dim: MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
                    hidden_dim: MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM,
                    tp_weight_dim: MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
                },
                &forward.edge_boundary,
                cache0,
                &conv_tp.bar_edge_mlp0_conv_tp_weights,
                &conv_tp.bar_edge_mlp0_edge_density,
            )?;
            mace_mh1_trace_stage("edge_mlp_bridge.layer0_radial_cached", stage_start);
            stage_start = trace_timings.then(Instant::now);
            let layer1 = self.edge_mlp_layer_vjp_and_decompose_f32_bridge_radial_cached(
                "interactions.1",
                MaceMh1EdgeMlpDims {
                    input_dim: MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
                    hidden_dim: MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
                    tp_weight_dim: MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
                },
                &forward.edge_boundary,
                cache1,
                &conv_tp.bar_edge_mlp1_conv_tp_weights,
                &conv_tp.bar_edge_mlp1_edge_density,
            )?;
            mace_mh1_trace_stage("edge_mlp_bridge.layer1_radial_cached", stage_start);

            let combine_start = trace_timings.then(Instant::now);
            let mut bar_edge_feats = layer0.bar_edge_feats;
            for (dst, src) in bar_edge_feats.iter_mut().zip(layer1.bar_edge_feats) {
                *dst += src;
            }
            let mut bar_edge_cutoff = layer0.bar_edge_cutoff;
            for (dst, src) in bar_edge_cutoff.iter_mut().zip(layer1.bar_edge_cutoff) {
                *dst += src;
            }
            mace_mh1_trace_stage("edge_mlp_bridge.radial_cached_combine", combine_start);
            mace_mh1_trace_stage("edge_mlp_bridge.total", total_start);

            return Ok(MaceMh1EdgeMlpForceVjpF32Bridge {
                conv_tp,
                bar_edge_feats,
                bar_edge_cutoff,
            });
        }

        let mut bar_edge_feats = vec![0.0_f32; forward.edge_boundary.edge_feats.len()];
        let mut bar_edge_cutoff = vec![0.0_f32; forward.edge_boundary.edge_cutoff.len()];

        let mut bar_edge_mlp0_augmented_edge_feats =
            vec![0.0_f32; forward.edge_mlp0.augmented_edge_feats_len()];
        let mut stage_start = trace_timings.then(Instant::now);
        self.edge_mlp_layer_vjp_f32_bridge(
            "interactions.0",
            MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
            MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM,
            MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
            &forward.edge_boundary,
            &forward.edge_mlp0.augmented_edge_feats,
            &forward.edge_mlp0.conv_tp_weights,
            &forward.edge_mlp0.edge_density,
            forward.edge_mlp0.forward_cache_f32.as_deref(),
            &conv_tp.bar_edge_mlp0_conv_tp_weights,
            &conv_tp.bar_edge_mlp0_edge_density,
            &mut bar_edge_cutoff,
            &mut bar_edge_mlp0_augmented_edge_feats,
        )?;
        mace_mh1_trace_stage("edge_mlp_bridge.layer0_vjp", stage_start);
        stage_start = trace_timings.then(Instant::now);
        decompose_edge_mlp_augmented_bars_f32_radial_only(
            "interactions.0.edge_mlp.f32_bridge_vjp",
            MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
            &forward.edge_boundary,
            &bar_edge_mlp0_augmented_edge_feats,
            &mut bar_edge_feats,
        )?;
        mace_mh1_trace_stage("edge_mlp_bridge.layer0_decompose", stage_start);

        let mut bar_edge_mlp1_augmented_edge_feats =
            vec![0.0_f32; forward.edge_mlp1.augmented_edge_feats_len()];
        stage_start = trace_timings.then(Instant::now);
        self.edge_mlp_layer_vjp_f32_bridge(
            "interactions.1",
            MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
            MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
            MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
            &forward.edge_boundary,
            &forward.edge_mlp1.augmented_edge_feats,
            &forward.edge_mlp1.conv_tp_weights,
            &forward.edge_mlp1.edge_density,
            forward.edge_mlp1.forward_cache_f32.as_deref(),
            &conv_tp.bar_edge_mlp1_conv_tp_weights,
            &conv_tp.bar_edge_mlp1_edge_density,
            &mut bar_edge_cutoff,
            &mut bar_edge_mlp1_augmented_edge_feats,
        )?;
        mace_mh1_trace_stage("edge_mlp_bridge.layer1_vjp", stage_start);
        stage_start = trace_timings.then(Instant::now);
        decompose_edge_mlp_augmented_bars_f32_radial_only(
            "interactions.1.edge_mlp.f32_bridge_vjp",
            MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
            &forward.edge_boundary,
            &bar_edge_mlp1_augmented_edge_feats,
            &mut bar_edge_feats,
        )?;
        mace_mh1_trace_stage("edge_mlp_bridge.layer1_decompose", stage_start);
        mace_mh1_trace_stage("edge_mlp_bridge.total", total_start);

        Ok(MaceMh1EdgeMlpForceVjpF32Bridge {
            conv_tp,
            bar_edge_feats,
            bar_edge_cutoff,
        })
    }

    #[cfg(feature = "parallel")]
    fn edge_mlp_vjp_from_conv_tp_parallel(
        &self,
        forward: &MaceMh1ForwardCache,
        conv_tp: MaceMh1ConvTpVjp,
    ) -> Result<MaceMh1EdgeMlpVjp, MaceMh1Error> {
        let (layer0, layer1) = rayon::join(
            || {
                self.edge_mlp_layer_vjp_and_decompose(
                    "interactions.0",
                    MaceMh1EdgeMlpDims {
                        input_dim: MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
                        hidden_dim: MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM,
                        tp_weight_dim: MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
                    },
                    &forward.edge_boundary,
                    forward.interaction0.source_embedding.len(),
                    forward.interaction0.target_embedding.len(),
                    &forward.edge_mlp0.augmented_edge_feats,
                    &forward.edge_mlp0.conv_tp_weights,
                    &forward.edge_mlp0.edge_density,
                    forward.edge_mlp0.forward_cache.as_deref(),
                    &conv_tp.bar_edge_mlp0_conv_tp_weights,
                    &conv_tp.post_scatter.bar_edge_mlp0_edge_density,
                )
            },
            || {
                self.edge_mlp_layer_vjp_and_decompose(
                    "interactions.1",
                    MaceMh1EdgeMlpDims {
                        input_dim: MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
                        hidden_dim: MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
                        tp_weight_dim: MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
                    },
                    &forward.edge_boundary,
                    forward.interaction1.source_embedding.len(),
                    forward.interaction1.target_embedding.len(),
                    &forward.edge_mlp1.augmented_edge_feats,
                    &forward.edge_mlp1.conv_tp_weights,
                    &forward.edge_mlp1.edge_density,
                    forward.edge_mlp1.forward_cache.as_deref(),
                    &conv_tp.bar_edge_mlp1_conv_tp_weights,
                    &conv_tp.post_scatter.bar_edge_mlp1_edge_density,
                )
            },
        );
        let layer0 = layer0?;
        let layer1 = layer1?;

        let mut bar_edge_feats = layer0.bar_edge_feats;
        for (dst, src) in bar_edge_feats.iter_mut().zip(&layer1.bar_edge_feats) {
            *dst += src;
        }
        let mut bar_edge_cutoff = layer0.bar_edge_cutoff;
        for (dst, src) in bar_edge_cutoff.iter_mut().zip(&layer1.bar_edge_cutoff) {
            *dst += src;
        }

        Ok(MaceMh1EdgeMlpVjp {
            conv_tp,
            bar_edge_feats,
            bar_edge_cutoff,
            bar_edge_mlp0_augmented_edge_feats: layer0.bar_augmented_edge_feats,
            bar_interaction0_source_embedding: layer0.bar_source_embedding,
            bar_interaction0_target_embedding: layer0.bar_target_embedding,
            bar_edge_mlp1_augmented_edge_feats: layer1.bar_augmented_edge_feats,
            bar_interaction1_source_embedding: layer1.bar_source_embedding,
            bar_interaction1_target_embedding: layer1.bar_target_embedding,
        })
    }

