    #[cfg(feature = "parallel")]
    fn edge_mlp_vjp_from_conv_tp_parallel_f32_bridge(
        &self,
        forward: &MaceMh1ForwardCache,
        conv_tp: MaceMh1ConvTpVjpF32Bridge,
    ) -> Result<MaceMh1EdgeMlpForceVjpF32Bridge, MaceMh1Error> {
        let trace_timings = mace_mh1_trace_timings_enabled();
        let total_start = trace_timings.then(Instant::now);
        let (layer0, layer1) = rayon::join(
            || {
                let stage_start = trace_timings.then(Instant::now);
                let result = self.edge_mlp_layer_vjp_and_decompose_f32_bridge(
                    "interactions.0",
                    MaceMh1EdgeMlpDims {
                        input_dim: MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
                        hidden_dim: MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM,
                        tp_weight_dim: MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
                    },
                    &forward.edge_boundary,
                    &forward.edge_mlp0.augmented_edge_feats,
                    &forward.edge_mlp0.conv_tp_weights,
                    &forward.edge_mlp0.edge_density,
                    forward.edge_mlp0.forward_cache_f32.as_deref(),
                    &conv_tp.bar_edge_mlp0_conv_tp_weights,
                    &conv_tp.bar_edge_mlp0_edge_density,
                );
                mace_mh1_trace_stage("edge_mlp_bridge_parallel.layer0", stage_start);
                result
            },
            || {
                let stage_start = trace_timings.then(Instant::now);
                let result = self.edge_mlp_layer_vjp_and_decompose_f32_bridge(
                    "interactions.1",
                    MaceMh1EdgeMlpDims {
                        input_dim: MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM,
                        hidden_dim: MACE_MH1_INTERACTION1_EDGE_MLP_HIDDEN_DIM,
                        tp_weight_dim: MACE_MH1_INTERACTION1_TP_WEIGHT_DIM,
                    },
                    &forward.edge_boundary,
                    &forward.edge_mlp1.augmented_edge_feats,
                    &forward.edge_mlp1.conv_tp_weights,
                    &forward.edge_mlp1.edge_density,
                    forward.edge_mlp1.forward_cache_f32.as_deref(),
                    &conv_tp.bar_edge_mlp1_conv_tp_weights,
                    &conv_tp.bar_edge_mlp1_edge_density,
                );
                mace_mh1_trace_stage("edge_mlp_bridge_parallel.layer1", stage_start);
                result
            },
        );
        let layer0 = layer0?;
        let layer1 = layer1?;

        let combine_start = trace_timings.then(Instant::now);
        let mut bar_edge_feats = layer0.bar_edge_feats;
        for (dst, src) in bar_edge_feats.iter_mut().zip(&layer1.bar_edge_feats) {
            *dst += src;
        }
        let mut bar_edge_cutoff = layer0.bar_edge_cutoff;
        for (dst, src) in bar_edge_cutoff.iter_mut().zip(&layer1.bar_edge_cutoff) {
            *dst += src;
        }
        mace_mh1_trace_stage("edge_mlp_bridge_parallel.combine", combine_start);
        mace_mh1_trace_stage("edge_mlp_bridge_parallel.total", total_start);

        Ok(MaceMh1EdgeMlpForceVjpF32Bridge {
            conv_tp,
            bar_edge_feats,
            bar_edge_cutoff,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp_and_decompose_force_bridge(
        &self,
        interaction_prefix: &str,
        dims: MaceMh1EdgeMlpDims,
        edge_input: &MaceMh1EdgeInputBoundary,
        augmented: &[f64],
        cutoff_conv_tp_weights: &[f64],
        cutoff_edge_density: &[f64],
        forward_cache: Option<&MaceMh1EdgeMlpForwardCache>,
        bar_cutoff_conv_tp_weights: &[f64],
        bar_cutoff_edge_density: &[f64],
    ) -> Result<MaceMh1EdgeMlpForceLayerVjpBars, MaceMh1Error> {
        if let Some(cache) = forward_cache
            .filter(|_| !edge_input.edge_cutoff.contains(&0.0))
            .filter(|cache| {
                cutoff_conv_tp_weights.len() == bar_cutoff_conv_tp_weights.len()
                    && cache.conv_tp_weights.linear0.len()
                        == edge_input.edge_count * dims.hidden_dim
                    && cache.density.linear0.len() == edge_input.edge_count * dims.hidden_dim
                    && cutoff_edge_density.len() == bar_cutoff_edge_density.len()
            })
        {
            return self.edge_mlp_layer_vjp_and_decompose_force_bridge_radial_cached(
                interaction_prefix,
                dims,
                edge_input,
                cutoff_conv_tp_weights,
                cutoff_edge_density,
                cache,
                bar_cutoff_conv_tp_weights,
                bar_cutoff_edge_density,
            );
        }

        let mut bar_edge_feats = vec![0.0; edge_input.edge_feats.len()];
        let mut bar_edge_cutoff = vec![0.0; edge_input.edge_cutoff.len()];
        let bar_augmented_len =
            forward_cache.map_or(augmented.len(), |_| edge_input.edge_count * dims.input_dim);
        let mut bar_augmented_edge_feats = vec![0.0; bar_augmented_len];
        self.edge_mlp_layer_vjp(
            interaction_prefix,
            dims.input_dim,
            dims.hidden_dim,
            dims.tp_weight_dim,
            edge_input,
            augmented,
            cutoff_conv_tp_weights,
            cutoff_edge_density,
            forward_cache,
            bar_cutoff_conv_tp_weights,
            bar_cutoff_edge_density,
            &mut bar_edge_cutoff,
            &mut bar_augmented_edge_feats,
        )?;
        decompose_edge_mlp_augmented_bars_radial_only(
            &format!("{interaction_prefix}.edge_mlp.force_bridge_vjp"),
            dims.input_dim,
            edge_input,
            &bar_augmented_edge_feats,
            &mut bar_edge_feats,
        )?;
        Ok(MaceMh1EdgeMlpForceLayerVjpBars {
            bar_edge_feats,
            bar_edge_cutoff,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp_and_decompose_force_bridge_radial_cached(
        &self,
        interaction_prefix: &str,
        dims: MaceMh1EdgeMlpDims,
        edge_input: &MaceMh1EdgeInputBoundary,
        cutoff_conv_tp_weights: &[f64],
        cutoff_edge_density: &[f64],
        forward_cache: &MaceMh1EdgeMlpForwardCache,
        bar_cutoff_conv_tp_weights: &[f64],
        bar_cutoff_edge_density: &[f64],
    ) -> Result<MaceMh1EdgeMlpForceLayerVjpBars, MaceMh1Error> {
        let edge_count = edge_input.edge_count;
        if edge_input.edge_feats.len() != edge_count * MACE_MH1_NUM_BESSEL
            || edge_input.edge_cutoff.len() != edge_count
            || cutoff_conv_tp_weights.len() != edge_count * dims.tp_weight_dim
            || bar_cutoff_conv_tp_weights.len() != edge_count * dims.tp_weight_dim
            || cutoff_edge_density.len() != edge_count
            || bar_cutoff_edge_density.len() != edge_count
        {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp force bridge radial length mismatch"
            )));
        }

        let conv_prefix = format!("{interaction_prefix}.conv_tp_weights.net");
        let density_prefix = format!("{interaction_prefix}.density_fn.net");
        let mut bar_raw_conv_tp_weights = vec![0.0; cutoff_conv_tp_weights.len()];
        let mut conv_bar_edge_cutoff = vec![0.0; edge_count];
        mace_mh1_fill_conv_tp_cutoff_bars(
            edge_count,
            dims.tp_weight_dim,
            &edge_input.edge_cutoff,
            cutoff_conv_tp_weights,
            None,
            bar_cutoff_conv_tp_weights,
            &mut bar_raw_conv_tp_weights,
            &mut conv_bar_edge_cutoff,
        );
        let mut conv_bar_edge_feats = vec![0.0; edge_input.edge_feats.len()];
        self.edge_mlp_conv_tp_weights_vjp_radial_input_cached(
            &conv_prefix,
            dims.input_dim,
            dims.hidden_dim,
            dims.tp_weight_dim,
            &bar_raw_conv_tp_weights,
            &mut conv_bar_edge_feats,
            &forward_cache.conv_tp_weights,
        )?;

        let mut bar_raw_edge_density = vec![0.0; edge_count];
        let mut density_bar_edge_cutoff = vec![0.0; edge_count];
        for edge in 0..edge_count {
            let bar = bar_cutoff_edge_density[edge];
            let cutoff = edge_input.edge_cutoff[edge];
            bar_raw_edge_density[edge] += bar * cutoff;
            density_bar_edge_cutoff[edge] += bar * (cutoff_edge_density[edge] / cutoff);
        }
        let mut density_bar_edge_feats = vec![0.0; edge_input.edge_feats.len()];
        self.edge_mlp_density_vjp_radial_input_cached(
            &density_prefix,
            dims.input_dim,
            dims.hidden_dim,
            &bar_raw_edge_density,
            &mut density_bar_edge_feats,
            &forward_cache.density,
        )?;

        for (dst, src) in conv_bar_edge_feats.iter_mut().zip(density_bar_edge_feats) {
            *dst += src;
        }
        for (dst, src) in conv_bar_edge_cutoff.iter_mut().zip(density_bar_edge_cutoff) {
            *dst += src;
        }

        Ok(MaceMh1EdgeMlpForceLayerVjpBars {
            bar_edge_feats: conv_bar_edge_feats,
            bar_edge_cutoff: conv_bar_edge_cutoff,
        })
    }

    #[cfg(feature = "parallel")]
    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp_and_decompose(
        &self,
        interaction_prefix: &str,
        dims: MaceMh1EdgeMlpDims,
        edge_input: &MaceMh1EdgeInputBoundary,
        source_embedding_len: usize,
        target_embedding_len: usize,
        augmented: &[f64],
        cutoff_conv_tp_weights: &[f64],
        cutoff_edge_density: &[f64],
        forward_cache: Option<&MaceMh1EdgeMlpForwardCache>,
        bar_cutoff_conv_tp_weights: &[f64],
        bar_cutoff_edge_density: &[f64],
    ) -> Result<MaceMh1EdgeMlpLayerVjpBars, MaceMh1Error> {
        let mut bar_edge_feats = vec![0.0; edge_input.edge_feats.len()];
        let mut bar_edge_cutoff = vec![0.0; edge_input.edge_cutoff.len()];
        let mut bar_augmented_edge_feats = vec![0.0; augmented.len()];
        if rayon::current_num_threads() > 2
            && edge_input.edge_count >= MACE_MH1_ROW_PARALLEL_MIN_ROWS
        {
            self.edge_mlp_layer_vjp_split_parallel(
                interaction_prefix,
                dims.input_dim,
                dims.hidden_dim,
                dims.tp_weight_dim,
                edge_input,
                augmented,
                cutoff_conv_tp_weights,
                cutoff_edge_density,
                forward_cache,
                bar_cutoff_conv_tp_weights,
                bar_cutoff_edge_density,
                &mut bar_edge_cutoff,
                &mut bar_augmented_edge_feats,
            )?;
        } else {
            self.edge_mlp_layer_vjp(
                interaction_prefix,
                dims.input_dim,
                dims.hidden_dim,
                dims.tp_weight_dim,
                edge_input,
                augmented,
                cutoff_conv_tp_weights,
                cutoff_edge_density,
                forward_cache,
                bar_cutoff_conv_tp_weights,
                bar_cutoff_edge_density,
                &mut bar_edge_cutoff,
                &mut bar_augmented_edge_feats,
            )?;
        }

        let mut bar_source_embedding = vec![0.0; source_embedding_len];
        let mut bar_target_embedding = vec![0.0; target_embedding_len];
        decompose_edge_mlp_augmented_bars(
            &format!("{interaction_prefix}.edge_mlp.parallel_vjp"),
            dims.input_dim,
            edge_input,
            &bar_augmented_edge_feats,
            &mut bar_edge_feats,
            &mut bar_source_embedding,
            &mut bar_target_embedding,
        )?;

        Ok(MaceMh1EdgeMlpLayerVjpBars {
            bar_edge_feats,
            bar_edge_cutoff,
            bar_augmented_edge_feats,
            bar_source_embedding,
            bar_target_embedding,
        })
    }

