    #[cfg(feature = "parallel")]
    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp_and_decompose_f32_bridge(
        &self,
        interaction_prefix: &str,
        dims: MaceMh1EdgeMlpDims,
        edge_input: &MaceMh1EdgeInputBoundary,
        augmented: &[f64],
        cutoff_conv_tp_weights: &[f64],
        cutoff_edge_density: &[f64],
        forward_cache: Option<&MaceMh1EdgeMlpForwardCacheF32>,
        bar_cutoff_conv_tp_weights: &[f32],
        bar_cutoff_edge_density: &[f32],
    ) -> Result<MaceMh1EdgeMlpLayerVjpBarsF32, MaceMh1Error> {
        let trace_timings = mace_mh1_trace_timings_enabled();
        if let Some(cache) = forward_cache
            // The radial-cached path recovers raw values by dividing cached
            // post-cutoff values by cutoff, so zero-cutoff edges use the
            // general bridge below where they are skipped explicitly.
            .filter(|_| !edge_input.edge_cutoff.contains(&0.0))
            .filter(|cache| {
                cache.cutoff_conv_tp_weights.len() == edge_input.edge_count * dims.tp_weight_dim
                    && bar_cutoff_conv_tp_weights.len()
                        == edge_input.edge_count * dims.tp_weight_dim
                    && cache.cutoff_edge_density.len() == edge_input.edge_count
                    && bar_cutoff_edge_density.len() == edge_input.edge_count
            })
        {
            let stage_start = trace_timings.then(Instant::now);
            let result = self.edge_mlp_layer_vjp_and_decompose_f32_bridge_radial_cached(
                interaction_prefix,
                dims,
                edge_input,
                cache,
                bar_cutoff_conv_tp_weights,
                bar_cutoff_edge_density,
            );
            mace_mh1_trace_stage(
                &format!("{interaction_prefix}.edge_mlp_bridge.radial_cached"),
                stage_start,
            );
            return result;
        }

        let mut bar_edge_feats = vec![0.0_f32; edge_input.edge_feats.len()];
        let mut bar_edge_cutoff = vec![0.0_f32; edge_input.edge_cutoff.len()];
        let bar_augmented_len =
            forward_cache.map_or(augmented.len(), |_| edge_input.edge_count * dims.input_dim);
        let mut bar_augmented_edge_feats = vec![0.0_f32; bar_augmented_len];
        let layer_vjp_start = trace_timings.then(Instant::now);
        if rayon::current_num_threads() > 2
            && edge_input.edge_count >= MACE_MH1_ROW_PARALLEL_MIN_ROWS
        {
            self.edge_mlp_layer_vjp_split_parallel_f32_bridge(
                interaction_prefix,
                dims.input_dim,
                dims.hidden_dim,
                dims.tp_weight_dim,
                edge_input,
                augmented,
                cutoff_conv_tp_weights,
                cutoff_edge_density,
                forward_cache,
                bar_cutoff_conv_tp_weights,
                bar_cutoff_edge_density,
                &mut bar_edge_cutoff,
                &mut bar_augmented_edge_feats,
            )?;
            mace_mh1_trace_stage(
                &format!("{interaction_prefix}.edge_mlp_bridge.split_parallel"),
                layer_vjp_start,
            );
        } else {
            self.edge_mlp_layer_vjp_f32_bridge(
                interaction_prefix,
                dims.input_dim,
                dims.hidden_dim,
                dims.tp_weight_dim,
                edge_input,
                augmented,
                cutoff_conv_tp_weights,
                cutoff_edge_density,
                forward_cache,
                bar_cutoff_conv_tp_weights,
                bar_cutoff_edge_density,
                &mut bar_edge_cutoff,
                &mut bar_augmented_edge_feats,
            )?;
            mace_mh1_trace_stage(
                &format!("{interaction_prefix}.edge_mlp_bridge.serial_layer"),
                layer_vjp_start,
            );
        }

        let decompose_start = trace_timings.then(Instant::now);
        decompose_edge_mlp_augmented_bars_f32_radial_only(
            &format!("{interaction_prefix}.edge_mlp.parallel_f32_bridge_vjp"),
            dims.input_dim,
            edge_input,
            &bar_augmented_edge_feats,
            &mut bar_edge_feats,
        )?;
        mace_mh1_trace_stage(
            &format!("{interaction_prefix}.edge_mlp_bridge.decompose"),
            decompose_start,
        );

        Ok(MaceMh1EdgeMlpLayerVjpBarsF32 {
            bar_edge_feats,
            bar_edge_cutoff,
        })
    }

    #[cfg(feature = "parallel")]
    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp_and_decompose_f32_bridge_radial_cached(
        &self,
        interaction_prefix: &str,
        dims: MaceMh1EdgeMlpDims,
        edge_input: &MaceMh1EdgeInputBoundary,
        forward_cache: &MaceMh1EdgeMlpForwardCacheF32,
        bar_cutoff_conv_tp_weights: &[f32],
        bar_cutoff_edge_density: &[f32],
    ) -> Result<MaceMh1EdgeMlpLayerVjpBarsF32, MaceMh1Error> {
        let edge_count = edge_input.edge_count;
        if edge_input.edge_feats.len() != edge_count * MACE_MH1_NUM_BESSEL
            || edge_input.edge_cutoff.len() != edge_count
            || forward_cache.cutoff_conv_tp_weights.len() != edge_count * dims.tp_weight_dim
            || bar_cutoff_conv_tp_weights.len() != edge_count * dims.tp_weight_dim
            || forward_cache.cutoff_edge_density.len() != edge_count
            || bar_cutoff_edge_density.len() != edge_count
        {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp radial f32-bridge length mismatch"
            )));
        }

        let trace_timings = mace_mh1_trace_timings_enabled();
        let conv_prefix = format!("{interaction_prefix}.conv_tp_weights.net");
        let density_prefix = format!("{interaction_prefix}.density_fn.net");
        let (conv_result, density_result) = rayon::join(
            || -> Result<(Vec<f32>, Vec<f32>), MaceMh1Error> {
                let stage_start = trace_timings.then(Instant::now);
                let mut bar_raw_conv_tp_weights =
                    vec![0.0_f32; forward_cache.cutoff_conv_tp_weights.len()];
                let mut local_bar_edge_cutoff = vec![0.0_f32; edge_count];
                mace_mh1_fill_conv_tp_cutoff_bars_f32(
                    edge_count,
                    dims.tp_weight_dim,
                    &edge_input.edge_cutoff,
                    None,
                    Some(&forward_cache.cutoff_conv_tp_weights),
                    bar_cutoff_conv_tp_weights,
                    &mut bar_raw_conv_tp_weights,
                    &mut local_bar_edge_cutoff,
                );
                let mut local_bar_edge_feats = vec![0.0_f32; edge_input.edge_feats.len()];
                let output_row_scale = vec![1.0; edge_count];
                self.edge_mlp_conv_tp_weights_vjp_radial_input_f32_cached(
                    &conv_prefix,
                    dims.input_dim,
                    dims.hidden_dim,
                    dims.tp_weight_dim,
                    &bar_raw_conv_tp_weights,
                    &mut local_bar_edge_feats,
                    &forward_cache.conv_tp_weights,
                    &output_row_scale,
                )?;
                let result = Ok((local_bar_edge_cutoff, local_bar_edge_feats));
                mace_mh1_trace_stage(
                    &format!("{interaction_prefix}.edge_mlp_bridge.radial_conv"),
                    stage_start,
                );
                result
            },
            || -> Result<(Vec<f32>, Vec<f32>), MaceMh1Error> {
                let stage_start = trace_timings.then(Instant::now);
                let mut bar_raw_edge_density = vec![0.0_f32; edge_count];
                let mut local_bar_edge_cutoff = vec![0.0_f32; edge_count];
                for edge in 0..edge_count {
                    let bar = bar_cutoff_edge_density[edge];
                    let cutoff = edge_input.edge_cutoff[edge] as f32;
                    bar_raw_edge_density[edge] += bar * cutoff;
                    // Skip cutoff == 0 edges (annihilated downstream); avoids 0/0.
                    if cutoff != 0.0 {
                        local_bar_edge_cutoff[edge] +=
                            bar * (forward_cache.cutoff_edge_density[edge] / cutoff);
                    }
                }
                let mut local_bar_edge_feats = vec![0.0_f32; edge_input.edge_feats.len()];
                self.edge_mlp_density_vjp_radial_input_f32_cached(
                    &density_prefix,
                    dims.input_dim,
                    dims.hidden_dim,
                    &bar_raw_edge_density,
                    &mut local_bar_edge_feats,
                    &forward_cache.density,
                )?;
                let result = Ok((local_bar_edge_cutoff, local_bar_edge_feats));
                mace_mh1_trace_stage(
                    &format!("{interaction_prefix}.edge_mlp_bridge.radial_density"),
                    stage_start,
                );
                result
            },
        );
        let (conv_bar_cutoff, conv_bar_edge_feats) = conv_result?;
        let (density_bar_cutoff, density_bar_edge_feats) = density_result?;

        let combine_start = trace_timings.then(Instant::now);
        let mut bar_edge_feats = conv_bar_edge_feats;
        for (dst, src) in bar_edge_feats.iter_mut().zip(density_bar_edge_feats) {
            *dst += src;
        }
        let mut bar_edge_cutoff = conv_bar_cutoff;
        for (dst, src) in bar_edge_cutoff.iter_mut().zip(density_bar_cutoff) {
            *dst += src;
        }
        mace_mh1_trace_stage(
            &format!("{interaction_prefix}.edge_mlp_bridge.radial_combine"),
            combine_start,
        );

        Ok(MaceMh1EdgeMlpLayerVjpBarsF32 {
            bar_edge_feats,
            bar_edge_cutoff,
        })
    }

    #[cfg(feature = "parallel")]
    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp_split_parallel(
        &self,
        interaction_prefix: &str,
        input_dim: usize,
        hidden_dim: usize,
        tp_weight_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        augmented: &[f64],
        cutoff_conv_tp_weights: &[f64],
        cutoff_edge_density: &[f64],
        forward_cache: Option<&MaceMh1EdgeMlpForwardCache>,
        bar_cutoff_conv_tp_weights: &[f64],
        bar_cutoff_edge_density: &[f64],
        bar_edge_cutoff: &mut [f64],
        bar_augmented: &mut [f64],
    ) -> Result<(), MaceMh1Error> {
        let edge_count = checked_row_count(
            &format!("{interaction_prefix}.edge_mlp.augmented.parallel_vjp"),
            augmented.len(),
            input_dim,
        )?;
        if edge_count != edge_input.edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp augmented row count {edge_count} does not match edge_count {}",
                edge_input.edge_count
            )));
        }
        if edge_input.edge_cutoff.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp edge_cutoff length mismatch"
            )));
        }
        if cutoff_conv_tp_weights.len() != edge_count * tp_weight_dim {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp cutoff conv_tp weight length mismatch"
            )));
        }
        if cutoff_edge_density.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp cutoff edge-density length mismatch"
            )));
        }
        if bar_edge_cutoff.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp bar_edge_cutoff length mismatch"
            )));
        }
        if bar_augmented.len() != augmented.len() {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp bar_augmented length mismatch"
            )));
        }
        if bar_cutoff_conv_tp_weights.len() != edge_count * tp_weight_dim {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp conv_tp weight bar length mismatch"
            )));
        }
        if bar_cutoff_edge_density.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp edge-density bar length mismatch"
            )));
        }

        let conv_prefix = format!("{interaction_prefix}.conv_tp_weights.net");
        let density_prefix = format!("{interaction_prefix}.density_fn.net");
        let has_zero_cutoff = edge_input.edge_cutoff.contains(&0.0);

        let (conv_result, density_result) = rayon::join(
            || -> Result<(Vec<f64>, Vec<f64>), MaceMh1Error> {
                let raw_conv_tp_weights = if has_zero_cutoff {
                    Some(self.edge_mlp_conv_tp_weights_forward(
                        &conv_prefix,
                        augmented,
                        input_dim,
                        hidden_dim,
                        tp_weight_dim,
                    )?)
                } else {
                    None
                };
                let mut bar_raw_conv_tp_weights = vec![0.0; cutoff_conv_tp_weights.len()];
                let mut local_bar_edge_cutoff = vec![0.0; edge_count];
                bar_raw_conv_tp_weights
                    .par_chunks_mut(tp_weight_dim)
                    .zip(local_bar_edge_cutoff.par_iter_mut())
                    .enumerate()
                    .for_each(|(edge, (bar_raw_row, cutoff_bar))| {
                        let cutoff = edge_input.edge_cutoff[edge];
                        let row_start = edge * tp_weight_dim;
                        let row_end = row_start + tp_weight_dim;
                        for (local, index) in (row_start..row_end).enumerate() {
                            let bar = bar_cutoff_conv_tp_weights[index];
                            bar_raw_row[local] += bar * cutoff;
                            let raw_value = match raw_conv_tp_weights.as_ref() {
                                Some(raw) => raw[index],
                                None => cutoff_conv_tp_weights[index] / cutoff,
                            };
                            *cutoff_bar += bar * raw_value;
                        }
                    });
                let mut local_bar_augmented = vec![0.0; augmented.len()];
                self.edge_mlp_conv_tp_weights_vjp_input(
                    &conv_prefix,
                    input_dim,
                    hidden_dim,
                    tp_weight_dim,
                    augmented,
                    &bar_raw_conv_tp_weights,
                    &mut local_bar_augmented,
                    forward_cache.map(|cache| &cache.conv_tp_weights),
                )?;
                Ok((local_bar_edge_cutoff, local_bar_augmented))
            },
            || -> Result<(Vec<f64>, Vec<f64>), MaceMh1Error> {
                let raw_edge_density = if has_zero_cutoff {
                    Some(self.edge_mlp_density_forward(
                        &density_prefix,
                        augmented,
                        input_dim,
                        hidden_dim,
                    )?)
                } else {
                    None
                };
                let mut bar_raw_edge_density = vec![0.0; edge_count];
                let mut local_bar_edge_cutoff = vec![0.0; edge_count];
                for edge in 0..edge_count {
                    let bar = bar_cutoff_edge_density[edge];
                    let cutoff = edge_input.edge_cutoff[edge];
                    bar_raw_edge_density[edge] += bar * cutoff;
                    let raw_value = match raw_edge_density.as_ref() {
                        Some(raw) => raw[edge],
                        None => cutoff_edge_density[edge] / cutoff,
                    };
                    local_bar_edge_cutoff[edge] += bar * raw_value;
                }
                let mut local_bar_augmented = vec![0.0; augmented.len()];
                self.edge_mlp_density_vjp_input(
                    &density_prefix,
                    input_dim,
                    hidden_dim,
                    augmented,
                    &bar_raw_edge_density,
                    &mut local_bar_augmented,
                    forward_cache.map(|cache| &cache.density),
                )?;
                Ok((local_bar_edge_cutoff, local_bar_augmented))
            },
        );
        let (conv_bar_cutoff, mut conv_bar_augmented) = conv_result?;
        let (density_bar_cutoff, density_bar_augmented) = density_result?;

        for ((dst, conv), density) in bar_edge_cutoff
            .iter_mut()
            .zip(conv_bar_cutoff)
            .zip(density_bar_cutoff)
        {
            *dst += conv + density;
        }
        for ((dst, conv), density) in bar_augmented
            .iter_mut()
            .zip(conv_bar_augmented.iter_mut())
            .zip(density_bar_augmented)
        {
            *dst += *conv + density;
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp(
        &self,
        interaction_prefix: &str,
        input_dim: usize,
        hidden_dim: usize,
        tp_weight_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        augmented: &[f64],
        cutoff_conv_tp_weights: &[f64],
        cutoff_edge_density: &[f64],
        forward_cache: Option<&MaceMh1EdgeMlpForwardCache>,
        bar_cutoff_conv_tp_weights: &[f64],
        bar_cutoff_edge_density: &[f64],
        bar_edge_cutoff: &mut [f64],
        bar_augmented: &mut [f64],
    ) -> Result<(), MaceMh1Error> {
        let edge_count = checked_row_count(
            &format!("{interaction_prefix}.edge_mlp.augmented.vjp"),
            augmented.len(),
            input_dim,
        )?;
        if edge_count != edge_input.edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp augmented row count {edge_count} does not match edge_count {}",
                edge_input.edge_count
            )));
        }
        if edge_input.edge_cutoff.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp edge_cutoff length mismatch"
            )));
        }
        if cutoff_conv_tp_weights.len() != edge_count * tp_weight_dim {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp cutoff conv_tp weight length mismatch"
            )));
        }
        if cutoff_edge_density.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp cutoff edge-density length mismatch"
            )));
        }
        if bar_edge_cutoff.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp bar_edge_cutoff length mismatch"
            )));
        }
        if bar_augmented.len() != augmented.len() {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp bar_augmented length mismatch"
            )));
        }
        if bar_cutoff_conv_tp_weights.len() != edge_count * tp_weight_dim {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp conv_tp weight bar length mismatch"
            )));
        }
        if bar_cutoff_edge_density.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp edge-density bar length mismatch"
            )));
        }

        let conv_prefix = &format!("{interaction_prefix}.conv_tp_weights.net");
        let raw_conv_tp_weights = if edge_input.edge_cutoff.contains(&0.0) {
            Some(self.edge_mlp_conv_tp_weights_forward(
                conv_prefix,
                augmented,
                input_dim,
                hidden_dim,
                tp_weight_dim,
            )?)
        } else {
            None
        };
        let mut bar_raw_conv_tp_weights = vec![0.0; cutoff_conv_tp_weights.len()];
        #[cfg(feature = "parallel")]
        let used_parallel_cutoff_vjp =
            if rayon::current_num_threads() > 1 && edge_count >= MACE_MH1_ROW_PARALLEL_MIN_ROWS {
                bar_raw_conv_tp_weights
                    .par_chunks_mut(tp_weight_dim)
                    .zip(bar_edge_cutoff.par_iter_mut())
                    .enumerate()
                    .for_each(|(edge, (bar_raw_row, cutoff_bar))| {
                        let cutoff = edge_input.edge_cutoff[edge];
                        let row_start = edge * tp_weight_dim;
                        let row_end = row_start + tp_weight_dim;
                        for (local, index) in (row_start..row_end).enumerate() {
                            let bar = bar_cutoff_conv_tp_weights[index];
                            bar_raw_row[local] += bar * cutoff;
                            let raw_value = match raw_conv_tp_weights.as_ref() {
                                Some(raw) => raw[index],
                                None => cutoff_conv_tp_weights[index] / cutoff,
                            };
                            *cutoff_bar += bar * raw_value;
                        }
                    });
                true
            } else {
                false
            };
        #[cfg(not(feature = "parallel"))]
        let used_parallel_cutoff_vjp = false;
        if !used_parallel_cutoff_vjp {
            for (edge, cutoff_bar) in bar_edge_cutoff.iter_mut().enumerate().take(edge_count) {
                let cutoff = edge_input.edge_cutoff[edge];
                let row_start = edge * tp_weight_dim;
                let row_end = row_start + tp_weight_dim;
                for index in row_start..row_end {
                    let bar = bar_cutoff_conv_tp_weights[index];
                    bar_raw_conv_tp_weights[index] += bar * cutoff;
                    let raw_value = match raw_conv_tp_weights.as_ref() {
                        Some(raw) => raw[index],
                        None => cutoff_conv_tp_weights[index] / cutoff,
                    };
                    *cutoff_bar += bar * raw_value;
                }
            }
        }
        self.edge_mlp_conv_tp_weights_vjp_input(
            conv_prefix,
            input_dim,
            hidden_dim,
            tp_weight_dim,
            augmented,
            &bar_raw_conv_tp_weights,
            bar_augmented,
            forward_cache.map(|cache| &cache.conv_tp_weights),
        )?;

        let density_prefix = &format!("{interaction_prefix}.density_fn.net");
        let raw_edge_density = if edge_input.edge_cutoff.contains(&0.0) {
            Some(self.edge_mlp_density_forward(density_prefix, augmented, input_dim, hidden_dim)?)
        } else {
            None
        };
        let mut bar_raw_edge_density = vec![0.0; edge_count];
        for edge in 0..edge_count {
            let bar = bar_cutoff_edge_density[edge];
            let cutoff = edge_input.edge_cutoff[edge];
            bar_raw_edge_density[edge] += bar * cutoff;
            let raw_value = match raw_edge_density.as_ref() {
                Some(raw) => raw[edge],
                None => cutoff_edge_density[edge] / cutoff,
            };
            bar_edge_cutoff[edge] += bar * raw_value;
        }
        self.edge_mlp_density_vjp_input(
            density_prefix,
            input_dim,
            hidden_dim,
            augmented,
            &bar_raw_edge_density,
            bar_augmented,
            forward_cache.map(|cache| &cache.density),
        )?;

        Ok(())
    }

    #[cfg(feature = "parallel")]
    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp_split_parallel_f32_promoted(
        &self,
        interaction_prefix: &str,
        input_dim: usize,
        hidden_dim: usize,
        tp_weight_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        augmented: &[f64],
        cutoff_conv_tp_weights: &[f64],
        cutoff_edge_density: &[f64],
        forward_cache: Option<&MaceMh1EdgeMlpForwardCacheF32>,
        bar_cutoff_conv_tp_weights: &[f64],
        bar_cutoff_edge_density: &[f64],
        bar_edge_cutoff: &mut [f64],
        bar_augmented: &mut [f64],
    ) -> Result<(), MaceMh1Error> {
        let edge_count = if let Some(cache) = forward_cache {
            if cache.cutoff_edge_density.len() != edge_input.edge_count {
                return Err(invalid(format!(
                    "{interaction_prefix}.edge_mlp parallel f32-promoted cached edge-density length mismatch"
                )));
            }
            edge_input.edge_count
        } else {
            checked_row_count(
                &format!("{interaction_prefix}.edge_mlp.augmented.parallel_f32_promoted_vjp"),
                augmented.len(),
                input_dim,
            )?
        };
        if edge_count != edge_input.edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp parallel f32-promoted augmented row count {edge_count} does not match edge_count {}",
                edge_input.edge_count
            )));
        }
        let augmented_len = edge_count * input_dim;
        let cutoff_conv_tp_weights_len = forward_cache
            .map_or(cutoff_conv_tp_weights.len(), |cache| {
                cache.cutoff_conv_tp_weights.len()
            });
        let cutoff_edge_density_len = forward_cache.map_or(cutoff_edge_density.len(), |cache| {
            cache.cutoff_edge_density.len()
        });
        if edge_input.edge_cutoff.len() != edge_count
            || bar_edge_cutoff.len() != edge_count
            || cutoff_edge_density_len != edge_count
            || bar_cutoff_edge_density.len() != edge_count
        {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp parallel f32-promoted scalar edge length mismatch"
            )));
        }
        if cutoff_conv_tp_weights_len != edge_count * tp_weight_dim
            || bar_cutoff_conv_tp_weights.len() != edge_count * tp_weight_dim
        {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp parallel f32-promoted Conv-TP weight length mismatch"
            )));
        }
        if bar_augmented.len() != augmented_len {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp parallel f32-promoted bar_augmented length mismatch"
            )));
        }

        let conv_prefix = format!("{interaction_prefix}.conv_tp_weights.net");
        let density_prefix = format!("{interaction_prefix}.density_fn.net");
        let has_zero_cutoff = edge_input.edge_cutoff.contains(&0.0);
        let augmented_f32 = if has_zero_cutoff || forward_cache.is_none() {
            Some(
                augmented
                    .iter()
                    .map(|&value| value as f32)
                    .collect::<Vec<_>>(),
            )
        } else {
            None
        };
        let augmented_f32 = augmented_f32.as_deref().unwrap_or(&[]);
        let cutoff_conv_tp_weights_f32 = forward_cache
            .filter(|cache| cache.cutoff_conv_tp_weights.len() == cutoff_conv_tp_weights_len)
            .map(|cache| cache.cutoff_conv_tp_weights.as_slice());
        let cutoff_edge_density_f32 = forward_cache
            .filter(|cache| cache.cutoff_edge_density.len() == cutoff_edge_density_len)
            .map(|cache| cache.cutoff_edge_density.as_slice());

        let (conv_result, density_result) = rayon::join(
            || -> Result<(Vec<f64>, Vec<f32>), MaceMh1Error> {
                let raw_conv_tp_weights = if has_zero_cutoff {
                    Some(self.edge_mlp_conv_tp_weights_forward_f32(
                        &conv_prefix,
                        augmented_f32,
                        input_dim,
                        hidden_dim,
                        tp_weight_dim,
                    )?)
                } else {
                    None
                };
                let mut bar_raw_conv_tp_weights = vec![0.0_f32; cutoff_conv_tp_weights_len];
                let mut local_bar_edge_cutoff = vec![0.0_f64; edge_count];
                bar_raw_conv_tp_weights
                    .par_chunks_mut(tp_weight_dim)
                    .zip(local_bar_edge_cutoff.par_iter_mut())
                    .enumerate()
                    .for_each(|(edge, (bar_raw_row, cutoff_bar))| {
                        let cutoff = edge_input.edge_cutoff[edge] as f32;
                        let row_start = edge * tp_weight_dim;
                        let row_end = row_start + tp_weight_dim;
                        let mut local_cutoff_bar = 0.0_f32;
                        for (local, index) in (row_start..row_end).enumerate() {
                            let bar = bar_cutoff_conv_tp_weights[index] as f32;
                            bar_raw_row[local] += bar * cutoff;
                            let raw_value = match raw_conv_tp_weights.as_ref() {
                                Some(raw) => raw[index],
                                None => {
                                    cutoff_conv_tp_weights_f32
                                        .map(|weights| weights[index])
                                        .unwrap_or(cutoff_conv_tp_weights[index] as f32)
                                        / cutoff
                                }
                            };
                            local_cutoff_bar += bar * raw_value;
                        }
                        *cutoff_bar = f64::from(local_cutoff_bar);
                    });
                let mut local_bar_augmented = vec![0.0_f32; augmented_len];
                self.edge_mlp_conv_tp_weights_vjp_input_f32(
                    &conv_prefix,
                    input_dim,
                    hidden_dim,
                    tp_weight_dim,
                    augmented_f32,
                    &bar_raw_conv_tp_weights,
                    &mut local_bar_augmented,
                    forward_cache.map(|cache| &cache.conv_tp_weights),
                )?;
                Ok((local_bar_edge_cutoff, local_bar_augmented))
            },
            || -> Result<(Vec<f64>, Vec<f32>), MaceMh1Error> {
                let raw_edge_density = if has_zero_cutoff {
                    Some(self.edge_mlp_density_forward_f32(
                        &density_prefix,
                        augmented_f32,
                        input_dim,
                        hidden_dim,
                    )?)
                } else {
                    None
                };
                let mut bar_raw_edge_density = vec![0.0_f32; edge_count];
                let mut local_bar_edge_cutoff = vec![0.0_f64; edge_count];
                for edge in 0..edge_count {
                    let bar = bar_cutoff_edge_density[edge] as f32;
                    let cutoff = edge_input.edge_cutoff[edge] as f32;
                    bar_raw_edge_density[edge] += bar * cutoff;
                    let raw_value = match raw_edge_density.as_ref() {
                        Some(raw) => raw[edge],
                        None => {
                            cutoff_edge_density_f32
                                .map(|density| density[edge])
                                .unwrap_or(cutoff_edge_density[edge] as f32)
                                / cutoff
                        }
                    };
                    local_bar_edge_cutoff[edge] += f64::from(bar * raw_value);
                }
                let mut local_bar_augmented = vec![0.0_f32; augmented_len];
                self.edge_mlp_density_vjp_input_f32(
                    &density_prefix,
                    input_dim,
                    hidden_dim,
                    augmented_f32,
                    &bar_raw_edge_density,
                    &mut local_bar_augmented,
                    forward_cache.map(|cache| &cache.density),
                )?;
                Ok((local_bar_edge_cutoff, local_bar_augmented))
            },
        );
        let (conv_bar_cutoff, conv_bar_augmented) = conv_result?;
        let (density_bar_cutoff, density_bar_augmented) = density_result?;

        for ((dst, conv), density) in bar_edge_cutoff
            .iter_mut()
            .zip(conv_bar_cutoff)
            .zip(density_bar_cutoff)
        {
            *dst += conv + density;
        }
        for ((dst, conv), density) in bar_augmented
            .iter_mut()
            .zip(conv_bar_augmented)
            .zip(density_bar_augmented)
        {
            *dst += f64::from(conv + density);
        }
        Ok(())
    }

    #[cfg(feature = "parallel")]
    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp_split_parallel_f32_bridge(
        &self,
        interaction_prefix: &str,
        input_dim: usize,
        hidden_dim: usize,
        tp_weight_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        augmented: &[f64],
        cutoff_conv_tp_weights: &[f64],
        cutoff_edge_density: &[f64],
        forward_cache: Option<&MaceMh1EdgeMlpForwardCacheF32>,
        bar_cutoff_conv_tp_weights: &[f32],
        bar_cutoff_edge_density: &[f32],
        bar_edge_cutoff: &mut [f32],
        bar_augmented: &mut [f32],
    ) -> Result<(), MaceMh1Error> {
        let edge_count = if let Some(cache) = forward_cache {
            if cache.cutoff_edge_density.len() != edge_input.edge_count {
                return Err(invalid(format!(
                    "{interaction_prefix}.edge_mlp parallel f32-bridge cached edge-density length mismatch"
                )));
            }
            edge_input.edge_count
        } else {
            checked_row_count(
                &format!("{interaction_prefix}.edge_mlp.augmented.parallel_f32_bridge_vjp"),
                augmented.len(),
                input_dim,
            )?
        };
        if edge_count != edge_input.edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp parallel f32-bridge augmented row count {edge_count} does not match edge_count {}",
                edge_input.edge_count
            )));
        }
        let augmented_len = edge_count * input_dim;
        let cutoff_conv_tp_weights_len = forward_cache
            .map_or(cutoff_conv_tp_weights.len(), |cache| {
                cache.cutoff_conv_tp_weights.len()
            });
        let cutoff_edge_density_len = forward_cache.map_or(cutoff_edge_density.len(), |cache| {
            cache.cutoff_edge_density.len()
        });
        if edge_input.edge_cutoff.len() != edge_count
            || bar_edge_cutoff.len() != edge_count
            || cutoff_edge_density_len != edge_count
            || bar_cutoff_edge_density.len() != edge_count
        {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp parallel f32-bridge scalar edge length mismatch"
            )));
        }
        if cutoff_conv_tp_weights_len != edge_count * tp_weight_dim
            || bar_cutoff_conv_tp_weights.len() != edge_count * tp_weight_dim
        {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp parallel f32-bridge Conv-TP weight length mismatch"
            )));
        }
        if bar_augmented.len() != augmented_len {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp parallel f32-bridge bar_augmented length mismatch"
            )));
        }

        let conv_prefix = format!("{interaction_prefix}.conv_tp_weights.net");
        let density_prefix = format!("{interaction_prefix}.density_fn.net");
        let augmented_f32 = if forward_cache.is_none() {
            Some(
                augmented
                    .iter()
                    .map(|&value| value as f32)
                    .collect::<Vec<_>>(),
            )
        } else {
            None
        };
        let augmented_f32 = augmented_f32.as_deref().unwrap_or(&[]);
        let cutoff_conv_tp_weights_f32 = forward_cache
            .filter(|cache| cache.cutoff_conv_tp_weights.len() == cutoff_conv_tp_weights_len)
            .map(|cache| cache.cutoff_conv_tp_weights.as_slice());
        let cutoff_edge_density_f32 = forward_cache
            .filter(|cache| cache.cutoff_edge_density.len() == cutoff_edge_density_len)
            .map(|cache| cache.cutoff_edge_density.as_slice());

        let (conv_result, density_result) = rayon::join(
            || -> Result<(Vec<f32>, Vec<f32>), MaceMh1Error> {
                let mut bar_raw_conv_tp_weights = vec![0.0_f32; cutoff_conv_tp_weights_len];
                let mut local_bar_edge_cutoff = vec![0.0_f32; edge_count];
                mace_mh1_fill_conv_tp_cutoff_bars_f32(
                    edge_count,
                    tp_weight_dim,
                    &edge_input.edge_cutoff,
                    Some(cutoff_conv_tp_weights),
                    cutoff_conv_tp_weights_f32,
                    bar_cutoff_conv_tp_weights,
                    &mut bar_raw_conv_tp_weights,
                    &mut local_bar_edge_cutoff,
                );
                let mut local_bar_augmented = vec![0.0_f32; augmented_len];
                self.edge_mlp_conv_tp_weights_vjp_input_f32(
                    &conv_prefix,
                    input_dim,
                    hidden_dim,
                    tp_weight_dim,
                    augmented_f32,
                    &bar_raw_conv_tp_weights,
                    &mut local_bar_augmented,
                    forward_cache.map(|cache| &cache.conv_tp_weights),
                )?;
                Ok((local_bar_edge_cutoff, local_bar_augmented))
            },
            || -> Result<(Vec<f32>, Vec<f32>), MaceMh1Error> {
                let mut bar_raw_edge_density = vec![0.0_f32; edge_count];
                let mut local_bar_edge_cutoff = vec![0.0_f32; edge_count];
                for edge in 0..edge_count {
                    let bar = bar_cutoff_edge_density[edge];
                    let cutoff = edge_input.edge_cutoff[edge] as f32;
                    bar_raw_edge_density[edge] += bar * cutoff;
                    // Recover the pre-cutoff density from the cached post-cutoff value;
                    // skip cutoff == 0 edges (annihilated downstream).
                    if cutoff != 0.0 {
                        let cutoff_density = cutoff_edge_density_f32
                            .map(|density| density[edge])
                            .unwrap_or(cutoff_edge_density[edge] as f32);
                        local_bar_edge_cutoff[edge] += bar * (cutoff_density / cutoff);
                    }
                }
                let mut local_bar_augmented = vec![0.0_f32; augmented_len];
                self.edge_mlp_density_vjp_input_f32(
                    &density_prefix,
                    input_dim,
                    hidden_dim,
                    augmented_f32,
                    &bar_raw_edge_density,
                    &mut local_bar_augmented,
                    forward_cache.map(|cache| &cache.density),
                )?;
                Ok((local_bar_edge_cutoff, local_bar_augmented))
            },
        );
        let (conv_bar_cutoff, conv_bar_augmented) = conv_result?;
        let (density_bar_cutoff, density_bar_augmented) = density_result?;

        for ((dst, conv), density) in bar_edge_cutoff
            .iter_mut()
            .zip(conv_bar_cutoff)
            .zip(density_bar_cutoff)
        {
            *dst += conv + density;
        }
        for ((dst, conv), density) in bar_augmented
            .iter_mut()
            .zip(conv_bar_augmented)
            .zip(density_bar_augmented)
        {
            *dst += conv + density;
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp_f32_promoted(
        &self,
        interaction_prefix: &str,
        input_dim: usize,
        hidden_dim: usize,
        tp_weight_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        augmented: &[f64],
        cutoff_conv_tp_weights: &[f64],
        cutoff_edge_density: &[f64],
        forward_cache: Option<&MaceMh1EdgeMlpForwardCacheF32>,
        bar_cutoff_conv_tp_weights: &[f64],
        bar_cutoff_edge_density: &[f64],
        bar_edge_cutoff: &mut [f64],
        bar_augmented: &mut [f64],
    ) -> Result<(), MaceMh1Error> {
        let edge_count = if let Some(cache) = forward_cache {
            if cache.cutoff_edge_density.len() != edge_input.edge_count {
                return Err(invalid(format!(
                    "{interaction_prefix}.edge_mlp f32-promoted cached edge-density length mismatch"
                )));
            }
            edge_input.edge_count
        } else {
            checked_row_count(
                &format!("{interaction_prefix}.edge_mlp.augmented.f32_promoted_vjp"),
                augmented.len(),
                input_dim,
            )?
        };
        if edge_count != edge_input.edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-promoted augmented row count {edge_count} does not match edge_count {}",
                edge_input.edge_count
            )));
        }
        let augmented_len = edge_count * input_dim;
        let cutoff_conv_tp_weights_len = forward_cache
            .map_or(cutoff_conv_tp_weights.len(), |cache| {
                cache.cutoff_conv_tp_weights.len()
            });
        let cutoff_edge_density_len = forward_cache.map_or(cutoff_edge_density.len(), |cache| {
            cache.cutoff_edge_density.len()
        });
        if edge_input.edge_cutoff.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-promoted edge_cutoff length mismatch"
            )));
        }
        if cutoff_conv_tp_weights_len != edge_count * tp_weight_dim {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-promoted cutoff conv_tp weight length mismatch"
            )));
        }
        if cutoff_edge_density_len != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-promoted cutoff edge-density length mismatch"
            )));
        }
        if bar_edge_cutoff.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-promoted bar_edge_cutoff length mismatch"
            )));
        }
        if bar_augmented.len() != augmented_len {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-promoted bar_augmented length mismatch"
            )));
        }
        if bar_cutoff_conv_tp_weights.len() != edge_count * tp_weight_dim {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-promoted conv_tp weight bar length mismatch"
            )));
        }
        if bar_cutoff_edge_density.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-promoted edge-density bar length mismatch"
            )));
        }

        let conv_prefix = &format!("{interaction_prefix}.conv_tp_weights.net");
        let has_zero_cutoff = edge_input.edge_cutoff.contains(&0.0);
        let augmented_f32 = if has_zero_cutoff || forward_cache.is_none() {
            Some(
                augmented
                    .iter()
                    .map(|&value| value as f32)
                    .collect::<Vec<_>>(),
            )
        } else {
            None
        };
        let augmented_f32 = augmented_f32.as_deref().unwrap_or(&[]);
        let cutoff_conv_tp_weights_f32 = forward_cache
            .filter(|cache| cache.cutoff_conv_tp_weights.len() == cutoff_conv_tp_weights_len)
            .map(|cache| cache.cutoff_conv_tp_weights.as_slice());
        let cutoff_edge_density_f32 = forward_cache
            .filter(|cache| cache.cutoff_edge_density.len() == cutoff_edge_density_len)
            .map(|cache| cache.cutoff_edge_density.as_slice());
        let raw_conv_tp_weights = if has_zero_cutoff {
            Some(self.edge_mlp_conv_tp_weights_forward_f32(
                conv_prefix,
                augmented_f32,
                input_dim,
                hidden_dim,
                tp_weight_dim,
            )?)
        } else {
            None
        };
        let mut bar_raw_conv_tp_weights = vec![0.0_f32; cutoff_conv_tp_weights_len];
        for (edge, cutoff_bar) in bar_edge_cutoff.iter_mut().enumerate().take(edge_count) {
            let cutoff = edge_input.edge_cutoff[edge] as f32;
            let row_start = edge * tp_weight_dim;
            let row_end = row_start + tp_weight_dim;
            let mut local_cutoff_bar = 0.0_f32;
            for index in row_start..row_end {
                let bar = bar_cutoff_conv_tp_weights[index] as f32;
                bar_raw_conv_tp_weights[index] += bar * cutoff;
                let raw_value = match raw_conv_tp_weights.as_ref() {
                    Some(raw) => raw[index],
                    None => {
                        cutoff_conv_tp_weights_f32
                            .map(|weights| weights[index])
                            .unwrap_or(cutoff_conv_tp_weights[index] as f32)
                            / cutoff
                    }
                };
                local_cutoff_bar += bar * raw_value;
            }
            *cutoff_bar += f64::from(local_cutoff_bar);
        }
        let mut bar_augmented_f32 = vec![0.0_f32; augmented_len];
        self.edge_mlp_conv_tp_weights_vjp_input_f32(
            conv_prefix,
            input_dim,
            hidden_dim,
            tp_weight_dim,
            augmented_f32,
            &bar_raw_conv_tp_weights,
            &mut bar_augmented_f32,
            forward_cache.map(|cache| &cache.conv_tp_weights),
        )?;

        let density_prefix = &format!("{interaction_prefix}.density_fn.net");
        let raw_edge_density = if has_zero_cutoff {
            Some(self.edge_mlp_density_forward_f32(
                density_prefix,
                augmented_f32,
                input_dim,
                hidden_dim,
            )?)
        } else {
            None
        };
        let mut bar_raw_edge_density = vec![0.0_f32; edge_count];
        for edge in 0..edge_count {
            let bar = bar_cutoff_edge_density[edge] as f32;
            let cutoff = edge_input.edge_cutoff[edge] as f32;
            bar_raw_edge_density[edge] += bar * cutoff;
            let raw_value = match raw_edge_density.as_ref() {
                Some(raw) => raw[edge],
                None => {
                    cutoff_edge_density_f32
                        .map(|density| density[edge])
                        .unwrap_or(cutoff_edge_density[edge] as f32)
                        / cutoff
                }
            };
            bar_edge_cutoff[edge] += f64::from(bar * raw_value);
        }
        self.edge_mlp_density_vjp_input_f32(
            density_prefix,
            input_dim,
            hidden_dim,
            augmented_f32,
            &bar_raw_edge_density,
            &mut bar_augmented_f32,
            forward_cache.map(|cache| &cache.density),
        )?;

        for (dst, &bar) in bar_augmented.iter_mut().zip(&bar_augmented_f32) {
            *dst += f64::from(bar);
        }

        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_layer_vjp_f32_bridge(
        &self,
        interaction_prefix: &str,
        input_dim: usize,
        hidden_dim: usize,
        tp_weight_dim: usize,
        edge_input: &MaceMh1EdgeInputBoundary,
        augmented: &[f64],
        cutoff_conv_tp_weights: &[f64],
        cutoff_edge_density: &[f64],
        forward_cache: Option<&MaceMh1EdgeMlpForwardCacheF32>,
        bar_cutoff_conv_tp_weights: &[f32],
        bar_cutoff_edge_density: &[f32],
        bar_edge_cutoff: &mut [f32],
        bar_augmented: &mut [f32],
    ) -> Result<(), MaceMh1Error> {
        let edge_count = if let Some(cache) = forward_cache {
            if cache.cutoff_edge_density.len() != edge_input.edge_count {
                return Err(invalid(format!(
                    "{interaction_prefix}.edge_mlp f32-bridge cached edge-density length mismatch"
                )));
            }
            edge_input.edge_count
        } else {
            checked_row_count(
                &format!("{interaction_prefix}.edge_mlp.augmented.f32_bridge_vjp"),
                augmented.len(),
                input_dim,
            )?
        };
        if edge_count != edge_input.edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-bridge augmented row count {edge_count} does not match edge_count {}",
                edge_input.edge_count
            )));
        }
        let augmented_len = edge_count * input_dim;
        let cutoff_conv_tp_weights_len = forward_cache
            .map_or(cutoff_conv_tp_weights.len(), |cache| {
                cache.cutoff_conv_tp_weights.len()
            });
        let cutoff_edge_density_len = forward_cache.map_or(cutoff_edge_density.len(), |cache| {
            cache.cutoff_edge_density.len()
        });
        if edge_input.edge_cutoff.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-bridge edge_cutoff length mismatch"
            )));
        }
        if cutoff_conv_tp_weights_len != edge_count * tp_weight_dim {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-bridge cutoff conv_tp weight length mismatch"
            )));
        }
        if cutoff_edge_density_len != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-bridge cutoff edge-density length mismatch"
            )));
        }
        if bar_edge_cutoff.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-bridge bar_edge_cutoff length mismatch"
            )));
        }
        if bar_augmented.len() != augmented_len {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-bridge bar_augmented length mismatch"
            )));
        }
        if bar_cutoff_conv_tp_weights.len() != edge_count * tp_weight_dim {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-bridge conv_tp weight bar length mismatch"
            )));
        }
        if bar_cutoff_edge_density.len() != edge_count {
            return Err(invalid(format!(
                "{interaction_prefix}.edge_mlp f32-bridge edge-density bar length mismatch"
            )));
        }

        let conv_prefix = &format!("{interaction_prefix}.conv_tp_weights.net");
        let augmented_f32 = if forward_cache.is_none() {
            Some(
                augmented
                    .iter()
                    .map(|&value| value as f32)
                    .collect::<Vec<_>>(),
            )
        } else {
            None
        };
        let augmented_f32 = augmented_f32.as_deref().unwrap_or(&[]);
        let cutoff_conv_tp_weights_f32 = forward_cache
            .filter(|cache| cache.cutoff_conv_tp_weights.len() == cutoff_conv_tp_weights_len)
            .map(|cache| cache.cutoff_conv_tp_weights.as_slice());
        let cutoff_edge_density_f32 = forward_cache
            .filter(|cache| cache.cutoff_edge_density.len() == cutoff_edge_density_len)
            .map(|cache| cache.cutoff_edge_density.as_slice());
        let mut bar_raw_conv_tp_weights = vec![0.0_f32; cutoff_conv_tp_weights_len];
        let mut local_bar_edge_cutoff = vec![0.0_f32; edge_count];
        mace_mh1_fill_conv_tp_cutoff_bars_f32(
            edge_count,
            tp_weight_dim,
            &edge_input.edge_cutoff,
            Some(cutoff_conv_tp_weights),
            cutoff_conv_tp_weights_f32,
            bar_cutoff_conv_tp_weights,
            &mut bar_raw_conv_tp_weights,
            &mut local_bar_edge_cutoff,
        );
        for (dst, src) in bar_edge_cutoff.iter_mut().zip(local_bar_edge_cutoff) {
            *dst += src;
        }
        let mut bar_augmented_f32 = vec![0.0_f32; augmented_len];
        self.edge_mlp_conv_tp_weights_vjp_input_f32(
            conv_prefix,
            input_dim,
            hidden_dim,
            tp_weight_dim,
            augmented_f32,
            &bar_raw_conv_tp_weights,
            &mut bar_augmented_f32,
            forward_cache.map(|cache| &cache.conv_tp_weights),
        )?;

        let density_prefix = &format!("{interaction_prefix}.density_fn.net");
        let mut bar_raw_edge_density = vec![0.0_f32; edge_count];
        for edge in 0..edge_count {
            let bar = bar_cutoff_edge_density[edge];
            let cutoff = edge_input.edge_cutoff[edge] as f32;
            bar_raw_edge_density[edge] += bar * cutoff;
            // See the Conv-TP weight note above: recover the pre-cutoff density from
            // the cached post-cutoff value, and skip cutoff == 0 edges.
            if cutoff != 0.0 {
                let cutoff_density = cutoff_edge_density_f32
                    .map(|density| density[edge])
                    .unwrap_or(cutoff_edge_density[edge] as f32);
                bar_edge_cutoff[edge] += bar * (cutoff_density / cutoff);
            }
        }
        self.edge_mlp_density_vjp_input_f32(
            density_prefix,
            input_dim,
            hidden_dim,
            augmented_f32,
            &bar_raw_edge_density,
            &mut bar_augmented_f32,
            forward_cache.map(|cache| &cache.density),
        )?;

        for (dst, &bar) in bar_augmented.iter_mut().zip(&bar_augmented_f32) {
            *dst += bar;
        }

        Ok(())
    }

    fn edge_mlp_conv_tp_weights_forward(
        &self,
        prefix: &str,
        augmented: &[f64],
        input_dim: usize,
        hidden_dim: usize,
        output_dim: usize,
    ) -> Result<Vec<f64>, MaceMh1Error> {
        let mut rows =
            self.torch_linear_rows(&format!("{prefix}.0"), augmented, input_dim, hidden_dim)?;
        rows = self.layer_norm_rows(&format!("{prefix}.1"), &rows, hidden_dim)?;
        apply_silu(&mut rows);
        rows = self.torch_linear_rows(&format!("{prefix}.3"), &rows, hidden_dim, hidden_dim)?;
        rows = self.layer_norm_rows(&format!("{prefix}.4"), &rows, hidden_dim)?;
        apply_silu(&mut rows);
        rows = self.torch_linear_rows(&format!("{prefix}.6"), &rows, hidden_dim, hidden_dim)?;
        rows = self.layer_norm_rows(&format!("{prefix}.7"), &rows, hidden_dim)?;
        apply_silu(&mut rows);
        self.torch_linear_rows(&format!("{prefix}.9"), &rows, hidden_dim, output_dim)
    }

    fn edge_mlp_conv_tp_weights_forward_with_cache(
        &self,
        prefix: &str,
        augmented: &[f64],
        input_dim: usize,
        hidden_dim: usize,
        output_dim: usize,
    ) -> Result<(Vec<f64>, Option<MaceMh1EdgeMlpConvTpWeightsCache>), MaceMh1Error> {
        let linear0 =
            self.torch_linear_rows(&format!("{prefix}.0"), augmented, input_dim, hidden_dim)?;
        let norm1 = self.layer_norm_rows(&format!("{prefix}.1"), &linear0, hidden_dim)?;
        let (mut rows, norm1_sigmoid) = silu_with_sigmoid_cache(&norm1);

        let linear3 =
            self.torch_linear_rows(&format!("{prefix}.3"), &rows, hidden_dim, hidden_dim)?;
        let norm4 = self.layer_norm_rows(&format!("{prefix}.4"), &linear3, hidden_dim)?;
        let (rows4_silu, norm4_sigmoid) = silu_with_sigmoid_cache(&norm4);
        rows = rows4_silu;

        let linear6 =
            self.torch_linear_rows(&format!("{prefix}.6"), &rows, hidden_dim, hidden_dim)?;
        let norm7 = self.layer_norm_rows(&format!("{prefix}.7"), &linear6, hidden_dim)?;
        let (rows7_silu, norm7_sigmoid) = silu_with_sigmoid_cache(&norm7);
        rows = rows7_silu;

        let output =
            self.torch_linear_rows(&format!("{prefix}.9"), &rows, hidden_dim, output_dim)?;
        Ok((
            output,
            Some(MaceMh1EdgeMlpConvTpWeightsCache {
                linear0,
                norm1,
                norm1_sigmoid,
                linear3,
                norm4,
                norm4_sigmoid,
                linear6,
                norm7,
                norm7_sigmoid,
            }),
        ))
    }

    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_conv_tp_weights_vjp_input(
        &self,
        prefix: &str,
        input_dim: usize,
        hidden_dim: usize,
        output_dim: usize,
        augmented: &[f64],
        bar_output: &[f64],
        bar_augmented: &mut [f64],
        cache: Option<&MaceMh1EdgeMlpConvTpWeightsCache>,
    ) -> Result<(), MaceMh1Error> {
        if let Some(cache) = cache {
            return self.edge_mlp_conv_tp_weights_vjp_input_cached(
                prefix,
                input_dim,
                hidden_dim,
                output_dim,
                bar_output,
                bar_augmented,
                cache,
            );
        }

        let mut rows0 =
            self.torch_linear_rows(&format!("{prefix}.0"), augmented, input_dim, hidden_dim)?;
        let rows1_input = rows0.clone();
        rows0 = self.layer_norm_rows(&format!("{prefix}.1"), &rows0, hidden_dim)?;
        let mut rows1_silu = rows0.clone();
        apply_silu(&mut rows1_silu);

        let mut rows3 =
            self.torch_linear_rows(&format!("{prefix}.3"), &rows1_silu, hidden_dim, hidden_dim)?;
        let rows4_input = rows3.clone();
        rows3 = self.layer_norm_rows(&format!("{prefix}.4"), &rows3, hidden_dim)?;
        let mut rows4_silu = rows3.clone();
        apply_silu(&mut rows4_silu);

        let mut rows6 =
            self.torch_linear_rows(&format!("{prefix}.6"), &rows4_silu, hidden_dim, hidden_dim)?;
        let rows7_input = rows6.clone();
        rows6 = self.layer_norm_rows(&format!("{prefix}.7"), &rows6, hidden_dim)?;
        let mut rows7_silu = rows6.clone();
        apply_silu(&mut rows7_silu);

        let mut bar_rows7_silu = vec![0.0; rows7_silu.len()];
        self.torch_linear_vjp_input(
            &format!("{prefix}.9"),
            hidden_dim,
            output_dim,
            bar_output,
            &mut bar_rows7_silu,
        )?;
        let mut bar_rows7 = vec![0.0; rows6.len()];
        for ((dst, &bar), &input) in bar_rows7.iter_mut().zip(&bar_rows7_silu).zip(&rows6) {
            *dst += bar * silu_derivative(input);
        }
        let mut bar_rows6 = vec![0.0; rows7_input.len()];
        self.layer_norm_vjp_input(
            &format!("{prefix}.7"),
            hidden_dim,
            &rows7_input,
            &bar_rows7,
            &mut bar_rows6,
        )?;

        let mut bar_rows4_silu = vec![0.0; rows4_silu.len()];
        self.torch_linear_vjp_input(
            &format!("{prefix}.6"),
            hidden_dim,
            hidden_dim,
            &bar_rows6,
            &mut bar_rows4_silu,
        )?;
        let mut bar_rows4 = vec![0.0; rows3.len()];
        for ((dst, &bar), &input) in bar_rows4.iter_mut().zip(&bar_rows4_silu).zip(&rows3) {
            *dst += bar * silu_derivative(input);
        }
        let mut bar_rows3 = vec![0.0; rows4_input.len()];
        self.layer_norm_vjp_input(
            &format!("{prefix}.4"),
            hidden_dim,
            &rows4_input,
            &bar_rows4,
            &mut bar_rows3,
        )?;

        let mut bar_rows1_silu = vec![0.0; rows1_silu.len()];
        self.torch_linear_vjp_input(
            &format!("{prefix}.3"),
            hidden_dim,
            hidden_dim,
            &bar_rows3,
            &mut bar_rows1_silu,
        )?;
        let mut bar_rows1 = vec![0.0; rows0.len()];
        for ((dst, &bar), &input) in bar_rows1.iter_mut().zip(&bar_rows1_silu).zip(&rows0) {
            *dst += bar * silu_derivative(input);
        }
        let mut bar_rows0 = vec![0.0; rows1_input.len()];
        self.layer_norm_vjp_input(
            &format!("{prefix}.1"),
            hidden_dim,
            &rows1_input,
            &bar_rows1,
            &mut bar_rows0,
        )?;
        self.torch_linear_vjp_input(
            &format!("{prefix}.0"),
            input_dim,
            hidden_dim,
            &bar_rows0,
            bar_augmented,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn edge_mlp_conv_tp_weights_vjp_input_cached(
        &self,
        prefix: &str,
        input_dim: usize,
        hidden_dim: usize,
        output_dim: usize,
        bar_output: &[f64],
        bar_augmented: &mut [f64],
        cache: &MaceMh1EdgeMlpConvTpWeightsCache,
    ) -> Result<(), MaceMh1Error> {
        let rows = checked_row_count(
            &format!("{prefix}.cached.conv_tp_weights.linear0"),
            cache.linear0.len(),
            hidden_dim,
        )?;
        if cache.norm1.len() != rows * hidden_dim
            || cache.norm1_sigmoid.len() != rows * hidden_dim
            || cache.linear3.len() != rows * hidden_dim
            || cache.norm4.len() != rows * hidden_dim
            || cache.norm4_sigmoid.len() != rows * hidden_dim
            || cache.linear6.len() != rows * hidden_dim
            || cache.norm7.len() != rows * hidden_dim
            || cache.norm7_sigmoid.len() != rows * hidden_dim
        {
            return Err(invalid(format!(
                "{prefix} cached conv_tp weight intermediates have inconsistent lengths"
            )));
        }
        if bar_output.len() != rows * output_dim {
            return Err(invalid(format!(
                "{prefix} bar_output length {} does not match cached rows {rows} * output_dim {output_dim}",
                bar_output.len()
            )));
        }
        if bar_augmented.len() != rows * input_dim {
            return Err(invalid(format!(
                "{prefix} bar_augmented length {} does not match cached rows {rows} * input_dim {input_dim}",
                bar_augmented.len()
            )));
        }

        let mut bar_rows7_silu = vec![0.0; cache.norm7.len()];
        self.torch_linear_vjp_input(
            &format!("{prefix}.9"),
            hidden_dim,
            output_dim,
            bar_output,
            &mut bar_rows7_silu,
        )?;
        for ((bar, &input), &sigmoid_value) in bar_rows7_silu
            .iter_mut()
            .zip(&cache.norm7)
            .zip(&cache.norm7_sigmoid)
        {
            *bar *= silu_derivative_from_sigmoid(input, sigmoid_value);
        }
        let mut bar_rows6 = vec![0.0; cache.linear6.len()];
        self.layer_norm_vjp_input(
            &format!("{prefix}.7"),
            hidden_dim,
            &cache.linear6,
            &bar_rows7_silu,
            &mut bar_rows6,
        )?;

        let mut bar_rows4_silu = vec![0.0; cache.norm4.len()];
        self.torch_linear_vjp_input(
            &format!("{prefix}.6"),
            hidden_dim,
            hidden_dim,
            &bar_rows6,
            &mut bar_rows4_silu,
        )?;
        for ((bar, &input), &sigmoid_value) in bar_rows4_silu
            .iter_mut()
            .zip(&cache.norm4)
            .zip(&cache.norm4_sigmoid)
        {
            *bar *= silu_derivative_from_sigmoid(input, sigmoid_value);
        }
        let mut bar_rows3 = vec![0.0; cache.linear3.len()];
        self.layer_norm_vjp_input(
            &format!("{prefix}.4"),
            hidden_dim,
            &cache.linear3,
            &bar_rows4_silu,
            &mut bar_rows3,
        )?;

        let mut bar_rows1_silu = vec![0.0; cache.norm1.len()];
        self.torch_linear_vjp_input(
            &format!("{prefix}.3"),
            hidden_dim,
            hidden_dim,
            &bar_rows3,
            &mut bar_rows1_silu,
        )?;
        for ((bar, &input), &sigmoid_value) in bar_rows1_silu
            .iter_mut()
            .zip(&cache.norm1)
            .zip(&cache.norm1_sigmoid)
        {
            *bar *= silu_derivative_from_sigmoid(input, sigmoid_value);
        }
        let mut bar_rows0 = vec![0.0; cache.linear0.len()];
        self.layer_norm_vjp_input(
            &format!("{prefix}.1"),
            hidden_dim,
            &cache.linear0,
            &bar_rows1_silu,
            &mut bar_rows0,
        )?;
        self.torch_linear_vjp_input(
            &format!("{prefix}.0"),
            input_dim,
            hidden_dim,
            &bar_rows0,
            bar_augmented,
        )
    }

