    fn edge_input_vjp_from_edge_mlp(
        &self,
        forward: &MaceMh1ForwardCache,
        edge_mlp: MaceMh1EdgeMlpVjp,
    ) -> Result<MaceMh1EdgeInputVjp, MaceMh1Error> {
        let edge_count = forward.edge_boundary.edge_count;
        validate_edge_input_geometry(&forward.edge_boundary, "MACE-MH-1 edge input VJP")?;
        if edge_mlp.bar_edge_feats.len() != edge_count * MACE_MH1_NUM_BESSEL {
            return Err(invalid(
                "MACE-MH-1 edge input VJP radial bar length mismatch",
            ));
        }
        if edge_mlp.bar_edge_cutoff.len() != edge_count {
            return Err(invalid(
                "MACE-MH-1 edge input VJP cutoff bar length mismatch",
            ));
        }
        if edge_mlp
            .conv_tp
            .post_scatter
            .tail
            .product
            .bar_pair_node_energy
            .len()
            != forward.edge_boundary.pair_node_energy.len()
        {
            return Err(invalid(
                "MACE-MH-1 edge input VJP pair-node-energy bar length mismatch",
            ));
        }

        let sh_plan = SphericalHarmonicsPlan::component(L_MAX, true)?;
        let mut bar_edge_vectors = vec![[0.0; 3]; edge_count];
        let mut bar_edge_distances = vec![0.0; edge_count];
        let pair_node_bars = &edge_mlp
            .conv_tp
            .post_scatter
            .tail
            .product
            .bar_pair_node_energy;
        let pair_cutoff_p = self.positive_usize_scalar("pair_repulsion_fn.p")?;
        let radial_cutoff_radius = self.f64_scalar("radial_embedding.cutoff_fn.r_max")?;
        let radial_cutoff_p = self.positive_usize_scalar("radial_embedding.cutoff_fn.p")?;
        let bessel_weights = self.f64_tensor(
            "radial_embedding.bessel_fn.bessel_weights",
            &[MACE_MH1_NUM_BESSEL],
        )?;
        let bessel_prefactor = self.f64_scalar("radial_embedding.bessel_fn.prefactor")?;
        let agnesi_q = self.f64_scalar("radial_embedding.distance_transform.q")?;
        let agnesi_p = self.f64_scalar("radial_embedding.distance_transform.p")?;
        let agnesi_a = self.f64_scalar("radial_embedding.distance_transform.a")?;
        let agnesi_covalent_radii =
            self.f64_tensor("radial_embedding.distance_transform.covalent_radii", &[119])?;
        let pair_coefficients = self.f64_tensor("pair_repulsion_fn.c", &[4])?;
        let pair_a_exp = self.f64_scalar("pair_repulsion_fn.a_exp")?;
        let pair_a_prefactor = self.f64_scalar("pair_repulsion_fn.a_prefactor")?;
        let pair_covalent_radii = self.f64_tensor("pair_repulsion_fn.covalent_radii", &[119])?;

        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && edge_count >= MACE_MH1_EDGE_INPUT_PARALLEL_MIN_EDGES
        {
            bar_edge_vectors
                .par_iter_mut()
                .zip(bar_edge_distances.par_iter_mut())
                .enumerate()
                .try_for_each(|(edge, (bar_edge_vector, bar_edge_distance))| {
                    let edge_vector = forward.edge_boundary.edge_vectors[edge];
                    let distance = forward.edge_boundary.edge_distances[edge];
                    let src_z = forward.edge_boundary.edge_src_atomic_numbers[edge];
                    let dst_z = forward.edge_boundary.edge_dst_atomic_numbers[edge];

                    let sh_bar_start = edge * MACE_MH1_SH_DIM;
                    let sh_bar_end = sh_bar_start + MACE_MH1_SH_DIM;
                    sh_plan.vjp_edge_vector(
                        edge_vector,
                        &edge_mlp.conv_tp.bar_edge_attrs[sh_bar_start..sh_bar_end],
                        bar_edge_vector,
                    )?;

                    let radial_start = edge * MACE_MH1_NUM_BESSEL;
                    let radial_end = radial_start + MACE_MH1_NUM_BESSEL;
                    let mut bar_distance = mace_mh1_radial_embedding_vjp_distance_from_parts(
                        distance,
                        src_z,
                        dst_z,
                        &forward.edge_boundary.edge_feats[radial_start..radial_end],
                        &edge_mlp.bar_edge_feats[radial_start..radial_end],
                        edge_mlp.bar_edge_cutoff[edge],
                        agnesi_q,
                        agnesi_p,
                        agnesi_a,
                        agnesi_covalent_radii,
                        radial_cutoff_radius,
                        radial_cutoff_p,
                        bessel_weights,
                        bessel_prefactor,
                    )?;

                    let dst = forward.edge_boundary.edge_dst[edge];
                    if dst >= pair_node_bars.len() {
                        return Err(invalid(format!(
                            "MACE-MH-1 edge input VJP edge {edge} target {dst} out of range for {} pair-node bars",
                            pair_node_bars.len()
                        )));
                    }
                    let pair_output = mace_zbl_edge_energy_forward_from_parts(
                        distance,
                        src_z,
                        dst_z,
                        pair_cutoff_p,
                        pair_coefficients,
                        pair_a_exp,
                        pair_a_prefactor,
                        pair_covalent_radii,
                    )?;
                    bar_distance += pair_node_bars[dst] * pair_output.derivative;
                    *bar_edge_distance = bar_distance;
                    distance_vjp_accumulate(
                        edge_vector,
                        bar_distance,
                        DISTANCE_EPS,
                        bar_edge_vector,
                    )?;
                    Ok::<(), MaceMh1Error>(())
                })?;

            return Ok(MaceMh1EdgeInputVjp {
                edge_mlp,
                bar_edge_vectors,
                bar_edge_distances,
            });
        }

        for edge in 0..edge_count {
            let edge_vector = forward.edge_boundary.edge_vectors[edge];
            let distance = forward.edge_boundary.edge_distances[edge];
            let src_z = forward.edge_boundary.edge_src_atomic_numbers[edge];
            let dst_z = forward.edge_boundary.edge_dst_atomic_numbers[edge];

            let sh_bar_start = edge * MACE_MH1_SH_DIM;
            let sh_bar_end = sh_bar_start + MACE_MH1_SH_DIM;
            sh_plan.vjp_edge_vector(
                edge_vector,
                &edge_mlp.conv_tp.bar_edge_attrs[sh_bar_start..sh_bar_end],
                &mut bar_edge_vectors[edge],
            )?;

            let radial_start = edge * MACE_MH1_NUM_BESSEL;
            let radial_end = radial_start + MACE_MH1_NUM_BESSEL;
            let mut bar_distance = mace_mh1_radial_embedding_vjp_distance_from_parts(
                distance,
                src_z,
                dst_z,
                &forward.edge_boundary.edge_feats[radial_start..radial_end],
                &edge_mlp.bar_edge_feats[radial_start..radial_end],
                edge_mlp.bar_edge_cutoff[edge],
                agnesi_q,
                agnesi_p,
                agnesi_a,
                agnesi_covalent_radii,
                radial_cutoff_radius,
                radial_cutoff_p,
                bessel_weights,
                bessel_prefactor,
            )?;

            let dst = forward.edge_boundary.edge_dst[edge];
            if dst >= pair_node_bars.len() {
                return Err(invalid(format!(
                    "MACE-MH-1 edge input VJP edge {edge} target {dst} out of range for {} pair-node bars",
                    pair_node_bars.len()
                )));
            }
            let pair_output = mace_zbl_edge_energy_forward_from_parts(
                distance,
                src_z,
                dst_z,
                pair_cutoff_p,
                pair_coefficients,
                pair_a_exp,
                pair_a_prefactor,
                pair_covalent_radii,
            )?;
            bar_distance += pair_node_bars[dst] * pair_output.derivative;
            bar_edge_distances[edge] = bar_distance;
            distance_vjp_accumulate(
                edge_vector,
                bar_distance,
                DISTANCE_EPS,
                &mut bar_edge_vectors[edge],
            )?;
        }

        Ok(MaceMh1EdgeInputVjp {
            edge_mlp,
            bar_edge_vectors,
            bar_edge_distances,
        })
    }

    fn forces_and_displacement_gradient_from_edge_mlp_vjp_f32_bridge(
        &self,
        forward: &MaceMh1ForwardCache,
        edge_mlp: MaceMh1EdgeMlpForceVjpF32Bridge,
        compute_displacement_gradient: bool,
        emit_forces: bool,
    ) -> Result<MaceMh1ForceReplay, MaceMh1Error> {
        let edge_count = forward.edge_boundary.edge_count;
        validate_edge_input_geometry(&forward.edge_boundary, "MACE-MH-1 f32 bridge force VJP")?;
        if edge_mlp.bar_edge_feats.len() != edge_count * MACE_MH1_NUM_BESSEL {
            return Err(invalid(
                "MACE-MH-1 f32 bridge force VJP radial bar length mismatch",
            ));
        }
        if edge_mlp.bar_edge_cutoff.len() != edge_count {
            return Err(invalid(
                "MACE-MH-1 f32 bridge force VJP cutoff bar length mismatch",
            ));
        }
        if edge_mlp.conv_tp.bar_edge_attrs.len() != edge_count * MACE_MH1_SH_DIM {
            return Err(invalid(
                "MACE-MH-1 f32 bridge force VJP SH bar length mismatch",
            ));
        }
        if edge_mlp.conv_tp.bar_pair_node_energy.len()
            != forward.edge_boundary.pair_node_energy.len()
        {
            return Err(invalid(
                "MACE-MH-1 f32 bridge force VJP pair-node-energy bar length mismatch",
            ));
        }
        if forward.edge_boundary.edge_src.len() != edge_count
            || forward.edge_boundary.edge_dst.len() != edge_count
        {
            return Err(invalid(
                "MACE-MH-1 f32 bridge force VJP edge index length mismatch",
            ));
        }

        let sh_plan = SphericalHarmonicsPlan::component(L_MAX, true)?;
        let mut bar_edge_vectors = vec![[0.0; 3]; edge_count];
        let pair_node_bars = &edge_mlp.conv_tp.bar_pair_node_energy;
        let pair_cutoff_p = self.positive_usize_scalar("pair_repulsion_fn.p")?;
        let radial_cutoff_radius = self.f64_scalar("radial_embedding.cutoff_fn.r_max")?;
        let radial_cutoff_p = self.positive_usize_scalar("radial_embedding.cutoff_fn.p")?;
        let bessel_weights = self.f64_tensor(
            "radial_embedding.bessel_fn.bessel_weights",
            &[MACE_MH1_NUM_BESSEL],
        )?;
        let bessel_prefactor = self.f64_scalar("radial_embedding.bessel_fn.prefactor")?;
        let agnesi_q = self.f64_scalar("radial_embedding.distance_transform.q")?;
        let agnesi_p = self.f64_scalar("radial_embedding.distance_transform.p")?;
        let agnesi_a = self.f64_scalar("radial_embedding.distance_transform.a")?;
        let agnesi_covalent_radii =
            self.f64_tensor("radial_embedding.distance_transform.covalent_radii", &[119])?;
        let pair_coefficients = self.f64_tensor("pair_repulsion_fn.c", &[4])?;
        let pair_a_exp = self.f64_scalar("pair_repulsion_fn.a_exp")?;
        let pair_a_prefactor = self.f64_scalar("pair_repulsion_fn.a_prefactor")?;
        let pair_covalent_radii = self.f64_tensor("pair_repulsion_fn.covalent_radii", &[119])?;

        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && edge_count >= MACE_MH1_EDGE_INPUT_PARALLEL_MIN_EDGES
        {
            bar_edge_vectors
                .par_iter_mut()
                .enumerate()
                .try_for_each(|(edge, bar_edge_vector)| {
                    let edge_vector = forward.edge_boundary.edge_vectors[edge];
                    let distance = forward.edge_boundary.edge_distances[edge];
                    let src_z = forward.edge_boundary.edge_src_atomic_numbers[edge];
                    let dst_z = forward.edge_boundary.edge_dst_atomic_numbers[edge];

                    let sh_bar_start = edge * MACE_MH1_SH_DIM;
                    let mut sh_bar = [0.0; MACE_MH1_SH_DIM];
                    for (dst, &src) in sh_bar.iter_mut().zip(
                        &edge_mlp.conv_tp.bar_edge_attrs
                            [sh_bar_start..sh_bar_start + MACE_MH1_SH_DIM],
                    ) {
                        *dst = f64::from(src);
                    }
                    sh_plan.vjp_edge_vector(edge_vector, &sh_bar, bar_edge_vector)?;

                    let radial_start = edge * MACE_MH1_NUM_BESSEL;
                    let radial_end = radial_start + MACE_MH1_NUM_BESSEL;
                    let mut bar_edge_feats = [0.0; MACE_MH1_NUM_BESSEL];
                    for (dst, &src) in bar_edge_feats
                        .iter_mut()
                        .zip(&edge_mlp.bar_edge_feats[radial_start..radial_end])
                    {
                        *dst = f64::from(src);
                    }
                    let mut bar_distance = mace_mh1_radial_embedding_vjp_distance_from_parts(
                        distance,
                        src_z,
                        dst_z,
                        &forward.edge_boundary.edge_feats[radial_start..radial_end],
                        &bar_edge_feats,
                        f64::from(edge_mlp.bar_edge_cutoff[edge]),
                        agnesi_q,
                        agnesi_p,
                        agnesi_a,
                        agnesi_covalent_radii,
                        radial_cutoff_radius,
                        radial_cutoff_p,
                        bessel_weights,
                        bessel_prefactor,
                    )?;

                    let dst = forward.edge_boundary.edge_dst[edge];
                    if dst >= pair_node_bars.len() {
                        return Err(invalid(format!(
                            "MACE-MH-1 f32 bridge force VJP edge {edge} target {dst} out of range for {} pair-node bars",
                            pair_node_bars.len()
                        )));
                    }
                    let pair_output = mace_zbl_edge_energy_forward_from_parts(
                        distance,
                        src_z,
                        dst_z,
                        pair_cutoff_p,
                        pair_coefficients,
                        pair_a_exp,
                        pair_a_prefactor,
                        pair_covalent_radii,
                    )?;
                    bar_distance += pair_node_bars[dst] * pair_output.derivative;
                    distance_vjp_accumulate(
                        edge_vector,
                        bar_distance,
                        DISTANCE_EPS,
                        bar_edge_vector,
                    )?;
                    Ok::<(), MaceMh1Error>(())
                })?;
        }

        #[cfg(not(feature = "parallel"))]
        let use_serial_force_bridge = true;
        #[cfg(feature = "parallel")]
        let use_serial_force_bridge = !(rayon::current_num_threads() > 1
            && edge_count >= MACE_MH1_EDGE_INPUT_PARALLEL_MIN_EDGES);
        if use_serial_force_bridge {
            for (edge, bar_edge_vector) in bar_edge_vectors.iter_mut().enumerate() {
                let edge_vector = forward.edge_boundary.edge_vectors[edge];
                let distance = forward.edge_boundary.edge_distances[edge];
                let src_z = forward.edge_boundary.edge_src_atomic_numbers[edge];
                let dst_z = forward.edge_boundary.edge_dst_atomic_numbers[edge];

                let sh_bar_start = edge * MACE_MH1_SH_DIM;
                let mut sh_bar = [0.0; MACE_MH1_SH_DIM];
                for (dst, &src) in sh_bar.iter_mut().zip(
                    &edge_mlp.conv_tp.bar_edge_attrs[sh_bar_start..sh_bar_start + MACE_MH1_SH_DIM],
                ) {
                    *dst = f64::from(src);
                }
                sh_plan.vjp_edge_vector(edge_vector, &sh_bar, bar_edge_vector)?;

                let radial_start = edge * MACE_MH1_NUM_BESSEL;
                let radial_end = radial_start + MACE_MH1_NUM_BESSEL;
                let mut bar_edge_feats = [0.0; MACE_MH1_NUM_BESSEL];
                for (dst, &src) in bar_edge_feats
                    .iter_mut()
                    .zip(&edge_mlp.bar_edge_feats[radial_start..radial_end])
                {
                    *dst = f64::from(src);
                }
                let mut bar_distance = mace_mh1_radial_embedding_vjp_distance_from_parts(
                    distance,
                    src_z,
                    dst_z,
                    &forward.edge_boundary.edge_feats[radial_start..radial_end],
                    &bar_edge_feats,
                    f64::from(edge_mlp.bar_edge_cutoff[edge]),
                    agnesi_q,
                    agnesi_p,
                    agnesi_a,
                    agnesi_covalent_radii,
                    radial_cutoff_radius,
                    radial_cutoff_p,
                    bessel_weights,
                    bessel_prefactor,
                )?;

                let dst = forward.edge_boundary.edge_dst[edge];
                if dst >= pair_node_bars.len() {
                    return Err(invalid(format!(
                        "MACE-MH-1 f32 bridge force VJP edge {edge} target {dst} out of range for {} pair-node bars",
                        pair_node_bars.len()
                    )));
                }
                let pair_output = mace_zbl_edge_energy_forward_from_parts(
                    distance,
                    src_z,
                    dst_z,
                    pair_cutoff_p,
                    pair_coefficients,
                    pair_a_exp,
                    pair_a_prefactor,
                    pair_covalent_radii,
                )?;
                bar_distance += pair_node_bars[dst] * pair_output.derivative;
                distance_vjp_accumulate(edge_vector, bar_distance, DISTANCE_EPS, bar_edge_vector)?;
            }
        }

        let mut forces = emit_forces.then(|| vec![[0.0; 3]; forward.type_ids.len()]);
        let mut force_comp = emit_forces.then(|| vec![[0.0; 3]; forward.type_ids.len()]);
        let mut displacement_gradient = [[0.0; 3]; 3];
        for (edge, &bar_edge_vector) in bar_edge_vectors.iter().enumerate() {
            if let (Some(forces), Some(force_comp)) = (&mut forces, &mut force_comp) {
                scatter_edge_vector_vjp_compensated(
                    forward.edge_boundary.edge_src[edge],
                    forward.edge_boundary.edge_dst[edge],
                    bar_edge_vector,
                    forces,
                    force_comp,
                )?;
            }
            if compute_displacement_gradient {
                accumulate_edge_displacement_gradient(
                    forward.edge_boundary.edge_vectors[edge],
                    bar_edge_vector,
                    &mut displacement_gradient,
                );
            }
        }
        Ok(MaceMh1ForceReplay {
            forces: forces.unwrap_or_default(),
            displacement_gradient,
        })
    }

    #[allow(dead_code)]
    fn forces_from_forward_cache(
        &self,
        forward: &MaceMh1ForwardCache,
    ) -> Result<Vec<[f64; 3]>, MaceMh1Error> {
        self.forces_and_displacement_gradient_from_forward_cache(forward, false, true)
            .map(|replay| replay.forces)
    }

    fn forces_and_displacement_gradient_from_forward_cache(
        &self,
        forward: &MaceMh1ForwardCache,
        compute_displacement_gradient: bool,
        emit_forces: bool,
    ) -> Result<MaceMh1ForceReplay, MaceMh1Error> {
        let trace_timings = mace_mh1_trace_timings_enabled();
        let total_start = trace_timings.then(Instant::now);
        let edge_mlp_start = trace_timings.then(Instant::now);
        let vjp = self.edge_input_vjp_with_interaction_input_linears_force_bridge(forward)?;
        mace_mh1_trace_stage("forces.edge_mlp_vjp_chain", edge_mlp_start);
        let force_scatter_start = trace_timings.then(Instant::now);
        let replay = self.forces_from_edge_input_vjp(
            forward,
            vjp,
            compute_displacement_gradient,
            emit_forces,
        )?;
        mace_mh1_trace_stage("forces.edge_input_force_scatter", force_scatter_start);
        mace_mh1_trace_stage("forces.total", total_start);
        Ok(replay)
    }

