fn mace_mh1_equivariant_linear_weight_len(
    instructions: &[MaceMh1EquivariantLinearInstruction],
) -> usize {
    instructions
        .iter()
        .map(|instruction| {
            instruction.weight_offset + instruction.input_features * instruction.output_features
        })
        .max()
        .unwrap_or(0)
}

fn mace_mh1_equivariant_linear_path_weights(
    instructions: &[MaceMh1EquivariantLinearInstruction],
) -> Vec<f64> {
    instructions
        .iter()
        .map(|instruction| {
            let input_features_for_output = instructions
                .iter()
                .filter(|candidate| {
                    candidate.output_offset == instruction.output_offset
                        && candidate.output_features == instruction.output_features
                        && candidate.dim == instruction.dim
                })
                .map(|candidate| candidate.input_features)
                .sum::<usize>();
            1.0 / (input_features_for_output as f64).sqrt()
        })
        .collect()
}

#[cfg(feature = "parallel")]
fn mace_mh1_conv_tp_forward_accumulate_unmasked_fast(
    plan: &TensorProductPlan,
    layouts: &TensorProductLayouts,
    source_row: &[f64],
    edge_attr: &[f64],
    weights: &[f64],
    out: &mut [f64],
) {
    debug_assert_eq!(source_row.len(), plan.input1_dim());
    debug_assert_eq!(edge_attr.len(), plan.input2_dim());
    debug_assert_eq!(weights.len(), plan.weight_numel);
    debug_assert_eq!(out.len(), plan.output_dim());

    for instruction in &plan.instructions {
        let in1 = layouts.in1[instruction.in1_segment];
        let in2 = layouts.in2[instruction.in2_segment];
        let out_segment = layouts.out[instruction.out_segment];
        let weight = match instruction.weight_offset {
            Some(offset) => weights[offset],
            None => 1.0,
        };
        let scale = instruction.path_weight * weight;
        let cg_end = instruction.cg_offset + instruction.cg_len;
        for cg in &plan.cg_entries[instruction.cg_offset..cg_end] {
            out[out_segment.start + cg.k_m] +=
                scale * cg.value * source_row[in1.start + cg.i_m] * edge_attr[in2.start + cg.j_m];
        }
    }
}

