#[inline(always)]
fn mace_mh1_conv_tp_forward_accumulate_chunked_unmasked(
    plan: &TensorProductPlan,
    chunks: &[MaceMh1ConvTpChunk],
    channels: usize,
    source_row: &[f64],
    edge_attr: &[f64],
    weights: &[f64],
    out: &mut [f64],
) {
    for chunk in chunks {
        let cg_end = chunk.cg_offset + chunk.cg_len;
        let cg_entries = &plan.cg_entries[chunk.cg_offset..cg_end];
        for channel in 0..channels {
            let x_base = chunk.in1_base + channel * chunk.in1_stride;
            let out_base = chunk.out_base + channel * chunk.out_stride;
            let weight = weights[chunk.weight_base + channel];
            let weighted_path = chunk.path_weight * weight;
            for cg in cg_entries {
                out[out_base + cg.k_m] += weighted_path
                    * cg.value
                    * source_row[x_base + cg.i_m]
                    * edge_attr[chunk.in2_base + cg.j_m];
            }
        }
    }
}

