#[allow(dead_code, clippy::too_many_arguments)]
#[inline(always)]
fn mace_mh1_conv_tp_forward_accumulate_selected_f32(
    prefix: &str,
    plan: &TensorProductPlan,
    layouts: Option<&TensorProductLayouts>,
    tp_weight_dim: usize,
    source_row: &[f32],
    edge_attr: &[f32],
    weights: &[f32],
    out: &mut [f32],
) -> Result<(), MaceMh1Error> {
    match tp_weight_dim {
        MACE_MH1_INTERACTION0_TP_WEIGHT_DIM => {
            mace_mh1_conv_tp_forward_accumulate_interaction0_unmasked_f32(
                plan, source_row, edge_attr, weights, out,
            );
        }
        MACE_MH1_INTERACTION1_TP_WEIGHT_DIM => {
            mace_mh1_conv_tp_forward_accumulate_interaction1_unmasked_f32(
                plan, source_row, edge_attr, weights, out,
            );
        }
        _ => {
            let Some(layouts) = layouts else {
                return Err(invalid(format!(
                    "{prefix}.f32 generic Conv-TP layouts were not prepared"
                )));
            };
            mace_mh1_conv_tp_forward_accumulate_unmasked_fast_f32(
                plan, layouts, source_row, edge_attr, weights, out,
            );
        }
    }
    Ok(())
}

