#[allow(dead_code, clippy::too_many_arguments)]
fn mace_mh1_conv_tp_forward_scatter_f32(
    prefix: &str,
    plan: &TensorProductPlan,
    linear_up_dim: usize,
    tp_output_dim: usize,
    tp_weight_dim: usize,
    edge_src: &[usize],
    edge_dst: &[usize],
    edge_attrs: &[f32],
    linear_up: &[f32],
    conv_tp_weights: &[f32],
    node_count: usize,
    output_mask: Option<&[f32]>,
    scatter_message: &mut [f32],
) -> Result<(), MaceMh1Error> {
    let edge_count = edge_src.len();
    if edge_dst.len() != edge_count {
        return Err(invalid(format!(
            "{prefix}.f32 edge_src length {edge_count} does not match edge_dst length {}",
            edge_dst.len()
        )));
    }
    if edge_attrs.len() != edge_count * MACE_MH1_SH_DIM {
        return Err(invalid(format!(
            "{prefix}.f32 edge_attrs length {} does not match edge_count {edge_count} * sh_dim {}",
            edge_attrs.len(),
            MACE_MH1_SH_DIM
        )));
    }
    if linear_up.len() != node_count * linear_up_dim {
        return Err(invalid(format!(
            "{prefix}.f32 linear_up length {} does not match node_count {node_count} * linear_up_dim {linear_up_dim}",
            linear_up.len()
        )));
    }
    if conv_tp_weights.len() != edge_count * tp_weight_dim {
        return Err(invalid(format!(
            "{prefix}.f32 conv_tp_weights length {} does not match edge_count {edge_count} * tp_weight_dim {tp_weight_dim}",
            conv_tp_weights.len()
        )));
    }
    if scatter_message.len() != node_count * tp_output_dim {
        return Err(invalid(format!(
            "{prefix}.f32 scatter_message length {} does not match node_count {node_count} * tp_output_dim {tp_output_dim}",
            scatter_message.len()
        )));
    }
    if let Some(mask) = output_mask {
        if mask.len() != tp_output_dim {
            return Err(invalid(format!(
                "{prefix}.f32 output_mask length {} does not match tp_output_dim {tp_output_dim}",
                mask.len()
            )));
        }
    }

    let layouts = if tp_weight_dim == MACE_MH1_INTERACTION0_TP_WEIGHT_DIM
        || tp_weight_dim == MACE_MH1_INTERACTION1_TP_WEIGHT_DIM
    {
        None
    } else {
        Some(plan.checked_layouts()?)
    };
    scatter_message.fill(0.0);
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && edge_count >= MACE_MH1_CONV_TP_VJP_PARALLEL_MIN_EDGES {
        let mut edges_by_dst = vec![Vec::new(); node_count];
        for edge in 0..edge_count {
            let src = edge_src[edge];
            let dst = edge_dst[edge];
            if src >= node_count || dst >= node_count {
                return Err(invalid(format!(
                    "{prefix}.f32 edge {edge} index {src}->{dst} is out of range for {node_count} nodes"
                )));
            }
            edges_by_dst[dst].push(edge);
        }
        scatter_message
            .par_chunks_mut(tp_output_dim)
            .enumerate()
            .try_for_each(|(dst, scatter_row)| -> Result<(), MaceMh1Error> {
                let mut scratch_message = output_mask.map(|_| vec![0.0_f32; tp_output_dim]);
                for &edge in &edges_by_dst[dst] {
                    let src = edge_src[edge];
                    let source_row = &linear_up[src * linear_up_dim..(src + 1) * linear_up_dim];
                    let edge_attr =
                        &edge_attrs[edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM];
                    let weights =
                        &conv_tp_weights[edge * tp_weight_dim..(edge + 1) * tp_weight_dim];
                    if let Some(mask) = output_mask {
                        let Some(scratch) = scratch_message.as_mut() else {
                            return Err(invalid(format!(
                                "{prefix}.f32 masked Conv-TP scratch was not allocated"
                            )));
                        };
                        scratch.fill(0.0);
                        mace_mh1_conv_tp_forward_accumulate_selected_f32(
                            prefix,
                            plan,
                            layouts.as_ref(),
                            tp_weight_dim,
                            source_row,
                            edge_attr,
                            weights,
                            scratch,
                        )?;
                        for ((dst, &value), &mask_value) in
                            scatter_row.iter_mut().zip(scratch.iter()).zip(mask)
                        {
                            *dst += value * mask_value;
                        }
                    } else {
                        mace_mh1_conv_tp_forward_accumulate_selected_f32(
                            prefix,
                            plan,
                            layouts.as_ref(),
                            tp_weight_dim,
                            source_row,
                            edge_attr,
                            weights,
                            scatter_row,
                        )?;
                    }
                }
                Ok(())
            })?;
        return Ok(());
    }
    let mut scratch_message = output_mask.map(|_| vec![0.0_f32; tp_output_dim]);
    for edge in 0..edge_count {
        let src = edge_src[edge];
        let dst = edge_dst[edge];
        if src >= node_count || dst >= node_count {
            return Err(invalid(format!(
                "{prefix}.f32 edge {edge} index {src}->{dst} is out of range for {node_count} nodes"
            )));
        }
        let source_row = &linear_up[src * linear_up_dim..(src + 1) * linear_up_dim];
        let edge_attr = &edge_attrs[edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM];
        let weights = &conv_tp_weights[edge * tp_weight_dim..(edge + 1) * tp_weight_dim];
        let scatter_row = &mut scatter_message[dst * tp_output_dim..(dst + 1) * tp_output_dim];
        if let Some(mask) = output_mask {
            let Some(scratch) = scratch_message.as_mut() else {
                return Err(invalid(format!(
                    "{prefix}.f32 masked Conv-TP scratch was not allocated"
                )));
            };
            scratch.fill(0.0);
            mace_mh1_conv_tp_forward_accumulate_selected_f32(
                prefix,
                plan,
                layouts.as_ref(),
                tp_weight_dim,
                source_row,
                edge_attr,
                weights,
                scratch,
            )?;
            for ((dst, &value), &mask_value) in scatter_row.iter_mut().zip(scratch.iter()).zip(mask)
            {
                *dst += value * mask_value;
            }
        } else {
            mace_mh1_conv_tp_forward_accumulate_selected_f32(
                prefix,
                plan,
                layouts.as_ref(),
                tp_weight_dim,
                source_row,
                edge_attr,
                weights,
                scatter_row,
            )?;
        }
    }
    Ok(())
}

#[cfg(feature = "parallel")]
#[allow(clippy::too_many_arguments)]
fn mace_mh1_conv_tp_forward_scatter_parallel(
    prefix: &str,
    plan: &TensorProductPlan,
    linear_up_dim: usize,
    tp_output_dim: usize,
    tp_weight_dim: usize,
    edge_input: &MaceMh1EdgeInputBoundary,
    linear_up: &[f64],
    conv_tp_weights: &[f64],
    output_mask: &[f64],
    node_count: usize,
    capture_edge_messages: bool,
    can_direct_scatter: bool,
) -> Result<(Vec<f64>, Vec<f64>), MaceMh1Error> {
    let layouts = plan.checked_layouts()?;
    let target_chunks = rayon::current_num_threads().max(1);
    let chunk_len = edge_input.edge_count.div_ceil(target_chunks).max(1);
    let ranges = (0..edge_input.edge_count)
        .step_by(chunk_len)
        .map(|start| (start, (start + chunk_len).min(edge_input.edge_count)))
        .collect::<Vec<_>>();

    let partials = ranges
        .into_par_iter()
        .map(
            |(edge_start, edge_end)| -> Result<MaceMh1ConvTpForwardChunk, MaceMh1Error> {
                let edge_len = edge_end - edge_start;
                let mut local_edge_messages = if capture_edge_messages {
                    vec![0.0; edge_len * tp_output_dim]
                } else {
                    Vec::new()
                };
                let mut local_scatter_message = vec![0.0; node_count * tp_output_dim];
                let mut scratch_message = vec![0.0; tp_output_dim];
                let mut message_compensation = vec![0.0; tp_output_dim];
                for edge in edge_start..edge_end {
                    let src = edge_input.edge_src[edge];
                    let dst = edge_input.edge_dst[edge];
                    if src >= node_count || dst >= node_count {
                        return Err(invalid(format!(
                            "{prefix} edge {edge} index {src}->{dst} is out of range for {node_count} nodes"
                        )));
                    }
                    let source_row = &linear_up[src * linear_up_dim..(src + 1) * linear_up_dim];
                    let edge_attr = &edge_input.edge_attrs
                        [edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM];
                    let weights =
                        &conv_tp_weights[edge * tp_weight_dim..(edge + 1) * tp_weight_dim];
                    let local_edge = edge - edge_start;
                    let scatter_base = dst * tp_output_dim;
                    if can_direct_scatter {
                        let scatter_row =
                            &mut local_scatter_message[scatter_base..scatter_base + tp_output_dim];
                        match tp_weight_dim {
                            MACE_MH1_INTERACTION0_TP_WEIGHT_DIM => {
                                mace_mh1_conv_tp_forward_accumulate_interaction0_unmasked(
                                    plan,
                                    source_row,
                                    edge_attr,
                                    weights,
                                    scatter_row,
                                );
                            }
                            MACE_MH1_INTERACTION1_TP_WEIGHT_DIM => {
                                mace_mh1_conv_tp_forward_accumulate_interaction1_unmasked(
                                    plan,
                                    source_row,
                                    edge_attr,
                                    weights,
                                    scatter_row,
                                );
                            }
                            _ => {
                                mace_mh1_conv_tp_forward_accumulate_unmasked_fast(
                                    plan,
                                    &layouts,
                                    source_row,
                                    edge_attr,
                                    weights,
                                    scatter_row,
                                );
                            }
                        }
                        continue;
                    }
                    let message = if capture_edge_messages {
                        &mut local_edge_messages
                            [local_edge * tp_output_dim..(local_edge + 1) * tp_output_dim]
                    } else {
                        scratch_message.fill(0.0);
                        &mut scratch_message
                    };
                    plan.forward_accumulate_with_layouts_and_compensation(
                        &layouts,
                        source_row,
                        edge_attr,
                        Some(weights),
                        message,
                        &mut message_compensation,
                    )?;
                    for (value, &mask) in message.iter_mut().zip(output_mask) {
                        *value *= mask;
                    }
                    for (i, &value) in message.iter().enumerate() {
                        local_scatter_message[scatter_base + i] += value;
                    }
                }
                Ok(MaceMh1ConvTpForwardChunk {
                    edge_start,
                    edge_end,
                    edge_messages: local_edge_messages,
                    scatter_message: local_scatter_message,
                })
            },
        )
        .collect::<Result<Vec<_>, MaceMh1Error>>()?;

    let mut edge_messages = if capture_edge_messages {
        vec![0.0; edge_input.edge_count * tp_output_dim]
    } else {
        Vec::new()
    };
    let mut scatter_message = vec![0.0; node_count * tp_output_dim];
    let mut scatter_comp = vec![0.0; scatter_message.len()];
    for partial in partials {
        let edge_start = partial.edge_start * tp_output_dim;
        let edge_end = partial.edge_end * tp_output_dim;
        if capture_edge_messages {
            edge_messages[edge_start..edge_end].copy_from_slice(&partial.edge_messages);
        }
        for (i, src) in partial.scatter_message.into_iter().enumerate() {
            mace_mh1_kahan_add(&mut scatter_message[i], &mut scatter_comp[i], src);
        }
    }
    Ok((edge_messages, scatter_message))
}

#[allow(clippy::too_many_arguments)]
fn mace_mh1_conv_tp_vjp_from_scatter_bar_unmasked_fast(
    plan: &TensorProductPlan,
    layouts: &TensorProductLayouts,
    source_row: &[f64],
    edge_attr: &[f64],
    weights: &[f64],
    scatter_bar: &[f64],
    bar_source: &mut [f64],
    bar_edge_attr: &mut [f64],
    bar_weight_row: &mut [f64],
) {
    debug_assert_eq!(source_row.len(), plan.input1_dim());
    debug_assert_eq!(edge_attr.len(), plan.input2_dim());
    debug_assert_eq!(weights.len(), plan.weight_numel);
    debug_assert_eq!(scatter_bar.len(), plan.output_dim());
    debug_assert_eq!(bar_source.len(), plan.input1_dim());
    debug_assert_eq!(bar_edge_attr.len(), plan.input2_dim());
    debug_assert_eq!(bar_weight_row.len(), plan.weight_numel);

    for instruction in &plan.instructions {
        let in1 = layouts.in1[instruction.in1_segment];
        let in2 = layouts.in2[instruction.in2_segment];
        let out = layouts.out[instruction.out_segment];
        let weight = match instruction.weight_offset {
            Some(offset) => weights[offset],
            None => 1.0,
        };
        let cg_end = instruction.cg_offset + instruction.cg_len;

        for cg in &plan.cg_entries[instruction.cg_offset..cg_end] {
            let x_index = in1.start + cg.i_m;
            let y_index = in2.start + cg.j_m;
            let out_index = out.start + cg.k_m;
            let scale = instruction.path_weight * cg.value;
            let bar_out = scatter_bar[out_index];

            bar_source[x_index] += scale * weight * edge_attr[y_index] * bar_out;
            bar_edge_attr[y_index] += scale * weight * source_row[x_index] * bar_out;
            if let Some(weight_offset) = instruction.weight_offset {
                bar_weight_row[weight_offset] +=
                    scale * source_row[x_index] * edge_attr[y_index] * bar_out;
            }
        }
    }
}

