#[allow(dead_code, clippy::too_many_arguments)]
fn mace_mh1_conv_tp_vjp_from_scatter_bar_f32(
    prefix: &str,
    specialization: MaceMh1ConvTpSpecialization,
    plan: &TensorProductPlan,
    linear_up_dim: usize,
    tp_output_dim: usize,
    tp_weight_dim: usize,
    edge_src: &[usize],
    edge_dst: &[usize],
    edge_attrs: &[f32],
    linear_up: &[f32],
    conv_tp_weights: &[f32],
    bar_scatter_message: &[f32],
    output_mask: Option<&[f32]>,
    node_count: usize,
    bar_linear_up: &mut [f32],
    bar_edge_attrs: &mut [f32],
    bar_tp_weights: &mut [f32],
) -> Result<(), MaceMh1Error> {
    let edge_count = edge_src.len();
    if edge_dst.len() != edge_count {
        return Err(invalid(format!(
            "{prefix}.f32 edge_src length {edge_count} does not match edge_dst length {}",
            edge_dst.len()
        )));
    }
    if edge_attrs.len() != edge_count * MACE_MH1_SH_DIM {
        return Err(invalid(format!(
            "{prefix}.f32 edge_attrs length {} does not match edge_count {edge_count} * sh_dim {}",
            edge_attrs.len(),
            MACE_MH1_SH_DIM
        )));
    }
    if linear_up.len() != node_count * linear_up_dim {
        return Err(invalid(format!(
            "{prefix}.f32 linear_up length {} does not match node_count {node_count} * linear_up_dim {linear_up_dim}",
            linear_up.len()
        )));
    }
    if conv_tp_weights.len() != edge_count * tp_weight_dim {
        return Err(invalid(format!(
            "{prefix}.f32 conv_tp_weights length {} does not match edge_count {edge_count} * tp_weight_dim {tp_weight_dim}",
            conv_tp_weights.len()
        )));
    }
    if bar_scatter_message.len() != node_count * tp_output_dim {
        return Err(invalid(format!(
            "{prefix}.f32 bar_scatter_message length {} does not match node_count {node_count} * tp_output_dim {tp_output_dim}",
            bar_scatter_message.len()
        )));
    }
    if let Some(mask) = output_mask {
        if mask.len() != tp_output_dim {
            return Err(invalid(format!(
                "{prefix}.f32 output_mask length {} does not match tp_output_dim {tp_output_dim}",
                mask.len()
            )));
        }
    }
    if bar_linear_up.len() != node_count * linear_up_dim {
        return Err(invalid(format!(
            "{prefix}.f32 bar_linear_up length {} does not match node_count {node_count} * linear_up_dim {linear_up_dim}",
            bar_linear_up.len()
        )));
    }
    if bar_edge_attrs.len() != edge_count * MACE_MH1_SH_DIM {
        return Err(invalid(format!(
            "{prefix}.f32 bar_edge_attrs length {} does not match edge_count {edge_count} * sh_dim {}",
            bar_edge_attrs.len(),
            MACE_MH1_SH_DIM
        )));
    }
    if bar_tp_weights.len() != edge_count * tp_weight_dim {
        return Err(invalid(format!(
            "{prefix}.f32 bar_tp_weights length {} does not match edge_count {edge_count} * tp_weight_dim {tp_weight_dim}",
            bar_tp_weights.len()
        )));
    }

    let unmasked_kernel = if output_mask.is_none() {
        Some(mace_mh1_conv_tp_vjp_kernel_for(specialization)?)
    } else {
        None
    };
    let layouts = if output_mask.is_some()
        || matches!(unmasked_kernel, Some(MaceMh1ConvTpVjpKernel::Generic))
    {
        Some(plan.checked_layouts()?)
    } else {
        None
    };
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && edge_count >= MACE_MH1_CONV_TP_VJP_PARALLEL_MIN_EDGES {
        let target_chunks = rayon::current_num_threads().max(1);
        let chunk_len = edge_count.div_ceil(target_chunks).max(1);
        let edge_attr_chunk_len = chunk_len * MACE_MH1_SH_DIM;
        let weight_chunk_len = chunk_len * tp_weight_dim;
        let partials = bar_edge_attrs
            .par_chunks_mut(edge_attr_chunk_len)
            .zip(bar_tp_weights.par_chunks_mut(weight_chunk_len))
            .enumerate()
            .map(
                |(chunk_index, (bar_edge_attrs_chunk, bar_tp_weights_chunk))| -> Result<(usize, Vec<f32>), MaceMh1Error> {
                    let edge_start = chunk_index * chunk_len;
                    let edge_len = bar_edge_attrs_chunk.len() / MACE_MH1_SH_DIM;
                    let edge_end = edge_start + edge_len;
                    if bar_tp_weights_chunk.len() != edge_len * tp_weight_dim {
                        return Err(invalid(format!(
                            "{prefix}.f32 Conv-TP VJP chunk length mismatch"
                        )));
                    }
                    let mut src_start = node_count;
                    let mut src_end = 0usize;
                    for (offset, &src) in edge_src[edge_start..edge_end].iter().enumerate() {
                        let edge = edge_start + offset;
                        if src >= node_count {
                            return Err(invalid(format!(
                                "{prefix}.f32 edge {edge} source index {src} is out of range for {node_count} nodes"
                            )));
                        }
                        src_start = src_start.min(src);
                        src_end = src_end.max(src + 1);
                    }
                    let mut local_bar_linear_up =
                        vec![0.0_f32; (src_end - src_start) * linear_up_dim];

                    for (offset, (&src, &dst)) in edge_src[edge_start..edge_end]
                        .iter()
                        .zip(&edge_dst[edge_start..edge_end])
                        .enumerate()
                    {
                        let edge = edge_start + offset;
                        if src >= node_count || dst >= node_count {
                            return Err(invalid(format!(
                                "{prefix}.f32 edge {edge} index {src}->{dst} is out of range for {node_count} nodes"
                            )));
                        }
                        let source_row = &linear_up[src * linear_up_dim..(src + 1) * linear_up_dim];
                        let edge_attr =
                            &edge_attrs[edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM];
                        let weights =
                            &conv_tp_weights[edge * tp_weight_dim..(edge + 1) * tp_weight_dim];
                        let scatter_bar =
                            &bar_scatter_message[dst * tp_output_dim..(dst + 1) * tp_output_dim];
                        let local_src = src - src_start;
                        let bar_source = &mut local_bar_linear_up
                            [local_src * linear_up_dim..(local_src + 1) * linear_up_dim];
                        let local_edge = edge - edge_start;
                        let bar_edge_attr = &mut bar_edge_attrs_chunk
                            [local_edge * MACE_MH1_SH_DIM..(local_edge + 1) * MACE_MH1_SH_DIM];
                        let bar_weight_row = &mut bar_tp_weights_chunk
                            [local_edge * tp_weight_dim..(local_edge + 1) * tp_weight_dim];
                        if let Some(mask) = output_mask {
                            let Some(layouts) = layouts.as_ref() else {
                                return Err(invalid(format!(
                                    "{prefix}.f32 masked Conv-TP VJP layouts were not prepared"
                                )));
                            };
                            mace_mh1_conv_tp_vjp_from_scatter_bar_masked_f32(
                                plan,
                                layouts,
                                source_row,
                                edge_attr,
                                weights,
                                scatter_bar,
                                mask,
                                bar_source,
                                bar_edge_attr,
                                bar_weight_row,
                            );
                        } else {
                            let Some(unmasked_kernel) = unmasked_kernel else {
                                return Err(invalid(format!(
                                    "{prefix}.f32 unmasked Conv-TP VJP kernel was not prepared"
                                )));
                            };
                            match unmasked_kernel {
                                MaceMh1ConvTpVjpKernel::Interaction0Direct => {
                                    mace_mh1_conv_tp_vjp_from_scatter_bar_interaction0_unmasked_f32(
                                        plan,
                                        source_row,
                                        edge_attr,
                                        weights,
                                        scatter_bar,
                                        bar_source,
                                        bar_edge_attr,
                                        bar_weight_row,
                                    );
                                }
                                MaceMh1ConvTpVjpKernel::Prepared(prepared) => {
                                    mace_mh1_conv_tp_vjp_from_scatter_bar_prepared_f32(
                                        prepared,
                                        source_row,
                                        edge_attr,
                                        weights,
                                        scatter_bar,
                                        bar_source,
                                        bar_edge_attr,
                                        bar_weight_row,
                                    );
                                }
                                MaceMh1ConvTpVjpKernel::Generic => {
                                    let Some(layouts) = layouts.as_ref() else {
                                        return Err(invalid(format!(
                                            "{prefix}.f32 generic Conv-TP VJP layouts were not prepared"
                                        )));
                                    };
                                    mace_mh1_conv_tp_vjp_from_scatter_bar_unmasked_fast_f32(
                                        plan,
                                        layouts,
                                        source_row,
                                        edge_attr,
                                        weights,
                                        scatter_bar,
                                        bar_source,
                                        bar_edge_attr,
                                        bar_weight_row,
                                    );
                                }
                            }
                        }
                    }

                    Ok((src_start, local_bar_linear_up))
                },
            )
            .collect::<Result<Vec<_>, MaceMh1Error>>()?;

        for (src_start, partial) in partials {
            let offset = src_start * linear_up_dim;
            let end = offset + partial.len();
            for (dst, src) in bar_linear_up[offset..end].iter_mut().zip(partial) {
                *dst += src;
            }
        }
        return Ok(());
    }
    for edge in 0..edge_count {
        let src = edge_src[edge];
        let dst = edge_dst[edge];
        if src >= node_count || dst >= node_count {
            return Err(invalid(format!(
                "{prefix}.f32 edge {edge} index {src}->{dst} is out of range for {node_count} nodes"
            )));
        }
        let source_row = &linear_up[src * linear_up_dim..(src + 1) * linear_up_dim];
        let edge_attr = &edge_attrs[edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM];
        let weights = &conv_tp_weights[edge * tp_weight_dim..(edge + 1) * tp_weight_dim];
        let scatter_bar = &bar_scatter_message[dst * tp_output_dim..(dst + 1) * tp_output_dim];
        let bar_source = &mut bar_linear_up[src * linear_up_dim..(src + 1) * linear_up_dim];
        let bar_edge_attr =
            &mut bar_edge_attrs[edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM];
        let bar_weight_row = &mut bar_tp_weights[edge * tp_weight_dim..(edge + 1) * tp_weight_dim];
        if let Some(mask) = output_mask {
            let Some(layouts) = layouts.as_ref() else {
                return Err(invalid(format!(
                    "{prefix}.f32 masked Conv-TP VJP layouts were not prepared"
                )));
            };
            mace_mh1_conv_tp_vjp_from_scatter_bar_masked_f32(
                plan,
                layouts,
                source_row,
                edge_attr,
                weights,
                scatter_bar,
                mask,
                bar_source,
                bar_edge_attr,
                bar_weight_row,
            );
        } else {
            let Some(unmasked_kernel) = unmasked_kernel else {
                return Err(invalid(format!(
                    "{prefix}.f32 unmasked Conv-TP VJP kernel was not prepared"
                )));
            };
            match unmasked_kernel {
                MaceMh1ConvTpVjpKernel::Interaction0Direct => {
                    mace_mh1_conv_tp_vjp_from_scatter_bar_interaction0_unmasked_f32(
                        plan,
                        source_row,
                        edge_attr,
                        weights,
                        scatter_bar,
                        bar_source,
                        bar_edge_attr,
                        bar_weight_row,
                    );
                }
                MaceMh1ConvTpVjpKernel::Prepared(prepared) => {
                    mace_mh1_conv_tp_vjp_from_scatter_bar_prepared_f32(
                        prepared,
                        source_row,
                        edge_attr,
                        weights,
                        scatter_bar,
                        bar_source,
                        bar_edge_attr,
                        bar_weight_row,
                    );
                }
                MaceMh1ConvTpVjpKernel::Generic => {
                    let Some(layouts) = layouts.as_ref() else {
                        return Err(invalid(format!(
                            "{prefix}.f32 generic Conv-TP VJP layouts were not prepared"
                        )));
                    };
                    mace_mh1_conv_tp_vjp_from_scatter_bar_unmasked_fast_f32(
                        plan,
                        layouts,
                        source_row,
                        edge_attr,
                        weights,
                        scatter_bar,
                        bar_source,
                        bar_edge_attr,
                        bar_weight_row,
                    );
                }
            }
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn mace_mh1_conv_tp_vjp_from_scatter_bar_masked_f32(
    plan: &TensorProductPlan,
    layouts: &TensorProductLayouts,
    source_row: &[f32],
    edge_attr: &[f32],
    weights: &[f32],
    scatter_bar: &[f32],
    output_mask: &[f32],
    bar_source: &mut [f32],
    bar_edge_attr: &mut [f32],
    bar_weight_row: &mut [f32],
) {
    debug_assert_eq!(source_row.len(), plan.input1_dim());
    debug_assert_eq!(edge_attr.len(), plan.input2_dim());
    debug_assert_eq!(weights.len(), plan.weight_numel);
    debug_assert_eq!(scatter_bar.len(), plan.output_dim());
    debug_assert_eq!(output_mask.len(), plan.output_dim());
    debug_assert_eq!(bar_source.len(), plan.input1_dim());
    debug_assert_eq!(bar_edge_attr.len(), plan.input2_dim());
    debug_assert_eq!(bar_weight_row.len(), plan.weight_numel);

    for instruction in &plan.instructions {
        let in1 = layouts.in1[instruction.in1_segment];
        let in2 = layouts.in2[instruction.in2_segment];
        let out = layouts.out[instruction.out_segment];
        let weight = match instruction.weight_offset {
            Some(offset) => weights[offset],
            None => 1.0,
        };
        let scale = instruction.path_weight as f32 * weight;
        let cg_end = instruction.cg_offset + instruction.cg_len;

        for cg in &plan.cg_entries[instruction.cg_offset..cg_end] {
            let x_index = in1.start + cg.i_m;
            let y_index = in2.start + cg.j_m;
            let out_index = out.start + cg.k_m;
            let bar_out = scatter_bar[out_index] * output_mask[out_index];
            let scaled_bar = scale * cg.value as f32 * bar_out;

            bar_source[x_index] += scaled_bar * edge_attr[y_index];
            bar_edge_attr[y_index] += scaled_bar * source_row[x_index];
            if let Some(weight_offset) = instruction.weight_offset {
                bar_weight_row[weight_offset] += instruction.path_weight as f32
                    * cg.value as f32
                    * source_row[x_index]
                    * edge_attr[y_index]
                    * bar_out;
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn mace_mh1_conv_tp_vjp_from_scatter_bar_masked(
    plan: &TensorProductPlan,
    layouts: &TensorProductLayouts,
    source_row: &[f64],
    edge_attr: &[f64],
    weights: &[f64],
    scatter_bar: &[f64],
    output_mask: &[f64],
    bar_source: &mut [f64],
    bar_edge_attr: &mut [f64],
    bar_weight_row: &mut [f64],
    bar_source_comp: &mut [f64],
    bar_edge_attr_comp: &mut [f64],
) {
    debug_assert_eq!(source_row.len(), plan.input1_dim());
    debug_assert_eq!(edge_attr.len(), plan.input2_dim());
    debug_assert_eq!(weights.len(), plan.weight_numel);
    debug_assert_eq!(scatter_bar.len(), plan.output_dim());
    debug_assert_eq!(output_mask.len(), plan.output_dim());
    debug_assert_eq!(bar_source.len(), plan.input1_dim());
    debug_assert_eq!(bar_edge_attr.len(), plan.input2_dim());
    debug_assert_eq!(bar_weight_row.len(), plan.weight_numel);
    debug_assert_eq!(bar_source_comp.len(), plan.input1_dim());
    debug_assert_eq!(bar_edge_attr_comp.len(), plan.input2_dim());

    bar_source_comp.fill(0.0);
    bar_edge_attr_comp.fill(0.0);

    for instruction in &plan.instructions {
        let in1 = layouts.in1[instruction.in1_segment];
        let in2 = layouts.in2[instruction.in2_segment];
        let out = layouts.out[instruction.out_segment];
        let weight = match instruction.weight_offset {
            Some(offset) => weights[offset],
            None => 1.0,
        };
        let cg_end = instruction.cg_offset + instruction.cg_len;

        for cg in &plan.cg_entries[instruction.cg_offset..cg_end] {
            let x_index = in1.start + cg.i_m;
            let y_index = in2.start + cg.j_m;
            let out_index = out.start + cg.k_m;
            let scale = instruction.path_weight * cg.value;
            let bar_out = scatter_bar[out_index] * output_mask[out_index];

            mace_mh1_kahan_add(
                &mut bar_source[x_index],
                &mut bar_source_comp[x_index],
                scale * weight * edge_attr[y_index] * bar_out,
            );
            mace_mh1_kahan_add(
                &mut bar_edge_attr[y_index],
                &mut bar_edge_attr_comp[y_index],
                scale * weight * source_row[x_index] * bar_out,
            );
            if let Some(weight_offset) = instruction.weight_offset {
                bar_weight_row[weight_offset] +=
                    scale * source_row[x_index] * edge_attr[y_index] * bar_out;
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn mace_mh1_equivariant_linear(
    input: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    instructions: &[MaceMh1EquivariantLinearInstruction],
    input_dim: usize,
    output_dim: usize,
    name: &str,
    out: &mut [f64],
) -> Result<(), MaceMh1Error> {
    let rows = checked_row_count(name, input.len(), input_dim)?;
    if output_mask.len() != output_dim {
        return Err(invalid(format!(
            "{name} output mask length {} does not match output_dim {output_dim}",
            output_mask.len()
        )));
    }
    if out.len() != rows * output_dim {
        return Err(invalid(format!(
            "{name} output length {} does not match rows {rows} * output_dim {output_dim}",
            out.len()
        )));
    }
    let weight_len = mace_mh1_equivariant_linear_weight_len(instructions);
    if weight.len() != weight_len {
        return Err(invalid(format!(
            "{name} weight length {} does not match expected {weight_len}",
            weight.len()
        )));
    }
    out.fill(0.0);
    let path_weights = mace_mh1_equivariant_linear_path_weights(instructions);
    for instruction in instructions {
        let input_end = instruction.input_offset + instruction.input_features * instruction.dim;
        let output_end = instruction.output_offset + instruction.output_features * instruction.dim;
        if input_end > input_dim || output_end > output_dim {
            return Err(invalid(format!(
                "{name} equivariant linear instruction exceeds row bounds"
            )));
        }
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64"),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    ))]
    if rows >= mace_mh1_blas_dispatch_threshold() {
        mace_mh1_equivariant_linear_blas(
            input,
            weight,
            output_mask,
            instructions,
            &path_weights,
            rows,
            input_dim,
            output_dim,
            out,
        );
        return Ok(());
    }
    for (instruction, &path_weight) in instructions.iter().zip(&path_weights) {
        let input_end = instruction.input_offset + instruction.input_features * instruction.dim;
        let output_end = instruction.output_offset + instruction.output_features * instruction.dim;
        if input_end > input_dim || output_end > output_dim {
            return Err(invalid(format!(
                "{name} equivariant linear instruction exceeds row bounds"
            )));
        }
        for row in 0..rows {
            let input_row = &input[row * input_dim..(row + 1) * input_dim];
            let output_row = &mut out[row * output_dim..(row + 1) * output_dim];
            for out_feature in 0..instruction.output_features {
                for component in 0..instruction.dim {
                    let mut value = 0.0;
                    for in_feature in 0..instruction.input_features {
                        let input_index =
                            instruction.input_offset + in_feature * instruction.dim + component;
                        let weight_index = instruction.weight_offset
                            + in_feature * instruction.output_features
                            + out_feature;
                        value += input_row[input_index] * weight[weight_index];
                    }
                    let output_index =
                        instruction.output_offset + out_feature * instruction.dim + component;
                    output_row[output_index] += value * path_weight * output_mask[output_index];
                }
            }
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn mace_mh1_equivariant_linear_f32(
    input: &[f32],
    weight: &[f32],
    output_mask: &[f32],
    instructions: &[MaceMh1EquivariantLinearInstruction],
    input_dim: usize,
    output_dim: usize,
    name: &str,
    out: &mut [f32],
) -> Result<(), MaceMh1Error> {
    let rows = checked_row_count(name, input.len(), input_dim)?;
    if output_mask.len() != output_dim {
        return Err(invalid(format!(
            "{name} f32 output mask length {} does not match output_dim {output_dim}",
            output_mask.len()
        )));
    }
    if out.len() != rows * output_dim {
        return Err(invalid(format!(
            "{name} f32 output length {} does not match rows {rows} * output_dim {output_dim}",
            out.len()
        )));
    }
    let weight_len = mace_mh1_equivariant_linear_weight_len(instructions);
    if weight.len() != weight_len {
        return Err(invalid(format!(
            "{name} f32 weight length {} does not match expected {weight_len}",
            weight.len()
        )));
    }
    out.fill(0.0);
    let path_weights = mace_mh1_equivariant_linear_path_weights(instructions)
        .into_iter()
        .map(|weight| weight as f32)
        .collect::<Vec<_>>();
    for instruction in instructions {
        let input_end = instruction.input_offset + instruction.input_features * instruction.dim;
        let output_end = instruction.output_offset + instruction.output_features * instruction.dim;
        if input_end > input_dim || output_end > output_dim {
            return Err(invalid(format!(
                "{name} f32 equivariant linear instruction exceeds row bounds"
            )));
        }
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if rows >= mace_mh1_blas_dispatch_threshold() {
        mace_mh1_equivariant_linear_blas_f32(
            input,
            weight,
            output_mask,
            instructions,
            &path_weights,
            rows,
            input_dim,
            output_dim,
            out,
        );
        return Ok(());
    }
    for (instruction, &path_weight) in instructions.iter().zip(&path_weights) {
        for row in 0..rows {
            let input_row = &input[row * input_dim..(row + 1) * input_dim];
            let output_row = &mut out[row * output_dim..(row + 1) * output_dim];
            for out_feature in 0..instruction.output_features {
                for component in 0..instruction.dim {
                    let mut value = 0.0_f32;
                    for in_feature in 0..instruction.input_features {
                        let input_index =
                            instruction.input_offset + in_feature * instruction.dim + component;
                        let weight_index = instruction.weight_offset
                            + in_feature * instruction.output_features
                            + out_feature;
                        value += input_row[input_index] * weight[weight_index];
                    }
                    let output_index =
                        instruction.output_offset + out_feature * instruction.dim + component;
                    output_row[output_index] += value * path_weight * output_mask[output_index];
                }
            }
        }
    }
    Ok(())
}

fn mace_mh1_masked_linear_vjp_input(
    weights: &[f64],
    output_mask: &[f64],
    input_dim: usize,
    output_dim: usize,
    name: &str,
    bar_out: &[f64],
    bar_input: &mut [f64],
) -> Result<(), MaceMh1Error> {
    let rows = checked_row_count(name, bar_input.len(), input_dim)?;
    if weights.len() != input_dim * output_dim {
        return Err(invalid(format!(
            "{name} weight length {} does not match input_dim {input_dim} * output_dim {output_dim}",
            weights.len()
        )));
    }
    if output_mask.len() != output_dim {
        return Err(invalid(format!(
            "{name} output mask length {} does not match output_dim {output_dim}",
            output_mask.len()
        )));
    }
    if bar_out.len() != rows * output_dim {
        return Err(invalid(format!(
            "{name} bar_out length {} does not match rows {rows} * output_dim {output_dim}",
            bar_out.len()
        )));
    }
    let path_weight = 1.0 / (input_dim as f64).sqrt();

    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    {
        #[cfg(feature = "parallel")]
        let use_blas_vjp = rayon::current_num_threads() > 1;
        #[cfg(not(feature = "parallel"))]
        let use_blas_vjp = false;

        if use_blas_vjp {
            if output_mask.iter().all(|&mask| mask == 1.0) {
                blas_backend::dense_vjp_input(
                    rows,
                    input_dim,
                    weights,
                    bar_out,
                    bar_input,
                    path_weight,
                );
            } else {
                let mut masked_bar_out = bar_out.to_vec();
                for row in masked_bar_out.chunks_exact_mut(output_dim) {
                    for (bar, &mask) in row.iter_mut().zip(output_mask) {
                        *bar *= mask;
                    }
                }
                blas_backend::dense_vjp_input(
                    rows,
                    input_dim,
                    weights,
                    &masked_bar_out,
                    bar_input,
                    path_weight,
                );
            }
        } else {
            for row in 0..rows {
                let input_offset = row * input_dim;
                let output_offset = row * output_dim;
                for out_feature in 0..output_dim {
                    let bar = bar_out[output_offset + out_feature]
                        * path_weight
                        * output_mask[out_feature];
                    for in_feature in 0..input_dim {
                        bar_input[input_offset + in_feature] +=
                            bar * weights[in_feature * output_dim + out_feature];
                    }
                }
            }
        }
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    )))]
    {
        for row in 0..rows {
            let input_offset = row * input_dim;
            let output_offset = row * output_dim;
            for out_feature in 0..output_dim {
                let bar =
                    bar_out[output_offset + out_feature] * path_weight * output_mask[out_feature];
                for in_feature in 0..input_dim {
                    bar_input[input_offset + in_feature] +=
                        bar * weights[in_feature * output_dim + out_feature];
                }
            }
        }
    }
    Ok(())
}

