#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        target_arch = "x86_64"
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64"),
    all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
))]
#[allow(clippy::too_many_arguments)]
fn mace_mh1_equivariant_linear_blas(
    input: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    instructions: &[MaceMh1EquivariantLinearInstruction],
    path_weights: &[f64],
    rows: usize,
    input_dim: usize,
    output_dim: usize,
    out: &mut [f64],
) {
    let max_in_features = instructions
        .iter()
        .map(|instruction| instruction.input_features)
        .max()
        .unwrap_or(0);
    let max_out_features = instructions
        .iter()
        .map(|instruction| instruction.output_features)
        .max()
        .unwrap_or(0);
    let max_dim = instructions
        .iter()
        .map(|instruction| instruction.dim)
        .max()
        .unwrap_or(0);
    let mut packed_input = vec![0.0; rows * max_in_features];
    let mut packed_out = vec![0.0; rows * max_out_features];
    let mut packed_input_wide = vec![0.0; rows * max_dim * max_in_features];
    let mut packed_out_wide = vec![0.0; rows * max_dim * max_out_features];
    for (instruction, &path_weight) in instructions.iter().zip(path_weights) {
        let weight_slice = &weight[instruction.weight_offset
            ..instruction.weight_offset + instruction.input_features * instruction.output_features];
        let instruction_mask_all_one = output_mask[instruction.output_offset
            ..instruction.output_offset + instruction.output_features * instruction.dim]
            .iter()
            .all(|&mask| mask == 1.0);
        if instruction.dim == 1 && instruction_mask_all_one {
            blas_backend::dense_forward_strided(
                &input[instruction.input_offset..],
                rows,
                instruction.input_features,
                input_dim,
                weight_slice,
                &mut out[instruction.output_offset..],
                instruction.output_features,
                output_dim,
                path_weight,
                1.0,
            );
            continue;
        }
        if instruction.dim > 1 && instruction_mask_all_one {
            let packed_rows = rows * instruction.dim;
            for row in 0..rows {
                let input_row = &input[row * input_dim..(row + 1) * input_dim];
                for component in 0..instruction.dim {
                    let packed_row = &mut packed_input_wide[(row * instruction.dim + component)
                        * max_in_features
                        ..(row * instruction.dim + component) * max_in_features
                            + instruction.input_features];
                    for (feature, packed_value) in packed_row.iter_mut().enumerate() {
                        *packed_value = input_row
                            [instruction.input_offset + feature * instruction.dim + component];
                    }
                }
            }
            blas_backend::dense_forward_strided(
                &packed_input_wide[..packed_rows * max_in_features],
                packed_rows,
                instruction.input_features,
                max_in_features,
                weight_slice,
                &mut packed_out_wide[..packed_rows * max_out_features],
                instruction.output_features,
                max_out_features,
                path_weight,
                0.0,
            );
            for row in 0..rows {
                let output_row = &mut out[row * output_dim..(row + 1) * output_dim];
                for component in 0..instruction.dim {
                    let packed_row = &packed_out_wide[(row * instruction.dim + component)
                        * max_out_features
                        ..(row * instruction.dim + component) * max_out_features
                            + instruction.output_features];
                    for (feature, &value) in packed_row.iter().enumerate() {
                        let output_index =
                            instruction.output_offset + feature * instruction.dim + component;
                        output_row[output_index] += value;
                    }
                }
            }
            continue;
        }
        for component in 0..instruction.dim {
            for row in 0..rows {
                let input_row = &input[row * input_dim..(row + 1) * input_dim];
                let packed_row = &mut packed_input
                    [row * max_in_features..row * max_in_features + instruction.input_features];
                for (feature, packed_value) in packed_row.iter_mut().enumerate() {
                    *packed_value =
                        input_row[instruction.input_offset + feature * instruction.dim + component];
                }
            }
            let packed_input_view = &packed_input[..rows * max_in_features];
            let packed_out_view = &mut packed_out[..rows * max_out_features];
            blas_backend::dense_forward_strided(
                packed_input_view,
                rows,
                instruction.input_features,
                max_in_features,
                weight_slice,
                packed_out_view,
                instruction.output_features,
                max_out_features,
                path_weight,
                0.0,
            );
            for row in 0..rows {
                let output_row = &mut out[row * output_dim..(row + 1) * output_dim];
                let packed_row = &packed_out
                    [row * max_out_features..row * max_out_features + instruction.output_features];
                for (feature, &value) in packed_row.iter().enumerate() {
                    let output_index =
                        instruction.output_offset + feature * instruction.dim + component;
                    output_row[output_index] += value * output_mask[output_index];
                }
            }
        }
    }
}

