#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
#[allow(clippy::too_many_arguments)]
fn mace_mh1_equivariant_linear_vjp_input_blas_f32(
    weight: &[f32],
    output_mask: &[f32],
    instructions: &[MaceMh1EquivariantLinearInstruction],
    path_weights: &[f32],
    rows: usize,
    input_dim: usize,
    output_dim: usize,
    bar_out: &[f32],
    bar_input: &mut [f32],
) {
    let max_in_features = instructions
        .iter()
        .map(|instruction| instruction.input_features)
        .max()
        .unwrap_or(0);
    let max_out_features = instructions
        .iter()
        .map(|instruction| instruction.output_features)
        .max()
        .unwrap_or(0);
    let max_dim = instructions
        .iter()
        .map(|instruction| instruction.dim)
        .max()
        .unwrap_or(0);
    let max_group_in_features = mace_mh1_equivariant_linear_max_contiguous_vjp_group_features_f32(
        instructions,
        path_weights,
    )
    .max(max_in_features);
    let mut packed_bar_out = vec![0.0_f32; rows * max_out_features];
    let mut packed_bar_input = vec![0.0_f32; rows * max_in_features];
    let mut packed_bar_out_wide = vec![0.0_f32; rows * max_dim * max_out_features];
    let mut packed_bar_input_wide = vec![0.0_f32; rows * max_dim * max_group_in_features];
    let mut instruction_index = 0;
    while instruction_index < instructions.len() {
        let instruction = &instructions[instruction_index];
        let path_weight = path_weights[instruction_index];
        let weight_slice = &weight[instruction.weight_offset
            ..instruction.weight_offset + instruction.input_features * instruction.output_features];
        let instruction_mask_all_one = output_mask[instruction.output_offset
            ..instruction.output_offset + instruction.output_features * instruction.dim]
            .iter()
            .all(|&mask| mask == 1.0);
        if instruction.dim == 1 && instruction_mask_all_one {
            let group = mace_mh1_equivariant_linear_contiguous_vjp_group_f32(
                instructions,
                path_weights,
                instruction_index,
            );
            let group_weight_slice = &weight[instruction.weight_offset
                ..instruction.weight_offset + group.input_features * instruction.output_features];
            blas_backend::dense_vjp_input_strided_f32(
                rows,
                group.input_features,
                group_weight_slice,
                instruction.output_features,
                &bar_out[instruction.output_offset..],
                output_dim,
                &mut bar_input[instruction.input_offset..],
                input_dim,
                path_weight,
                1.0,
            );
            instruction_index = group.end;
            continue;
        }
        if instruction.dim > 1 && instruction_mask_all_one {
            let group = mace_mh1_equivariant_linear_contiguous_vjp_group_f32(
                instructions,
                path_weights,
                instruction_index,
            );
            let packed_rows = rows * instruction.dim;
            for row in 0..rows {
                let bar_out_row = &bar_out[row * output_dim..(row + 1) * output_dim];
                for component in 0..instruction.dim {
                    let packed_row = &mut packed_bar_out_wide[(row * instruction.dim + component)
                        * max_out_features
                        ..(row * instruction.dim + component) * max_out_features
                            + instruction.output_features];
                    for (feature, packed_value) in packed_row.iter_mut().enumerate() {
                        *packed_value = bar_out_row
                            [instruction.output_offset + feature * instruction.dim + component];
                    }
                }
            }
            let group_weight_slice = &weight[instruction.weight_offset
                ..instruction.weight_offset + group.input_features * instruction.output_features];
            blas_backend::dense_vjp_input_strided_f32(
                packed_rows,
                group.input_features,
                group_weight_slice,
                instruction.output_features,
                &packed_bar_out_wide[..packed_rows * max_out_features],
                max_out_features,
                &mut packed_bar_input_wide[..packed_rows * max_group_in_features],
                max_group_in_features,
                path_weight,
                0.0,
            );
            for row in 0..rows {
                let bar_input_row = &mut bar_input[row * input_dim..(row + 1) * input_dim];
                for component in 0..instruction.dim {
                    let packed_offset = (row * instruction.dim + component) * max_group_in_features;
                    let packed_row =
                        &packed_bar_input_wide[packed_offset..packed_offset + group.input_features];
                    for (feature, &value) in packed_row.iter().enumerate() {
                        let input_index =
                            instruction.input_offset + feature * instruction.dim + component;
                        bar_input_row[input_index] += value;
                    }
                }
            }
            instruction_index = group.end;
            continue;
        }
        for component in 0..instruction.dim {
            for row in 0..rows {
                let bar_out_row = &bar_out[row * output_dim..(row + 1) * output_dim];
                let packed_row = &mut packed_bar_out
                    [row * max_out_features..row * max_out_features + instruction.output_features];
                for (feature, packed_value) in packed_row.iter_mut().enumerate() {
                    let output_index =
                        instruction.output_offset + feature * instruction.dim + component;
                    *packed_value = bar_out_row[output_index] * output_mask[output_index];
                }
            }
            blas_backend::dense_vjp_input_strided_f32(
                rows,
                instruction.input_features,
                weight_slice,
                instruction.output_features,
                &packed_bar_out[..rows * max_out_features],
                max_out_features,
                &mut packed_bar_input[..rows * max_in_features],
                max_in_features,
                path_weight,
                0.0,
            );
            for row in 0..rows {
                let bar_input_row = &mut bar_input[row * input_dim..(row + 1) * input_dim];
                let packed_row = &packed_bar_input
                    [row * max_in_features..row * max_in_features + instruction.input_features];
                for (feature, &value) in packed_row.iter().enumerate() {
                    let input_index =
                        instruction.input_offset + feature * instruction.dim + component;
                    bar_input_row[input_index] += value;
                }
            }
        }
        instruction_index += 1;
    }
}

