#[allow(dead_code)]
fn mace_mh1_interaction_equivariant_nonlin(
    input: &[f64],
    output_mask: &[f64],
    name: &str,
) -> Result<Vec<f64>, MaceMh1Error> {
    let rows = checked_row_count(name, input.len(), MACE_MH1_INTERACTION0_NONLIN_DIM)?;
    if output_mask.len() != MACE_MH1_INTERACTION0_OUT_DIM - MACE_MH1_INTERACTION0_RESHAPED_CHANNELS
    {
        return Err(invalid(
            "MACE-MH-1 interaction-0 equivariant nonlinearity mask length mismatch",
        ));
    }
    let mut output = vec![0.0; rows * MACE_MH1_INTERACTION0_OUT_DIM];
    for row in 0..rows {
        let input_row = &input
            [row * MACE_MH1_INTERACTION0_NONLIN_DIM..(row + 1) * MACE_MH1_INTERACTION0_NONLIN_DIM];
        let output_row = &mut output
            [row * MACE_MH1_INTERACTION0_OUT_DIM..(row + 1) * MACE_MH1_INTERACTION0_OUT_DIM];

        for feature in 0..MACE_MH1_INTERACTION0_RESHAPED_CHANNELS {
            output_row[feature] = silu(input_row[feature]) * MACE_MH1_SILU_SCALE;
        }
        mace_mh1_apply_gate_group(
            input_row,
            output_mask,
            output_row,
            MaceMh1GateGroup {
                gate_offset: 512,
                input_offset: 2048,
                output_offset: 512,
                mask_offset: 0,
                dim: 3,
            },
        );
        mace_mh1_apply_gate_group(
            input_row,
            output_mask,
            output_row,
            MaceMh1GateGroup {
                gate_offset: 1024,
                input_offset: 3584,
                output_offset: 2048,
                mask_offset: 1536,
                dim: 5,
            },
        );
        mace_mh1_apply_gate_group(
            input_row,
            output_mask,
            output_row,
            MaceMh1GateGroup {
                gate_offset: 1536,
                input_offset: 6144,
                output_offset: 4608,
                mask_offset: 4096,
                dim: 7,
            },
        );
    }
    Ok(output)
}

fn mace_mh1_interaction_equivariant_nonlin_with_sigmoid_cache(
    input: &[f64],
    output_mask: &[f64],
    name: &str,
) -> Result<(Vec<f64>, Vec<f64>), MaceMh1Error> {
    let rows = checked_row_count(name, input.len(), MACE_MH1_INTERACTION0_NONLIN_DIM)?;
    if output_mask.len() != MACE_MH1_INTERACTION0_OUT_DIM - MACE_MH1_INTERACTION0_RESHAPED_CHANNELS
    {
        return Err(invalid(
            "MACE-MH-1 equivariant nonlinearity mask length mismatch",
        ));
    }
    let mut output = vec![0.0; rows * MACE_MH1_INTERACTION0_OUT_DIM];
    let mut sigmoid_cache = vec![0.0; rows * MACE_MH1_INTERACTION0_RESHAPED_CHANNELS * 4];
    let trace_timings = mace_mh1_trace_timings_enabled();
    let sigmoid_start = trace_timings.then(Instant::now);
    fill_strided_sigmoid_cache_f64(
        input,
        rows,
        MACE_MH1_INTERACTION0_NONLIN_DIM,
        MACE_MH1_INTERACTION0_RESHAPED_CHANNELS * 4,
        &mut sigmoid_cache,
    );
    mace_mh1_trace_stage(&format!("{name}.sigmoid_cache"), sigmoid_start);

    #[cfg(feature = "parallel")]
    let used_parallel_rows = if rayon::current_num_threads() > 2 && rows >= 16 {
        input
            .par_chunks_exact(MACE_MH1_INTERACTION0_NONLIN_DIM)
            .zip(output.par_chunks_exact_mut(MACE_MH1_INTERACTION0_OUT_DIM))
            .zip(sigmoid_cache.par_chunks_exact(MACE_MH1_INTERACTION0_RESHAPED_CHANNELS * 4))
            .for_each(|((input_row, output_row), sigmoid_row)| {
                mace_mh1_interaction_equivariant_nonlin_row_from_sigmoid_cache(
                    input_row,
                    output_mask,
                    output_row,
                    sigmoid_row,
                );
            });
        true
    } else {
        false
    };
    #[cfg(not(feature = "parallel"))]
    let used_parallel_rows = false;
    if !used_parallel_rows {
        for row in 0..rows {
            let input_row = &input[row * MACE_MH1_INTERACTION0_NONLIN_DIM
                ..(row + 1) * MACE_MH1_INTERACTION0_NONLIN_DIM];
            let output_row = &mut output
                [row * MACE_MH1_INTERACTION0_OUT_DIM..(row + 1) * MACE_MH1_INTERACTION0_OUT_DIM];
            let sigmoid_row = &sigmoid_cache[row * MACE_MH1_INTERACTION0_RESHAPED_CHANNELS * 4
                ..(row + 1) * MACE_MH1_INTERACTION0_RESHAPED_CHANNELS * 4];
            mace_mh1_interaction_equivariant_nonlin_row_from_sigmoid_cache(
                input_row,
                output_mask,
                output_row,
                sigmoid_row,
            );
        }
    }
    Ok((output, sigmoid_cache))
}

fn mace_mh1_interaction_equivariant_nonlin_row_from_sigmoid_cache(
    input_row: &[f64],
    output_mask: &[f64],
    output_row: &mut [f64],
    sigmoid_row: &[f64],
) {
    for feature in 0..MACE_MH1_INTERACTION0_RESHAPED_CHANNELS {
        let sigmoid_value = sigmoid_row[feature];
        output_row[feature] = input_row[feature] * sigmoid_value * MACE_MH1_SILU_SCALE;
    }
    mace_mh1_apply_gate_group_from_sigmoid_cache(
        input_row,
        output_mask,
        output_row,
        sigmoid_row,
        MaceMh1GateGroup {
            gate_offset: 512,
            input_offset: 2048,
            output_offset: 512,
            mask_offset: 0,
            dim: 3,
        },
    );
    mace_mh1_apply_gate_group_from_sigmoid_cache(
        input_row,
        output_mask,
        output_row,
        sigmoid_row,
        MaceMh1GateGroup {
            gate_offset: 1024,
            input_offset: 3584,
            output_offset: 2048,
            mask_offset: 1536,
            dim: 5,
        },
    );
    mace_mh1_apply_gate_group_from_sigmoid_cache(
        input_row,
        output_mask,
        output_row,
        sigmoid_row,
        MaceMh1GateGroup {
            gate_offset: 1536,
            input_offset: 6144,
            output_offset: 4608,
            mask_offset: 4096,
            dim: 7,
        },
    );
}

