static MACE_MH1_INTERACTION0_CONV_TP_PLAN: OnceLock<Result<TensorProductPlan, String>> =
    OnceLock::new();
static MACE_MH1_INTERACTION1_CONV_TP_PLAN_TRUE_F64: OnceLock<Result<TensorProductPlan, String>> =
    OnceLock::new();
static MACE_MH1_INTERACTION1_CONV_TP_PLAN_UPSTREAM: OnceLock<Result<TensorProductPlan, String>> =
    OnceLock::new();
static MACE_MH1_INTERACTION1_PREPARED_CONV_TP_PLAN_TRUE_F64: OnceLock<
    Result<MaceMh1PreparedConvTpPlan, String>,
> = OnceLock::new();
static MACE_MH1_INTERACTION1_PREPARED_CONV_TP_PLAN_UPSTREAM: OnceLock<
    Result<MaceMh1PreparedConvTpPlan, String>,
> = OnceLock::new();

fn mace_mh1_interaction0_conv_tp_plan() -> Result<&'static TensorProductPlan, MaceMh1Error> {
    cached_mace_mh1_conv_tp_plan(
        MACE_MH1_INTERACTION0_CONV_TP_PLAN.get_or_init(|| {
            build_mace_mh1_interaction0_conv_tp_plan().map_err(|err| err.to_string())
        }),
        "interaction-0",
    )
}

fn cached_mace_mh1_conv_tp_plan<'a>(
    cached: &'a Result<TensorProductPlan, String>,
    label: &str,
) -> Result<&'a TensorProductPlan, MaceMh1Error> {
    match cached {
        Ok(plan) => Ok(plan),
        Err(message) => Err(invalid(format!(
            "static MACE-MH-1 {label} conv TP plan is invalid: {message}"
        ))),
    }
}

fn mace_mh1_conv_tp_vjp_kernel_for(
    specialization: MaceMh1ConvTpSpecialization,
) -> Result<MaceMh1ConvTpVjpKernel<'static>, MaceMh1Error> {
    match specialization {
        MaceMh1ConvTpSpecialization::Interaction0 => Ok(MaceMh1ConvTpVjpKernel::Interaction0Direct),
        MaceMh1ConvTpSpecialization::Interaction1(wigner_mode) => {
            Ok(MaceMh1ConvTpVjpKernel::Prepared(
                mace_mh1_interaction1_prepared_conv_tp_plan_for(wigner_mode)?,
            ))
        }
        MaceMh1ConvTpSpecialization::Generic => Ok(MaceMh1ConvTpVjpKernel::Generic),
    }
}

fn mace_mh1_interaction1_prepared_conv_tp_plan_for(
    wigner_mode: MaceMh1WignerMode,
) -> Result<&'static MaceMh1PreparedConvTpPlan, MaceMh1Error> {
    let plan = mace_mh1_interaction1_conv_tp_plan_for(wigner_mode)?;
    let cached = match wigner_mode {
        MaceMh1WignerMode::TrueFloat64 => MACE_MH1_INTERACTION1_PREPARED_CONV_TP_PLAN_TRUE_F64
            .get_or_init(|| {
                mace_mh1_prepare_conv_tp_plan(
                    plan,
                    &MACE_MH1_INTERACTION1_CONV_TP_CHUNKS,
                    MACE_MH1_INTERACTION1_SCALAR_CHANNELS,
                )
                .map_err(|err| err.to_string())
            }),
        MaceMh1WignerMode::UpstreamArtifact => MACE_MH1_INTERACTION1_PREPARED_CONV_TP_PLAN_UPSTREAM
            .get_or_init(|| {
                mace_mh1_prepare_conv_tp_plan(
                    plan,
                    &MACE_MH1_INTERACTION1_CONV_TP_CHUNKS,
                    MACE_MH1_INTERACTION1_SCALAR_CHANNELS,
                )
                .map_err(|err| err.to_string())
            }),
    };
    cached_mace_mh1_prepared_conv_tp_plan(cached, "interaction-1")
}

fn cached_mace_mh1_prepared_conv_tp_plan<'a>(
    cached: &'a Result<MaceMh1PreparedConvTpPlan, String>,
    label: &str,
) -> Result<&'a MaceMh1PreparedConvTpPlan, MaceMh1Error> {
    match cached {
        Ok(plan) => Ok(plan),
        Err(message) => Err(invalid(format!(
            "static MACE-MH-1 {label} prepared conv TP plan is invalid: {message}"
        ))),
    }
}

fn mace_mh1_prepare_conv_tp_plan(
    plan: &TensorProductPlan,
    chunks: &[MaceMh1ConvTpChunk],
    channels: usize,
) -> Result<MaceMh1PreparedConvTpPlan, MaceMh1Error> {
    let mut prepared_chunks = Vec::with_capacity(chunks.len());
    let mut entries = Vec::new();
    for chunk in chunks {
        let cg_end = chunk.cg_offset + chunk.cg_len;
        if cg_end > plan.cg_entries.len() {
            return Err(invalid(format!(
                "MACE-MH-1 prepared conv TP chunk cg range {}..{} exceeds {} entries",
                chunk.cg_offset,
                cg_end,
                plan.cg_entries.len()
            )));
        }
        let entry_offset = entries.len();
        for cg in &plan.cg_entries[chunk.cg_offset..cg_end] {
            entries.push(MaceMh1PreparedConvTpEntry {
                i_m: cg.i_m,
                y_index: chunk.in2_base + cg.j_m,
                k_m: cg.k_m,
                scale: chunk.path_weight * cg.value,
            });
        }
        prepared_chunks.push(MaceMh1PreparedConvTpChunk {
            in1_base: chunk.in1_base,
            in1_stride: chunk.in1_stride,
            out_base: chunk.out_base,
            out_stride: chunk.out_stride,
            weight_base: chunk.weight_base,
            entry_offset,
            entry_len: chunk.cg_len,
        });
    }
    Ok(MaceMh1PreparedConvTpPlan {
        channels,
        chunks: prepared_chunks,
        entries,
    })
}

fn build_mace_mh1_interaction0_conv_tp_plan() -> Result<TensorProductPlan, MaceMh1Error> {
    const CG_OFFSETS: [usize; 4] = [0, 1, 4, 9];
    const CG_LENS: [usize; 4] = [1, 3, 5, 7];
    const PATH_WEIGHTS: [f64; 4] = [
        1.0,
        1.732_050_807_568_877_2,
        2.236_067_977_499_79,
        2.645_751_311_064_590_7,
    ];
    const CG_VALUES: [f64; 16] = [
        1.0,
        0.577_350_269_189_625_8,
        0.577_350_269_189_625_6,
        0.577_350_269_189_625_8,
        0.447_213_595_499_957_7,
        0.447_213_595_499_958_15,
        0.447_213_595_499_957_8,
        0.447_213_595_499_958,
        0.447_213_595_499_958_2,
        0.377_964_473_009_227_6,
        0.377_964_473_009_227_5,
        0.377_964_473_009_227,
        0.377_964_473_009_227_14,
        0.377_964_473_009_227_14,
        0.377_964_473_009_227_2,
        0.377_964_473_009_227_5,
    ];
    let mut instructions = Vec::with_capacity(MACE_MH1_INTERACTION0_TP_WEIGHT_DIM);
    for l in 0..=L_MAX {
        for channel in 0..MACE_MH1_INTERACTION0_CHANNELS {
            let offset = l * MACE_MH1_INTERACTION0_CHANNELS + channel;
            instructions.push(TensorProductInstruction {
                in1_segment: channel,
                in2_segment: l,
                out_segment: offset,
                cg_offset: CG_OFFSETS[l],
                cg_len: CG_LENS[l],
                weight_offset: Some(offset),
                path_weight: PATH_WEIGHTS[l],
            });
        }
    }
    let mut cg_entries = Vec::with_capacity(MACE_MH1_SH_DIM);
    for l in 0..=L_MAX {
        for m in 0..(2 * l + 1) {
            cg_entries.push(CgEntry {
                i_m: 0,
                j_m: m,
                k_m: m,
                value: CG_VALUES[CG_OFFSETS[l] + m],
            });
        }
    }
    Ok(TensorProductPlan::new(
        "128x0e".parse()?,
        "1x0e+1x1o+1x2e+1x3o".parse()?,
        "128x0e+128x1o+128x2e+128x3o".parse()?,
        instructions,
        cg_entries,
        MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
    )?)
}

#[allow(dead_code)]
fn mace_mh1_interaction1_conv_tp_plan() -> Result<&'static TensorProductPlan, MaceMh1Error> {
    mace_mh1_interaction1_conv_tp_plan_for(MaceMh1WignerMode::default())
}

fn mace_mh1_interaction1_conv_tp_plan_for(
    wigner_mode: MaceMh1WignerMode,
) -> Result<&'static TensorProductPlan, MaceMh1Error> {
    let cached = match wigner_mode {
        MaceMh1WignerMode::TrueFloat64 => {
            MACE_MH1_INTERACTION1_CONV_TP_PLAN_TRUE_F64.get_or_init(|| {
                build_mace_mh1_interaction1_conv_tp_plan(wigner_mode).map_err(|err| err.to_string())
            })
        }
        MaceMh1WignerMode::UpstreamArtifact => MACE_MH1_INTERACTION1_CONV_TP_PLAN_UPSTREAM
            .get_or_init(|| {
                build_mace_mh1_interaction1_conv_tp_plan(wigner_mode).map_err(|err| err.to_string())
            }),
    };
    cached_mace_mh1_conv_tp_plan(cached, "interaction-1")
}

