fn mace_mh1_interaction1_cg_value(wigner_mode: MaceMh1WignerMode, index: usize, value: f64) -> f64 {
    match wigner_mode {
        MaceMh1WignerMode::TrueFloat64 => value,
        MaceMh1WignerMode::UpstreamArtifact => {
            // The serialized upstream TensorProduct keeps generic Wigner 3j
            // constants in TorchScript buffers that were captured as f32, then
            // promoted by model.double(). l=0 specialized paths use scalar
            // sqrt constants instead and must stay f64.
            if (10..21).contains(&index) || (26..58).contains(&index) || (65..86).contains(&index) {
                f64::from(value as f32)
            } else {
                value
            }
        }
    }
}

fn torch_linear_rows_from_parts(
    input: &[f64],
    weight: &[f64],
    bias: &[f64],
    input_dim: usize,
    output_dim: usize,
    name: &str,
) -> Result<Vec<f64>, MaceMh1Error> {
    let rows = checked_row_count(name, input.len(), input_dim)?;
    if weight.len() != output_dim * input_dim {
        return Err(invalid(format!(
            "{name} weight length {} does not match output_dim {output_dim} * input_dim {input_dim}",
            weight.len()
        )));
    }
    if bias.len() != output_dim {
        return Err(invalid(format!(
            "{name} bias length {} does not match output_dim {output_dim}",
            bias.len()
        )));
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64"),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    ))]
    if rows >= mace_mh1_blas_dispatch_threshold() && input_dim >= 16 && output_dim >= 16 {
        let mut output = vec![0.0; rows * output_dim];
        blas_backend::dense_forward_output_major_weight(
            input,
            rows,
            input_dim,
            weight,
            &mut output,
            output_dim,
            1.0,
            0.0,
        );
        for row in output.chunks_exact_mut(output_dim) {
            for (value, &bias_value) in row.iter_mut().zip(bias) {
                *value += bias_value;
            }
        }
        return Ok(output);
    }
    let mut output = vec![0.0; rows * output_dim];
    for row in 0..rows {
        let input_row = &input[row * input_dim..(row + 1) * input_dim];
        let output_row = &mut output[row * output_dim..(row + 1) * output_dim];
        for out_feature in 0..output_dim {
            let mut value = bias[out_feature];
            let weight_row = &weight[out_feature * input_dim..(out_feature + 1) * input_dim];
            for (&weight, &input_value) in weight_row.iter().zip(input_row) {
                value += weight * input_value;
            }
            output_row[out_feature] = value;
        }
    }
    Ok(output)
}

#[allow(dead_code)]
fn torch_linear_rows_from_parts_f32(
    input: &[f32],
    weight: &[f32],
    bias: &[f32],
    input_dim: usize,
    output_dim: usize,
    name: &str,
) -> Result<Vec<f32>, MaceMh1Error> {
    let rows = checked_row_count(name, input.len(), input_dim)?;
    if weight.len() != output_dim * input_dim {
        return Err(invalid(format!(
            "{name} f32 weight length {} does not match output_dim {output_dim} * input_dim {input_dim}",
            weight.len()
        )));
    }
    if bias.len() != output_dim {
        return Err(invalid(format!(
            "{name} f32 bias length {} does not match output_dim {output_dim}",
            bias.len()
        )));
    }
    let mut output = vec![0.0; rows * output_dim];
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if rows >= mace_mh1_blas_dispatch_threshold() && input_dim >= 16 && output_dim >= 16 {
        blas_backend::dense_forward_output_major_weight_f32(
            input,
            rows,
            input_dim,
            weight,
            &mut output,
            output_dim,
            1.0,
            0.0,
        );
        add_bias_to_rows_f32(&mut output, bias, output_dim);
        return Ok(output);
    }
    for row in 0..rows {
        let input_row = &input[row * input_dim..(row + 1) * input_dim];
        let output_row = &mut output[row * output_dim..(row + 1) * output_dim];
        for out_feature in 0..output_dim {
            let mut value = bias[out_feature];
            let weight_row = &weight[out_feature * input_dim..(out_feature + 1) * input_dim];
            for (&weight, &input_value) in weight_row.iter().zip(input_row) {
                value += weight * input_value;
            }
            output_row[out_feature] = value;
        }
    }
    Ok(output)
}

#[allow(dead_code)]
fn add_bias_to_rows_f32(output: &mut [f32], bias: &[f32], output_dim: usize) {
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1
        && output_dim > 0
        && output.len() / output_dim >= MACE_MH1_ROW_PARALLEL_MIN_ROWS
    {
        output.par_chunks_exact_mut(output_dim).for_each(|row| {
            for (value, &bias_value) in row.iter_mut().zip(bias) {
                *value += bias_value;
            }
        });
        return;
    }

    for row in output.chunks_exact_mut(output_dim) {
        for (value, &bias_value) in row.iter_mut().zip(bias) {
            *value += bias_value;
        }
    }
}

fn torch_linear_vjp_input_from_parts(
    weight: &[f64],
    input_dim: usize,
    output_dim: usize,
    name: &str,
    bar_output: &[f64],
    bar_input: &mut [f64],
) -> Result<(), MaceMh1Error> {
    let rows = checked_row_count(&format!("{name}.bar_output"), bar_output.len(), output_dim)?;
    if weight.len() != output_dim * input_dim {
        return Err(invalid(format!(
            "{name} weight length {} does not match output_dim {output_dim} * input_dim {input_dim}",
            weight.len()
        )));
    }
    if bar_input.len() != rows * input_dim {
        return Err(invalid(format!(
            "{name} bar_input length {} does not match rows {rows} * input_dim {input_dim}",
            bar_input.len()
        )));
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64"),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    ))]
    if rows >= mace_mh1_blas_dispatch_threshold() && input_dim >= 16 && output_dim >= 16 {
        blas_backend::dense_vjp_input_output_major_weight(
            rows, input_dim, output_dim, weight, bar_output, bar_input, 1.0, 1.0,
        );
        return Ok(());
    }
    for row in 0..rows {
        let bar_output_row = &bar_output[row * output_dim..(row + 1) * output_dim];
        let bar_input_row = &mut bar_input[row * input_dim..(row + 1) * input_dim];
        for (out_feature, &bar) in bar_output_row.iter().enumerate() {
            let weight_row = &weight[out_feature * input_dim..(out_feature + 1) * input_dim];
            for (bar_input_value, &weight_value) in bar_input_row.iter_mut().zip(weight_row) {
                *bar_input_value += bar * weight_value;
            }
        }
    }
    Ok(())
}

#[allow(dead_code, clippy::too_many_arguments)]
fn torch_linear_vjp_input_from_parts_column_block(
    weight: &[f64],
    input_dim: usize,
    output_dim: usize,
    column_offset: usize,
    selected_input_dim: usize,
    name: &str,
    bar_output: &[f64],
    bar_input: &mut [f64],
) -> Result<(), MaceMh1Error> {
    let rows = checked_row_count(
        &format!("{name}.column_block.bar_output"),
        bar_output.len(),
        output_dim,
    )?;
    if column_offset > input_dim || selected_input_dim > input_dim - column_offset {
        return Err(invalid(format!(
            "{name} column block {column_offset}..{} exceeds input_dim {input_dim}",
            column_offset + selected_input_dim
        )));
    }
    if weight.len() != output_dim * input_dim {
        return Err(invalid(format!(
            "{name} weight length {} does not match output_dim {output_dim} * input_dim {input_dim}",
            weight.len()
        )));
    }
    if bar_input.len() != rows * selected_input_dim {
        return Err(invalid(format!(
            "{name} column-block bar_input length {} does not match rows {rows} * selected_input_dim {selected_input_dim}",
            bar_input.len()
        )));
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64"),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    ))]
    if rows >= mace_mh1_blas_dispatch_threshold() && selected_input_dim >= 1 && output_dim >= 16 {
        blas_backend::dense_vjp_input_output_major_weight_column_block_add(
            rows,
            selected_input_dim,
            input_dim,
            output_dim,
            column_offset,
            weight,
            bar_output,
            bar_input,
            1.0,
            1.0,
        );
        return Ok(());
    }
    for row in 0..rows {
        let bar_output_row = &bar_output[row * output_dim..(row + 1) * output_dim];
        let bar_input_row =
            &mut bar_input[row * selected_input_dim..(row + 1) * selected_input_dim];
        for (out_feature, &bar) in bar_output_row.iter().enumerate() {
            let weight_row = &weight[out_feature * input_dim + column_offset
                ..out_feature * input_dim + column_offset + selected_input_dim];
            for (bar_input_value, &weight_value) in bar_input_row.iter_mut().zip(weight_row) {
                *bar_input_value += bar * weight_value;
            }
        }
    }
    Ok(())
}

