fn layer_norm_rows_from_parts(
    input: &[f64],
    weight: &[f64],
    bias: &[f64],
    width: usize,
    eps: f64,
    name: &str,
) -> Result<Vec<f64>, MaceMh1Error> {
    let rows = checked_row_count(name, input.len(), width)?;
    if weight.len() != width {
        return Err(invalid(format!(
            "{name} layer-norm weight length {} does not match width {width}",
            weight.len()
        )));
    }
    if bias.len() != width {
        return Err(invalid(format!(
            "{name} layer-norm bias length {} does not match width {width}",
            bias.len()
        )));
    }
    let mut output = vec![0.0; input.len()];
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && rows >= MACE_MH1_ROW_PARALLEL_MIN_ROWS {
        output
            .par_chunks_mut(width)
            .zip(input.par_chunks(width))
            .for_each(|(output_row, input_row)| {
                let mean = input_row.iter().sum::<f64>() / width as f64;
                let variance = input_row
                    .iter()
                    .map(|value| {
                        let delta = value - mean;
                        delta * delta
                    })
                    .sum::<f64>()
                    / width as f64;
                let denom = (variance + eps).sqrt();
                for feature in 0..width {
                    output_row[feature] =
                        ((input_row[feature] - mean) / denom) * weight[feature] + bias[feature];
                }
            });
        return Ok(output);
    }
    for row in 0..rows {
        let input_row = &input[row * width..(row + 1) * width];
        let output_row = &mut output[row * width..(row + 1) * width];
        let mean = input_row.iter().sum::<f64>() / width as f64;
        let variance = input_row
            .iter()
            .map(|value| {
                let delta = value - mean;
                delta * delta
            })
            .sum::<f64>()
            / width as f64;
        let denom = (variance + eps).sqrt();
        for feature in 0..width {
            output_row[feature] =
                ((input_row[feature] - mean) / denom) * weight[feature] + bias[feature];
        }
    }
    Ok(output)
}

