fn layer_norm_vjp_input_from_parts(
    input: &[f64],
    weight: &[f64],
    width: usize,
    eps: f64,
    name: &str,
    bar_output: &[f64],
    bar_input: &mut [f64],
) -> Result<(), MaceMh1Error> {
    let rows = checked_row_count(name, input.len(), width)?;
    if weight.len() != width {
        return Err(invalid(format!(
            "{name} layer-norm weight length {} does not match width {width}",
            weight.len()
        )));
    }
    if bar_output.len() != input.len() {
        return Err(invalid(format!(
            "{name} bar_output length {} does not match input length {}",
            bar_output.len(),
            input.len()
        )));
    }
    if bar_input.len() != input.len() {
        return Err(invalid(format!(
            "{name} bar_input length {} does not match input length {}",
            bar_input.len(),
            input.len()
        )));
    }

    let inv_width = 1.0 / width as f64;
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && rows >= MACE_MH1_ROW_PARALLEL_MIN_ROWS {
        bar_input
            .par_chunks_mut(width)
            .zip(input.par_chunks(width))
            .zip(bar_output.par_chunks(width))
            .for_each(|((bar_input_row, input_row), bar_output_row)| {
                let mean = input_row.iter().sum::<f64>() * inv_width;
                let variance = input_row
                    .iter()
                    .map(|value| {
                        let delta = value - mean;
                        delta * delta
                    })
                    .sum::<f64>()
                    * inv_width;
                let denom = (variance + eps).sqrt();
                let inv_denom = 1.0 / denom;
                let mut sum_bar_normalized = 0.0;
                let mut sum_bar_normalized_times_normalized = 0.0;
                for feature in 0..width {
                    let normalized = (input_row[feature] - mean) * inv_denom;
                    let bar_normalized = bar_output_row[feature] * weight[feature];
                    sum_bar_normalized += bar_normalized;
                    sum_bar_normalized_times_normalized += bar_normalized * normalized;
                }
                for feature in 0..width {
                    let normalized = (input_row[feature] - mean) * inv_denom;
                    let bar_normalized = bar_output_row[feature] * weight[feature];
                    bar_input_row[feature] += inv_denom
                        * inv_width
                        * (width as f64 * bar_normalized
                            - sum_bar_normalized
                            - normalized * sum_bar_normalized_times_normalized);
                }
            });
        return Ok(());
    }
    for row in 0..rows {
        let input_row = &input[row * width..(row + 1) * width];
        let bar_output_row = &bar_output[row * width..(row + 1) * width];
        let bar_input_row = &mut bar_input[row * width..(row + 1) * width];
        let mean = input_row.iter().sum::<f64>() * inv_width;
        let variance = input_row
            .iter()
            .map(|value| {
                let delta = value - mean;
                delta * delta
            })
            .sum::<f64>()
            * inv_width;
        let denom = (variance + eps).sqrt();
        let inv_denom = 1.0 / denom;
        let mut sum_bar_normalized = 0.0;
        let mut sum_bar_normalized_times_normalized = 0.0;
        for feature in 0..width {
            let normalized = (input_row[feature] - mean) * inv_denom;
            let bar_normalized = bar_output_row[feature] * weight[feature];
            sum_bar_normalized += bar_normalized;
            sum_bar_normalized_times_normalized += bar_normalized * normalized;
        }
        for feature in 0..width {
            let normalized = (input_row[feature] - mean) * inv_denom;
            let bar_normalized = bar_output_row[feature] * weight[feature];
            bar_input_row[feature] += inv_denom
                * inv_width
                * (width as f64 * bar_normalized
                    - sum_bar_normalized
                    - normalized * sum_bar_normalized_times_normalized);
        }
    }
    Ok(())
}

