fn validate_edge_input_geometry(
    edge_input: &MaceMh1EdgeInputBoundary,
    prefix: &str,
) -> Result<(), MaceMh1Error> {
    let edge_count = edge_input.edge_count;
    if edge_input.edge_src.len() != edge_count
        || edge_input.edge_dst.len() != edge_count
        || edge_input.edge_vectors.len() != edge_count
        || edge_input.edge_distances.len() != edge_count
        || edge_input.edge_src_atomic_numbers.len() != edge_count
        || edge_input.edge_dst_atomic_numbers.len() != edge_count
        || edge_input.edge_cutoff.len() != edge_count
    {
        return Err(invalid(format!(
            "{prefix} edge metadata lengths must all match edge_count {edge_count}"
        )));
    }
    if edge_input.edge_attrs.len() != edge_count * MACE_MH1_SH_DIM {
        return Err(invalid(format!("{prefix} edge_attrs length mismatch")));
    }
    if edge_input.edge_feats.len() != edge_count * MACE_MH1_NUM_BESSEL {
        return Err(invalid(format!("{prefix} edge_feats length mismatch")));
    }
    for (edge, (&distance, vector)) in edge_input
        .edge_distances
        .iter()
        .zip(&edge_input.edge_vectors)
        .enumerate()
    {
        if !distance.is_finite() || distance <= 0.0 {
            return Err(invalid(format!(
                "{prefix} edge {edge} distance must be positive and finite, got {distance}"
            )));
        }
        if !vector.iter().all(|value| value.is_finite()) {
            return Err(invalid(format!(
                "{prefix} edge {edge} vector contains a non-finite value"
            )));
        }
    }
    Ok(())
}

fn decompose_edge_mlp_augmented_bars(
    prefix: &str,
    input_dim: usize,
    edge_input: &MaceMh1EdgeInputBoundary,
    bar_augmented: &[f64],
    bar_edge_feats: &mut [f64],
    bar_source_embedding: &mut [f64],
    bar_target_embedding: &mut [f64],
) -> Result<(), MaceMh1Error> {
    let edge_count = checked_row_count(prefix, bar_augmented.len(), input_dim)?;
    if edge_count != edge_input.edge_count {
        return Err(invalid(format!(
            "{prefix} bar_augmented row count {edge_count} does not match edge_count {}",
            edge_input.edge_count
        )));
    }
    if bar_edge_feats.len() != edge_count * MACE_MH1_NUM_BESSEL {
        return Err(invalid(format!("{prefix} bar_edge_feats length mismatch")));
    }
    let source_rows = checked_row_count(
        &format!("{prefix}.source_embedding"),
        bar_source_embedding.len(),
        MACE_MH1_NODE_CHANNELS,
    )?;
    let target_rows = checked_row_count(
        &format!("{prefix}.target_embedding"),
        bar_target_embedding.len(),
        MACE_MH1_NODE_CHANNELS,
    )?;
    if edge_input.edge_src.len() != edge_count || edge_input.edge_dst.len() != edge_count {
        return Err(invalid(format!("{prefix} edge index length mismatch")));
    }

    let source_offset = MACE_MH1_NUM_BESSEL;
    let target_offset = source_offset + MACE_MH1_NODE_CHANNELS;
    for edge in 0..edge_count {
        let src = edge_input.edge_src[edge];
        let dst = edge_input.edge_dst[edge];
        if src >= source_rows || dst >= target_rows {
            return Err(invalid(format!(
                "{prefix} edge {edge} index {src}->{dst} is out of range for source rows {source_rows} and target rows {target_rows}"
            )));
        }
        let bar_augmented_row = &bar_augmented[edge * input_dim..(edge + 1) * input_dim];
        let bar_edge_feats_row =
            &mut bar_edge_feats[edge * MACE_MH1_NUM_BESSEL..(edge + 1) * MACE_MH1_NUM_BESSEL];
        for (dst_value, &bar) in bar_edge_feats_row
            .iter_mut()
            .zip(&bar_augmented_row[..MACE_MH1_NUM_BESSEL])
        {
            *dst_value += bar;
        }
        let bar_source_row = &mut bar_source_embedding
            [src * MACE_MH1_NODE_CHANNELS..(src + 1) * MACE_MH1_NODE_CHANNELS];
        for (dst_value, &bar) in bar_source_row
            .iter_mut()
            .zip(&bar_augmented_row[source_offset..source_offset + MACE_MH1_NODE_CHANNELS])
        {
            *dst_value += bar;
        }
        let bar_target_row = &mut bar_target_embedding
            [dst * MACE_MH1_NODE_CHANNELS..(dst + 1) * MACE_MH1_NODE_CHANNELS];
        for (dst_value, &bar) in bar_target_row
            .iter_mut()
            .zip(&bar_augmented_row[target_offset..target_offset + MACE_MH1_NODE_CHANNELS])
        {
            *dst_value += bar;
        }
    }
    Ok(())
}

#[cfg(target_arch = "x86_64")]
#[inline(always)]
fn mace_mh1_avx2_fma_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var_os("LLMLIP_DISABLE_SIMD").is_none()
            && std::env::var_os("LLMLIP_DISABLE_AVX2").is_none()
            && std::env::var_os("LLMLIP_DISABLE_AVX").is_none()
            && std::is_x86_feature_detected!("avx2")
            && std::is_x86_feature_detected!("fma")
    })
}

#[cfg(target_arch = "x86_64")]
#[allow(dead_code)]
#[allow(unsafe_code)]
#[inline(always)]
fn mace_mh1_fill_conv_tp_cutoff_row_f64_avx2_safe(
    cutoff: f64,
    bar_cutoff: &[f64],
    cutoff_weights: &[f64],
    bar_raw: &mut [f64],
) -> f64 {
    debug_assert!(mace_mh1_avx2_fma_enabled());
    debug_assert!(
        bar_raw.iter().all(|&value| value == 0.0),
        "MACE-MH-1 AVX2 cutoff row helper overwrites bar_raw; callers must pass zero-initialized rows"
    );
    // SAFETY: runtime AVX2/FMA detection guards this call. Slices are validated
    // by the caller to have equal contiguous row lengths. The AVX2 kernel stores
    // raw bars directly instead of accumulating, so callers must pass a zeroed
    // per-edge row.
    unsafe {
        mace_mh1_fill_conv_tp_cutoff_row_f64_avx2(cutoff, bar_cutoff, cutoff_weights, bar_raw)
    }
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
#[target_feature(enable = "fma")]
#[allow(dead_code)]
#[allow(unsafe_code)]
unsafe fn mace_mh1_fill_conv_tp_cutoff_row_f64_avx2(
    cutoff: f64,
    bar_cutoff: &[f64],
    cutoff_weights: &[f64],
    bar_raw: &mut [f64],
) -> f64 {
    use std::arch::x86_64::*;

    debug_assert_eq!(bar_cutoff.len(), cutoff_weights.len());
    debug_assert_eq!(bar_cutoff.len(), bar_raw.len());

    let cutoff_v = _mm256_set1_pd(cutoff);
    let mut acc = _mm256_setzero_pd();
    let mut i = 0;
    while i + 4 <= bar_cutoff.len() {
        let bar = _mm256_loadu_pd(bar_cutoff.as_ptr().add(i));
        let weights = _mm256_loadu_pd(cutoff_weights.as_ptr().add(i));
        _mm256_storeu_pd(bar_raw.as_mut_ptr().add(i), _mm256_mul_pd(bar, cutoff_v));
        acc = _mm256_fmadd_pd(bar, weights, acc);
        i += 4;
    }

    let mut lanes = [0.0; 4];
    _mm256_storeu_pd(lanes.as_mut_ptr(), acc);
    let mut dot = lanes.iter().sum::<f64>();
    while i < bar_cutoff.len() {
        let bar = bar_cutoff[i];
        bar_raw[i] = bar * cutoff;
        dot += bar * cutoff_weights[i];
        i += 1;
    }
    dot / cutoff
}

#[cfg(target_arch = "x86_64")]
#[allow(dead_code)]
#[allow(unsafe_code)]
#[inline(always)]
fn mace_mh1_fill_conv_tp_cutoff_row_f32_avx2_safe(
    cutoff: f32,
    bar_cutoff: &[f32],
    cutoff_weights: &[f32],
    bar_raw: &mut [f32],
) -> f32 {
    debug_assert!(mace_mh1_avx2_fma_enabled());
    debug_assert!(
        bar_raw.iter().all(|&value| value == 0.0),
        "MACE-MH-1 AVX2 cutoff row helper overwrites bar_raw; callers must pass zero-initialized rows"
    );
    // SAFETY: runtime AVX2/FMA detection guards this call. Slices are validated
    // by the caller to have equal contiguous row lengths. The AVX2 kernel stores
    // raw bars directly instead of accumulating, so callers must pass a zeroed
    // per-edge row.
    unsafe {
        mace_mh1_fill_conv_tp_cutoff_row_f32_avx2(cutoff, bar_cutoff, cutoff_weights, bar_raw)
    }
}

