#[cfg(target_arch = "x86_64")]
#[allow(unsafe_code)]
#[inline(always)]
fn mace_mh1_scale_row_by_cutoff_f64_avx2_safe(cutoff: f64, values: &mut [f64]) {
    debug_assert!(mace_mh1_avx2_fma_enabled());
    // SAFETY: runtime AVX2 detection guards this call. The row is contiguous.
    unsafe {
        mace_mh1_scale_row_by_cutoff_f64_avx2(cutoff, values);
    }
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
#[allow(unsafe_code)]
unsafe fn mace_mh1_scale_row_by_cutoff_f64_avx2(cutoff: f64, values: &mut [f64]) {
    use std::arch::x86_64::*;

    let cutoff_v = _mm256_set1_pd(cutoff);
    let mut i = 0;
    while i + 4 <= values.len() {
        let value = _mm256_loadu_pd(values.as_ptr().add(i));
        _mm256_storeu_pd(values.as_mut_ptr().add(i), _mm256_mul_pd(value, cutoff_v));
        i += 4;
    }
    while i < values.len() {
        values[i] *= cutoff;
        i += 1;
    }
}

fn mace_mh1_scale_rows_by_cutoff_f64(
    edge_count: usize,
    row_width: usize,
    edge_cutoff: &[f64],
    values: &mut [f64],
) {
    debug_assert_eq!(edge_cutoff.len(), edge_count);
    debug_assert_eq!(values.len(), edge_count * row_width);
    #[cfg(target_arch = "x86_64")]
    let use_avx2 = mace_mh1_avx2_fma_enabled();

    #[cfg(feature = "parallel")]
    if edge_count >= MACE_MH1_EDGE_MLP_CUTOFF_BAR_PARALLEL_MIN_EDGES {
        values
            .par_chunks_mut(row_width)
            .zip(edge_cutoff.par_iter())
            .for_each(|(row, &cutoff)| {
                #[cfg(target_arch = "x86_64")]
                if use_avx2 {
                    mace_mh1_scale_row_by_cutoff_f64_avx2_safe(cutoff, row);
                    return;
                }
                for value in row {
                    *value *= cutoff;
                }
            });
        return;
    }

    for (row, &cutoff) in values.chunks_exact_mut(row_width).zip(edge_cutoff) {
        #[cfg(target_arch = "x86_64")]
        if use_avx2 {
            mace_mh1_scale_row_by_cutoff_f64_avx2_safe(cutoff, row);
            continue;
        }
        for value in row {
            *value *= cutoff;
        }
    }
}

#[allow(dead_code, clippy::too_many_arguments)]
fn mace_mh1_fill_conv_tp_cutoff_bars(
    edge_count: usize,
    tp_weight_dim: usize,
    edge_cutoff: &[f64],
    cutoff_conv_tp_weights: &[f64],
    raw_conv_tp_weights: Option<&[f64]>,
    bar_cutoff_conv_tp_weights: &[f64],
    bar_raw_conv_tp_weights: &mut [f64],
    local_bar_edge_cutoff: &mut [f64],
) {
    debug_assert_eq!(edge_cutoff.len(), edge_count);
    debug_assert_eq!(cutoff_conv_tp_weights.len(), edge_count * tp_weight_dim);
    debug_assert_eq!(bar_cutoff_conv_tp_weights.len(), edge_count * tp_weight_dim);
    debug_assert_eq!(bar_raw_conv_tp_weights.len(), edge_count * tp_weight_dim);
    debug_assert_eq!(local_bar_edge_cutoff.len(), edge_count);
    if let Some(raw) = raw_conv_tp_weights {
        debug_assert_eq!(raw.len(), edge_count * tp_weight_dim);
    }
    #[cfg(target_arch = "x86_64")]
    let use_avx2 = raw_conv_tp_weights.is_none() && mace_mh1_avx2_fma_enabled();

    #[cfg(feature = "parallel")]
    if edge_count >= MACE_MH1_EDGE_MLP_CUTOFF_BAR_PARALLEL_MIN_EDGES {
        bar_raw_conv_tp_weights
            .par_chunks_mut(tp_weight_dim)
            .zip(local_bar_edge_cutoff.par_iter_mut())
            .enumerate()
            .for_each(|(edge, (bar_raw_row, cutoff_bar))| {
                let cutoff = edge_cutoff[edge];
                let row_start = edge * tp_weight_dim;
                let row_end = row_start + tp_weight_dim;
                let mut local_cutoff_bar = 0.0;
                if let Some(raw) = raw_conv_tp_weights {
                    for (local, index) in (row_start..row_end).enumerate() {
                        let bar = bar_cutoff_conv_tp_weights[index];
                        bar_raw_row[local] += bar * cutoff;
                        local_cutoff_bar += bar * raw[index];
                    }
                } else {
                    #[cfg(target_arch = "x86_64")]
                    if use_avx2 {
                        let bar_cutoff_row = &bar_cutoff_conv_tp_weights[row_start..row_end];
                        let cutoff_weight_row = &cutoff_conv_tp_weights[row_start..row_end];
                        *cutoff_bar = mace_mh1_fill_conv_tp_cutoff_row_f64_avx2_safe(
                            cutoff,
                            bar_cutoff_row,
                            cutoff_weight_row,
                            bar_raw_row,
                        );
                        return;
                    }
                    let inv_cutoff = 1.0 / cutoff;
                    for (local, index) in (row_start..row_end).enumerate() {
                        let bar = bar_cutoff_conv_tp_weights[index];
                        bar_raw_row[local] += bar * cutoff;
                        local_cutoff_bar += bar * cutoff_conv_tp_weights[index];
                    }
                    local_cutoff_bar *= inv_cutoff;
                }
                *cutoff_bar = local_cutoff_bar;
            });
        return;
    }

    for edge in 0..edge_count {
        let cutoff = edge_cutoff[edge];
        let row_start = edge * tp_weight_dim;
        let row_end = row_start + tp_weight_dim;
        let bar_raw_row = &mut bar_raw_conv_tp_weights[row_start..row_end];
        let mut local_cutoff_bar = 0.0;
        if let Some(raw) = raw_conv_tp_weights {
            for (local, index) in (row_start..row_end).enumerate() {
                let bar = bar_cutoff_conv_tp_weights[index];
                bar_raw_row[local] += bar * cutoff;
                local_cutoff_bar += bar * raw[index];
            }
        } else {
            #[cfg(target_arch = "x86_64")]
            if use_avx2 {
                let bar_cutoff_row = &bar_cutoff_conv_tp_weights[row_start..row_end];
                let cutoff_weight_row = &cutoff_conv_tp_weights[row_start..row_end];
                local_bar_edge_cutoff[edge] = mace_mh1_fill_conv_tp_cutoff_row_f64_avx2_safe(
                    cutoff,
                    bar_cutoff_row,
                    cutoff_weight_row,
                    bar_raw_row,
                );
                continue;
            }
            let inv_cutoff = 1.0 / cutoff;
            for (local, index) in (row_start..row_end).enumerate() {
                let bar = bar_cutoff_conv_tp_weights[index];
                bar_raw_row[local] += bar * cutoff;
                local_cutoff_bar += bar * cutoff_conv_tp_weights[index];
            }
            local_cutoff_bar *= inv_cutoff;
        }
        local_bar_edge_cutoff[edge] = local_cutoff_bar;
    }
}

#[allow(dead_code, clippy::too_many_arguments)]
fn mace_mh1_fill_conv_tp_cutoff_bars_f32(
    edge_count: usize,
    tp_weight_dim: usize,
    edge_cutoff: &[f64],
    cutoff_conv_tp_weights_f64: Option<&[f64]>,
    cutoff_conv_tp_weights_f32: Option<&[f32]>,
    bar_cutoff_conv_tp_weights: &[f32],
    bar_raw_conv_tp_weights: &mut [f32],
    local_bar_edge_cutoff: &mut [f32],
) {
    debug_assert_eq!(edge_cutoff.len(), edge_count);
    debug_assert_eq!(bar_cutoff_conv_tp_weights.len(), edge_count * tp_weight_dim);
    debug_assert_eq!(bar_raw_conv_tp_weights.len(), edge_count * tp_weight_dim);
    debug_assert_eq!(local_bar_edge_cutoff.len(), edge_count);
    if let Some(weights) = cutoff_conv_tp_weights_f64 {
        debug_assert_eq!(weights.len(), edge_count * tp_weight_dim);
    }
    if let Some(weights) = cutoff_conv_tp_weights_f32 {
        debug_assert_eq!(weights.len(), edge_count * tp_weight_dim);
    }
    #[cfg(target_arch = "x86_64")]
    let use_avx2 = cutoff_conv_tp_weights_f32.is_some() && mace_mh1_avx2_fma_enabled();

    #[cfg(feature = "parallel")]
    if edge_count >= MACE_MH1_EDGE_MLP_CUTOFF_BAR_PARALLEL_MIN_EDGES {
        bar_raw_conv_tp_weights
            .par_chunks_mut(tp_weight_dim)
            .zip(local_bar_edge_cutoff.par_iter_mut())
            .enumerate()
            .for_each(|(edge, (bar_raw_row, cutoff_bar))| {
                let cutoff = edge_cutoff[edge] as f32;
                let row_start = edge * tp_weight_dim;
                let row_end = row_start + tp_weight_dim;
                let mut local_cutoff_bar = 0.0_f32;
                if cutoff != 0.0 {
                    let inv_cutoff = 1.0_f32 / cutoff;
                    if let Some(weights) = cutoff_conv_tp_weights_f32 {
                        #[cfg(target_arch = "x86_64")]
                        if use_avx2 {
                            let bar_cutoff_row = &bar_cutoff_conv_tp_weights[row_start..row_end];
                            let cutoff_weight_row = &weights[row_start..row_end];
                            *cutoff_bar = mace_mh1_fill_conv_tp_cutoff_row_f32_avx2_safe(
                                cutoff,
                                bar_cutoff_row,
                                cutoff_weight_row,
                                bar_raw_row,
                            );
                            return;
                        }
                        for (local, index) in (row_start..row_end).enumerate() {
                            let bar = bar_cutoff_conv_tp_weights[index];
                            bar_raw_row[local] += bar * cutoff;
                            local_cutoff_bar += bar * weights[index];
                        }
                    } else if let Some(weights) = cutoff_conv_tp_weights_f64 {
                        for (local, index) in (row_start..row_end).enumerate() {
                            let bar = bar_cutoff_conv_tp_weights[index];
                            bar_raw_row[local] += bar * cutoff;
                            local_cutoff_bar += bar * weights[index] as f32;
                        }
                    } else {
                        for (local, index) in (row_start..row_end).enumerate() {
                            bar_raw_row[local] += bar_cutoff_conv_tp_weights[index] * cutoff;
                        }
                    }
                    local_cutoff_bar *= inv_cutoff;
                } else {
                    for (local, index) in (row_start..row_end).enumerate() {
                        bar_raw_row[local] += bar_cutoff_conv_tp_weights[index] * cutoff;
                    }
                }
                *cutoff_bar = local_cutoff_bar;
            });
        return;
    }

    for edge in 0..edge_count {
        let cutoff = edge_cutoff[edge] as f32;
        let row_start = edge * tp_weight_dim;
        let row_end = row_start + tp_weight_dim;
        let bar_raw_row = &mut bar_raw_conv_tp_weights[row_start..row_end];
        let mut local_cutoff_bar = 0.0_f32;
        if cutoff != 0.0 {
            let inv_cutoff = 1.0_f32 / cutoff;
            if let Some(weights) = cutoff_conv_tp_weights_f32 {
                #[cfg(target_arch = "x86_64")]
                if use_avx2 {
                    let bar_cutoff_row = &bar_cutoff_conv_tp_weights[row_start..row_end];
                    let cutoff_weight_row = &weights[row_start..row_end];
                    local_bar_edge_cutoff[edge] = mace_mh1_fill_conv_tp_cutoff_row_f32_avx2_safe(
                        cutoff,
                        bar_cutoff_row,
                        cutoff_weight_row,
                        bar_raw_row,
                    );
                    continue;
                }
                for (local, index) in (row_start..row_end).enumerate() {
                    let bar = bar_cutoff_conv_tp_weights[index];
                    bar_raw_row[local] += bar * cutoff;
                    local_cutoff_bar += bar * weights[index];
                }
            } else if let Some(weights) = cutoff_conv_tp_weights_f64 {
                for (local, index) in (row_start..row_end).enumerate() {
                    let bar = bar_cutoff_conv_tp_weights[index];
                    bar_raw_row[local] += bar * cutoff;
                    local_cutoff_bar += bar * weights[index] as f32;
                }
            } else {
                for (local, index) in (row_start..row_end).enumerate() {
                    bar_raw_row[local] += bar_cutoff_conv_tp_weights[index] * cutoff;
                }
            }
            local_cutoff_bar *= inv_cutoff;
        } else {
            for (local, index) in (row_start..row_end).enumerate() {
                bar_raw_row[local] += bar_cutoff_conv_tp_weights[index] * cutoff;
            }
        }
        local_bar_edge_cutoff[edge] = local_cutoff_bar;
    }
}

fn decompose_edge_mlp_augmented_bars_radial_only(
    prefix: &str,
    input_dim: usize,
    edge_input: &MaceMh1EdgeInputBoundary,
    bar_augmented: &[f64],
    bar_edge_feats: &mut [f64],
) -> Result<(), MaceMh1Error> {
    let edge_count = checked_row_count(prefix, bar_augmented.len(), input_dim)?;
    if edge_count != edge_input.edge_count {
        return Err(invalid(format!(
            "{prefix} bar_augmented row count {edge_count} does not match edge_count {}",
            edge_input.edge_count
        )));
    }
    if bar_edge_feats.len() != edge_count * MACE_MH1_NUM_BESSEL {
        return Err(invalid(format!("{prefix} bar_edge_feats length mismatch")));
    }

    for edge in 0..edge_count {
        let bar_augmented_row = &bar_augmented[edge * input_dim..(edge + 1) * input_dim];
        let bar_edge_feats_row =
            &mut bar_edge_feats[edge * MACE_MH1_NUM_BESSEL..(edge + 1) * MACE_MH1_NUM_BESSEL];
        for (dst_value, &bar) in bar_edge_feats_row
            .iter_mut()
            .zip(&bar_augmented_row[..MACE_MH1_NUM_BESSEL])
        {
            *dst_value += bar;
        }
    }
    Ok(())
}

