fn apply_silu(values: &mut [f64]) {
    for value in values {
        *value = silu(*value);
    }
}

#[allow(dead_code)]
fn apply_silu_f32(values: &mut [f32]) {
    for value in values {
        *value = silu_f32(*value);
    }
}

fn silu_with_sigmoid_cache(values: &[f64]) -> (Vec<f64>, Vec<f64>) {
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && values.len() >= MACE_MH1_ROW_PARALLEL_MIN_ROWS {
        let mut silu_values = vec![0.0; values.len()];
        let mut sigmoid_values = vec![0.0; values.len()];
        silu_values
            .par_iter_mut()
            .zip(sigmoid_values.par_iter_mut())
            .zip(values.par_iter())
            .for_each(|((silu_value, sigmoid_value), &value)| {
                let sigmoid = sigmoid(value);
                *sigmoid_value = sigmoid;
                *silu_value = value * sigmoid;
            });
        return (silu_values, sigmoid_values);
    }

    let mut silu_values = Vec::with_capacity(values.len());
    let mut sigmoid_values = Vec::with_capacity(values.len());
    for &value in values {
        let sigmoid = sigmoid(value);
        sigmoid_values.push(sigmoid);
        silu_values.push(value * sigmoid);
    }
    (silu_values, sigmoid_values)
}

fn silu_with_sigmoid_cache_f32(values: &[f32]) -> (Vec<f32>, Vec<f32>) {
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        )
    ))]
    {
        let mut silu_values = values.iter().map(|&value| -value).collect::<Vec<_>>();
        let mut sigmoid_values = vec![0.0_f32; values.len()];
        blas_backend::exp_f32(&silu_values, &mut sigmoid_values);
        for ((silu_value, sigmoid_value), &value) in silu_values
            .iter_mut()
            .zip(sigmoid_values.iter_mut())
            .zip(values)
        {
            let sigmoid = 1.0 / (1.0 + *sigmoid_value);
            *sigmoid_value = sigmoid;
            *silu_value = value * sigmoid;
        }
        (silu_values, sigmoid_values)
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        )
    )))]
    {
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && values.len() >= MACE_MH1_ROW_PARALLEL_MIN_ROWS {
            let mut silu_values = vec![0.0_f32; values.len()];
            let mut sigmoid_values = vec![0.0_f32; values.len()];
            silu_values
                .par_iter_mut()
                .zip(sigmoid_values.par_iter_mut())
                .zip(values.par_iter())
                .for_each(|((silu_value, sigmoid_value), &value)| {
                    let sigmoid = sigmoid_f32(value);
                    *silu_value = value * sigmoid;
                    *sigmoid_value = sigmoid;
                });
            return (silu_values, sigmoid_values);
        }

        let mut silu_values = Vec::with_capacity(values.len());
        let mut sigmoid_values = Vec::with_capacity(values.len());
        for &value in values {
            let sigmoid_value = sigmoid_f32(value);
            silu_values.push(value * sigmoid_value);
            sigmoid_values.push(sigmoid_value);
        }
        (silu_values, sigmoid_values)
    }
}

fn fill_strided_sigmoid_cache_f32(
    input: &[f32],
    rows: usize,
    input_row_stride: usize,
    width: usize,
    sigmoid_cache: &mut [f32],
) {
    debug_assert!(input.len() >= rows * input_row_stride);
    debug_assert_eq!(sigmoid_cache.len(), rows * width);

    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        )
    ))]
    {
        let mut negated = vec![0.0_f32; sigmoid_cache.len()];
        for row in 0..rows {
            let input_row = &input[row * input_row_stride..row * input_row_stride + width];
            let negated_row = &mut negated[row * width..(row + 1) * width];
            for (dst, &src) in negated_row.iter_mut().zip(input_row) {
                *dst = -src;
            }
        }
        blas_backend::exp_f32(&negated, sigmoid_cache);
        for value in sigmoid_cache {
            *value = 1.0 / (1.0 + *value);
        }
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        )
    )))]
    {
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 2 && rows >= 16 {
            sigmoid_cache
                .par_chunks_mut(width)
                .enumerate()
                .for_each(|(row, cache_row)| {
                    let input_row = &input[row * input_row_stride..row * input_row_stride + width];
                    for (dst, &src) in cache_row.iter_mut().zip(input_row) {
                        *dst = sigmoid_f32(src);
                    }
                });
            return;
        }
        for row in 0..rows {
            let input_row = &input[row * input_row_stride..row * input_row_stride + width];
            let cache_row = &mut sigmoid_cache[row * width..(row + 1) * width];
            for (dst, &src) in cache_row.iter_mut().zip(input_row) {
                *dst = sigmoid_f32(src);
            }
        }
    }
}

fn fill_strided_sigmoid_cache_f64(
    input: &[f64],
    rows: usize,
    input_row_stride: usize,
    width: usize,
    sigmoid_cache: &mut [f64],
) {
    debug_assert!(input.len() >= rows * input_row_stride);
    debug_assert_eq!(sigmoid_cache.len(), rows * width);

    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        )
    ))]
    {
        let mut negated = vec![0.0; sigmoid_cache.len()];
        for row in 0..rows {
            let input_row = &input[row * input_row_stride..row * input_row_stride + width];
            let negated_row = &mut negated[row * width..(row + 1) * width];
            for (dst, &src) in negated_row.iter_mut().zip(input_row) {
                *dst = -src;
            }
        }
        blas_backend::exp_f64(&negated, sigmoid_cache);
        for value in sigmoid_cache {
            *value = 1.0 / (1.0 + *value);
        }
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        )
    )))]
    {
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 2 && rows >= 16 {
            sigmoid_cache
                .par_chunks_mut(width)
                .enumerate()
                .for_each(|(row, cache_row)| {
                    let input_row = &input[row * input_row_stride..row * input_row_stride + width];
                    for (dst, &src) in cache_row.iter_mut().zip(input_row) {
                        *dst = sigmoid(src);
                    }
                });
            return;
        }
        for row in 0..rows {
            let input_row = &input[row * input_row_stride..row * input_row_stride + width];
            let cache_row = &mut sigmoid_cache[row * width..(row + 1) * width];
            for (dst, &src) in cache_row.iter_mut().zip(input_row) {
                *dst = sigmoid(src);
            }
        }
    }
}

fn silu(value: f64) -> f64 {
    if value >= 0.0 {
        value / (1.0 + (-value).exp())
    } else {
        let exp_value = value.exp();
        value * exp_value / (1.0 + exp_value)
    }
}

#[allow(dead_code)]
fn silu_f32(value: f32) -> f32 {
    if value >= 0.0 {
        value / (1.0 + (-value).exp())
    } else {
        let exp_value = value.exp();
        value * exp_value / (1.0 + exp_value)
    }
}

fn silu_derivative(value: f64) -> f64 {
    let sigmoid_value = sigmoid(value);
    silu_derivative_from_sigmoid(value, sigmoid_value)
}

fn silu_derivative_from_sigmoid(value: f64, sigmoid_value: f64) -> f64 {
    sigmoid_value * (1.0 + value * (1.0 - sigmoid_value))
}

fn silu_derivative_f32(value: f32) -> f32 {
    let sigmoid_value = sigmoid_f32(value);
    silu_derivative_from_sigmoid_f32(value, sigmoid_value)
}

fn silu_derivative_from_sigmoid_f32(value: f32, sigmoid_value: f32) -> f32 {
    sigmoid_value * (1.0 + value * (1.0 - sigmoid_value))
}

fn sigmoid(value: f64) -> f64 {
    if value >= 0.0 {
        1.0 / (1.0 + (-value).exp())
    } else {
        let exp_value = value.exp();
        exp_value / (1.0 + exp_value)
    }
}

fn sigmoid_f32(value: f32) -> f32 {
    if value >= 0.0 {
        1.0 / (1.0 + (-value).exp())
    } else {
        let exp_value = value.exp();
        exp_value / (1.0 + exp_value)
    }
}

#[allow(dead_code)]
fn sigmoid_derivative(value: f64) -> f64 {
    let sigmoid_value = sigmoid(value);
    sigmoid_value * (1.0 - sigmoid_value)
}

