fn require_eq(name: &str, actual: &str, expected: &str) -> Result<(), MaceMh1Error> {
    if actual == expected {
        Ok(())
    } else {
        Err(invalid(format!(
            "{name} must be {expected:?}, got {actual:?}"
        )))
    }
}

fn require_f64(name: &str, actual: f64, expected: f64) -> Result<(), MaceMh1Error> {
    if actual.is_finite() && (actual - expected).abs() <= 1.0e-12 {
        Ok(())
    } else {
        Err(invalid(format!("{name} must be {expected}, got {actual}")))
    }
}

fn require_usize(name: &str, actual: usize, expected: usize) -> Result<(), MaceMh1Error> {
    if actual == expected {
        Ok(())
    } else {
        Err(invalid(format!("{name} must be {expected}, got {actual}")))
    }
}

fn require_str_slice(name: &str, actual: &[String], expected: &[&str]) -> Result<(), MaceMh1Error> {
    let actual_refs = actual.iter().map(String::as_str).collect::<Vec<_>>();
    if actual_refs == expected {
        Ok(())
    } else {
        Err(invalid(format!(
            "{name} must be {expected:?}, got {actual_refs:?}"
        )))
    }
}

fn require_u8_slice(name: &str, actual: &[u8], expected: &[u8]) -> Result<(), MaceMh1Error> {
    if actual == expected {
        Ok(())
    } else {
        Err(invalid(format!(
            "{name} must be {expected:?}, got {actual:?}"
        )))
    }
}

fn require_usize_slice(
    name: &str,
    actual: &[usize],
    expected: &[usize],
) -> Result<(), MaceMh1Error> {
    if actual == expected {
        Ok(())
    } else {
        Err(invalid(format!(
            "{name} must be {expected:?}, got {actual:?}"
        )))
    }
}

#[inline(always)]
fn mace_mh1_kahan_add(sum: &mut f64, compensation: &mut f64, term: f64) {
    let y = term - *compensation;
    let t = *sum + y;
    *compensation = (t - *sum) - y;
    *sum = t;
}

fn invalid(message: impl Into<String>) -> MaceMh1Error {
    MaceMh1Error::InvalidMetadata(message.into())
}

fn dtype_size_bytes(dtype: &str) -> Result<usize, MaceMh1Error> {
    match dtype {
        "bool" => Ok(std::mem::size_of::<u8>()),
        "f64" => Ok(std::mem::size_of::<f64>()),
        "i32" => Ok(std::mem::size_of::<i32>()),
        "i64" => Ok(std::mem::size_of::<i64>()),
        other => Err(invalid(format!(
            "unsupported MACE-MH-1 tensor dtype {other:?}"
        ))),
    }
}

fn validate_state_export_tensors(
    tensors: &[MaceMh1StateTensor],
    expected_tensor_count: usize,
) -> Result<(), MaceMh1Error> {
    require_usize("tensors.len", tensors.len(), expected_tensor_count)?;
    let mut seen = HashSet::new();
    for tensor in tensors {
        if tensor.name.trim().is_empty() {
            return Err(invalid("tensor.name must not be empty"));
        }
        if !seen.insert(tensor.name.as_str()) {
            return Err(invalid(format!("duplicate tensor name `{}`", tensor.name)));
        }
        require_eq("tensor.layout", &tensor.layout, "row-major")?;
        match tensor.dtype.as_str() {
            "bool" | "f64" | "i32" | "i64" => {}
            other => return Err(invalid(format!("unsupported exported dtype `{other}`"))),
        }
        match tensor.source_dtype.as_str() {
            "bool" | "f32" | "f64" | "i32" | "i64" => {}
            other => return Err(invalid(format!("unsupported source dtype `{other}`"))),
        }
        let shape_numel = tensor
            .shape
            .iter()
            .try_fold(1_usize, |acc, dim| acc.checked_mul(*dim))
            .ok_or_else(|| invalid("tensor.shape product overflows usize"))?;
        require_usize("tensor.shape_product", shape_numel, tensor.numel)?;
        let expected_bytes = tensor
            .numel
            .checked_mul(dtype_size_bytes(&tensor.dtype)?)
            .ok_or_else(|| invalid("tensor.byte_size overflows usize"))?;
        require_usize("tensor.byte_size", tensor.byte_size, expected_bytes)?;
        if tensor.path.trim().is_empty() {
            return Err(invalid("tensor.path must not be empty"));
        }
        if tensor.sha256.len() != 64 || !tensor.sha256.bytes().all(|byte| byte.is_ascii_hexdigit())
        {
            return Err(invalid("tensor.sha256 must be a 64-character hex digest"));
        }
    }
    Ok(())
}

fn validate_state_export_external_tensors(
    tensors: &[MaceMh1StateTensor],
    external_tensors: &BTreeMap<String, MaceMh1ExternalTensor>,
) -> Result<(), MaceMh1Error> {
    let exported_names = tensors
        .iter()
        .map(|tensor| tensor.name.as_str())
        .collect::<HashSet<_>>();
    for tensor in tensors {
        if !external_tensors.contains_key(&tensor.name) {
            return Err(invalid(format!(
                "missing external tensor `{}`",
                tensor.name
            )));
        }
    }
    for name in external_tensors.keys() {
        if !exported_names.contains(name.as_str()) {
            return Err(invalid(format!("unexpected external tensor `{name}`")));
        }
    }
    for tensor in tensors {
        let external = external_tensors
            .get(&tensor.name)
            .ok_or_else(|| invalid(format!("missing external tensor `{}`", tensor.name)))?;
        if external.shape != tensor.shape {
            return Err(invalid(format!(
                "tensor `{}` expected shape {:?}, got {:?}",
                tensor.name, tensor.shape, external.shape
            )));
        }
        let actual_dtype = external.values.dtype_name();
        if actual_dtype != tensor.dtype {
            return Err(invalid(format!(
                "tensor `{}` expected dtype {}, got {actual_dtype}",
                tensor.name, tensor.dtype
            )));
        }
        if external.values.len() != tensor.numel {
            return Err(invalid(format!(
                "tensor `{}` expected {} values, got {}",
                tensor.name,
                tensor.numel,
                external.values.len()
            )));
        }
    }
    Ok(())
}

