    fn tensor_numel(shape: &[usize]) -> usize {
        shape.iter().product()
    }

    fn state_tensor_spec(
        name: &str,
        dtype: &str,
        shape: &[usize],
        index: usize,
    ) -> serde_json::Value {
        let numel = tensor_numel(shape);
        let byte_size = numel * dtype_size_bytes(dtype).unwrap();
        serde_json::json!({
            "byte_size": byte_size,
            "dtype": dtype,
            "layout": "row-major",
            "name": name,
            "numel": numel,
            "path": format!("tensors/tensor_{index:05}.bin"),
            "sha256": "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
            "shape": shape,
            "source_dtype": dtype
        })
    }

    fn filler_state_tensor_spec(index: usize, path_index: usize) -> serde_json::Value {
        state_tensor_spec(&format!("state.{index:03}"), "f64", &[1], path_index)
    }

    fn state_tensor_specs() -> Vec<serde_json::Value> {
        let mut tensors = REQUIRED_RUNTIME_TENSORS
            .iter()
            .enumerate()
            .map(|(index, spec)| state_tensor_spec(spec.name, spec.dtype, spec.shape, index))
            .collect::<Vec<_>>();
        let filler_count = STATE_DICT_TENSOR_COUNT - tensors.len();
        for index in 0..filler_count {
            tensors.push(filler_state_tensor_spec(
                index,
                index + REQUIRED_RUNTIME_TENSORS.len(),
            ));
        }
        tensors
    }

    fn valid_state_json() -> String {
        let mut value: serde_json::Value = serde_json::from_str(&valid_metadata_json()).unwrap();
        value["schema_version"] = serde_json::json!("mace-mh1-state-dict-v1");
        value["runtime_status"] = serde_json::json!("state_export_only");
        value["tensors"] = serde_json::Value::Array(state_tensor_specs());
        serde_json::to_string(&value).unwrap()
    }

    fn external_tensor(dtype: &str, shape: &[usize], seed: usize) -> MaceMh1ExternalTensor {
        let numel = tensor_numel(shape);
        let values = match dtype {
            "f64" => MaceMh1ExternalTensorValues::F64(
                (0..numel)
                    .map(|offset| seed as f64 + offset as f64)
                    .collect(),
            ),
            "i32" => MaceMh1ExternalTensorValues::I32(
                (0..numel)
                    .map(|offset| seed as i32 + offset as i32)
                    .collect(),
            ),
            other => panic!("unsupported test dtype {other}"),
        };
        MaceMh1ExternalTensor {
            shape: shape.to_vec(),
            values,
        }
    }

    fn external_tensor_for_required_spec(
        spec: &RequiredRuntimeTensorSpec,
        seed: usize,
    ) -> MaceMh1ExternalTensor {
        match spec.name {
            "radial_embedding.distance_transform.q" => {
                return external_test_f64_tensor(spec.shape, vec![0.918_299_973_011_016_8]);
            }
            "radial_embedding.distance_transform.p" => {
                return external_test_f64_tensor(spec.shape, vec![4.579_100_131_988_525]);
            }
            "radial_embedding.distance_transform.a" => {
                return external_test_f64_tensor(spec.shape, vec![1.080_500_006_675_720_2]);
            }
            "radial_embedding.distance_transform.covalent_radii"
            | "pair_repulsion_fn.covalent_radii" => {
                return external_test_f64_tensor(spec.shape, test_covalent_radii());
            }
            "pair_repulsion_fn.c" => {
                return external_test_f64_tensor(
                    spec.shape,
                    vec![
                        0.181_752_746_105_194_1,
                        0.509_885_199_069_999_2,
                        0.280_233_155_607_866_3,
                        0.028_171_919_837_091_4,
                    ],
                );
            }
            "pair_repulsion_fn.p" => {
                return MaceMh1ExternalTensor {
                    shape: spec.shape.to_vec(),
                    values: MaceMh1ExternalTensorValues::I32(vec![6]),
                };
            }
            "pair_repulsion_fn.a_exp" => {
                return external_test_f64_tensor(spec.shape, vec![0.885_339_793_750_762_9]);
            }
            "pair_repulsion_fn.a_prefactor" => {
                return external_test_f64_tensor(spec.shape, vec![0.468_376_612_345_321]);
            }
            _ => {}
        }
        if spec.dtype == "f64"
            && (spec.name.starts_with("products.0.") || spec.name.starts_with("products.1."))
        {
            let numel = tensor_numel(spec.shape);
            let values = if spec.name.ends_with(".output_mask") {
                vec![1.0; numel]
            } else {
                (0..numel)
                    .map(|offset| {
                        let centered = ((seed + offset) % 17) as f64 - 8.0;
                        centered * 1.0e-6
                    })
                    .collect()
            };
            return MaceMh1ExternalTensor {
                shape: spec.shape.to_vec(),
                values: MaceMh1ExternalTensorValues::F64(values),
            };
        }
        external_tensor(spec.dtype, spec.shape, seed)
    }

    fn external_test_f64_tensor(shape: &[usize], values: Vec<f64>) -> MaceMh1ExternalTensor {
        assert_eq!(
            values.len(),
            tensor_numel(shape),
            "external test tensor numel"
        );
        MaceMh1ExternalTensor {
            shape: shape.to_vec(),
            values: MaceMh1ExternalTensorValues::F64(values),
        }
    }

    fn valid_external_tensors() -> BTreeMap<String, MaceMh1ExternalTensor> {
        let mut tensors = BTreeMap::new();
        for (index, spec) in REQUIRED_RUNTIME_TENSORS.iter().enumerate() {
            tensors.insert(
                spec.name.to_owned(),
                external_tensor_for_required_spec(spec, index),
            );
        }
        let filler_count = STATE_DICT_TENSOR_COUNT - REQUIRED_RUNTIME_TENSORS.len();
        for index in 0..filler_count {
            tensors.insert(
                format!("state.{index:03}"),
                external_tensor("f64", &[1], index + REQUIRED_RUNTIME_TENSORS.len()),
            );
        }
        tensors
    }

    #[test]
    fn runtime_state_builds_f32_cache_for_f64_tensors() {
        let mut tensors = BTreeMap::new();
        tensors.insert(
            "weights".to_owned(),
            external_test_f64_tensor(&[3], vec![1.25, -2.5, 3.75]),
        );
        tensors.insert(
            "index".to_owned(),
            MaceMh1ExternalTensor {
                shape: Vec::new(),
                values: MaceMh1ExternalTensorValues::I32(vec![7]),
            },
        );
        let runtime = MaceMh1RuntimeState::new(tensors);

        assert_eq!(
            runtime.f32_tensor("weights", &[3]).unwrap(),
            &[1.25_f32, -2.5, 3.75]
        );
        assert!(matches!(
            runtime.f32_scalar("weights"),
            Err(MaceMh1Error::RuntimeTensorShapeMismatch {
                name,
                expected,
                actual,
            }) if name == "weights" && expected.is_empty() && actual == vec![3]
        ));
        assert!(matches!(
            runtime.f32_tensor("index", &[]),
            Err(MaceMh1Error::RuntimeTensorDtypeMismatch { .. })
        ));
    }

    #[test]
    fn torch_linear_rows_f32_matches_f64_reference() {
        let input_f32 = vec![0.25_f32, -0.5, 1.0, 1.5, -2.0, 0.75];
        let weight_f32 = vec![0.5_f32, -0.25, 0.125, -0.75, 0.375, 0.25];
        let bias_f32 = vec![0.1_f32, -0.2];

        let actual = torch_linear_rows_from_parts_f32(
            &input_f32,
            &weight_f32,
            &bias_f32,
            3,
            2,
            "test.linear",
        )
        .unwrap();
        let expected = torch_linear_rows_from_parts(
            &input_f32
                .iter()
                .map(|&value| f64::from(value))
                .collect::<Vec<_>>(),
            &weight_f32
                .iter()
                .map(|&value| f64::from(value))
                .collect::<Vec<_>>(),
            &bias_f32
                .iter()
                .map(|&value| f64::from(value))
                .collect::<Vec<_>>(),
            3,
            2,
            "test.linear",
        )
        .unwrap();

        for (index, (&actual, &expected)) in actual.iter().zip(&expected).enumerate() {
            let delta = (f64::from(actual) - expected).abs();
            assert!(
                delta <= 2.0e-7,
                "f32 dense output[{index}] expected {expected:.8e}, got {actual:.8e}, delta {delta:.3e}"
            );
        }

        let mut tensors = BTreeMap::new();
        tensors.insert(
            "dense.weight".to_owned(),
            external_test_f64_tensor(
                &[2, 3],
                weight_f32.iter().map(|&value| f64::from(value)).collect(),
            ),
        );
        tensors.insert(
            "dense.bias".to_owned(),
            external_test_f64_tensor(
                &[2],
                bias_f32.iter().map(|&value| f64::from(value)).collect(),
            ),
        );
        let runtime = MaceMh1RuntimeState::new(tensors);
        let cached = runtime
            .torch_linear_rows_f32("dense", &input_f32, 3, 2)
            .unwrap();
        assert_eq!(cached, actual);
    }

    #[test]
    fn layer_norm_and_silu_f32_match_f64_reference() {
        let input_f32 = vec![0.25_f32, -0.5, 1.0, 1.5, -2.0, 0.75];
        let weight_f32 = vec![1.1_f32, 0.9, -0.7];
        let bias_f32 = vec![0.05_f32, -0.1, 0.2];

        let actual = layer_norm_rows_from_parts_f32(
            &input_f32,
            &weight_f32,
            &bias_f32,
            3,
            MACE_MH1_LAYER_NORM_EPS as f32,
            "test.norm",
        )
        .unwrap();
        let input_f64 = input_f32
            .iter()
            .map(|&value| f64::from(value))
            .collect::<Vec<_>>();
        let weight_f64 = weight_f32
            .iter()
            .map(|&value| f64::from(value))
            .collect::<Vec<_>>();
        let bias_f64 = bias_f32
            .iter()
            .map(|&value| f64::from(value))
            .collect::<Vec<_>>();
        let expected = layer_norm_rows_from_parts(
            &input_f64,
            &weight_f64,
            &bias_f64,
            3,
            MACE_MH1_LAYER_NORM_EPS,
            "test.norm",
        )
        .unwrap();
        for (index, (&actual, &expected)) in actual.iter().zip(&expected).enumerate() {
            let delta = (f64::from(actual) - expected).abs();
            assert!(
                delta <= 2.0e-6,
                "f32 layer norm output[{index}] expected {expected:.8e}, got {actual:.8e}, delta {delta:.3e}"
            );
        }

        let mut silu_actual = actual.clone();
        apply_silu_f32(&mut silu_actual);
        let mut silu_expected = expected.clone();
        apply_silu(&mut silu_expected);
        for (index, (&actual, &expected)) in silu_actual.iter().zip(&silu_expected).enumerate() {
            let delta = (f64::from(actual) - expected).abs();
            assert!(
                delta <= 2.0e-6,
                "f32 SiLU output[{index}] expected {expected:.8e}, got {actual:.8e}, delta {delta:.3e}"
            );
        }

        let mut tensors = BTreeMap::new();
        tensors.insert(
            "norm.weight".to_owned(),
            external_test_f64_tensor(&[3], weight_f64),
        );
        tensors.insert(
            "norm.bias".to_owned(),
            external_test_f64_tensor(&[3], bias_f64),
        );
        let runtime = MaceMh1RuntimeState::new(tensors);
        let cached = runtime.layer_norm_rows_f32("norm", &input_f32, 3).unwrap();
        assert_eq!(cached, actual);
    }

    #[test]
    fn silu_sigmoid_cache_helpers_match_direct_paths() {
        let values = vec![-20.0, -3.5, -0.125, 0.0, 0.25, 4.0, 18.0];
        let (cached_silu, sigmoid_cache) = silu_with_sigmoid_cache(&values);
        let mut expected_silu = values.clone();
        apply_silu(&mut expected_silu);
        assert_slices_close_abs(
            "f64 SiLU cache forward",
            &cached_silu,
            &expected_silu,
            1.0e-14,
        );
        for (index, (&value, &sigmoid_value)) in values.iter().zip(&sigmoid_cache).enumerate() {
            let expected = silu_derivative(value);
            let actual = silu_derivative_from_sigmoid(value, sigmoid_value);
            assert!(
                (actual - expected).abs() <= 1.0e-14,
                "f64 SiLU derivative cache[{index}] expected {expected:.16e}, got {actual:.16e}"
            );
        }

        let values_f32 = values.iter().map(|&value| value as f32).collect::<Vec<_>>();
        let (cached_silu_f32, sigmoid_cache_f32) = silu_with_sigmoid_cache_f32(&values_f32);
        let mut expected_silu_f32 = values_f32.clone();
        apply_silu_f32(&mut expected_silu_f32);
        let to_f64 = |values: &[f32]| values.iter().map(|&v| f64::from(v)).collect::<Vec<_>>();
        assert_slices_close_abs(
            "f32 SiLU cache forward",
            &to_f64(&cached_silu_f32),
            &to_f64(&expected_silu_f32),
            2.0e-6,
        );
        for (index, (&value, &sigmoid_value)) in
            values_f32.iter().zip(&sigmoid_cache_f32).enumerate()
        {
            let expected = silu_derivative_f32(value);
            let actual = silu_derivative_from_sigmoid_f32(value, sigmoid_value);
            assert!(
                (actual - expected).abs() <= 2.0e-6,
                "f32 SiLU derivative cache[{index}] expected {expected:.8e}, got {actual:.8e}"
            );
        }

        let rows = 3;
        let stride = 6;
        let width = 4;
        let strided = (0..rows * stride)
            .map(|index| ((index % 17) as f64 - 8.0) * 0.375)
            .collect::<Vec<_>>();
        let mut actual = vec![0.0; rows * width];
        fill_strided_sigmoid_cache_f64(&strided, rows, stride, width, &mut actual);
        let mut expected = vec![0.0; rows * width];
        for row in 0..rows {
            for col in 0..width {
                expected[row * width + col] = sigmoid(strided[row * stride + col]);
            }
        }
        assert_slices_close_abs("f64 strided sigmoid cache", &actual, &expected, 1.0e-14);
    }

    #[test]
    fn equivariant_nonlin_sigmoid_cache_matches_uncached_forward_and_vjp() {
        let rows = 1;
        let input = (0..rows * MACE_MH1_INTERACTION0_NONLIN_DIM)
            .map(|index| ((index % 29) as f64 - 14.0) * 0.03125)
            .collect::<Vec<_>>();
        let output_mask = (0..MACE_MH1_INTERACTION0_OUT_DIM
            - MACE_MH1_INTERACTION0_RESHAPED_CHANNELS)
            .map(|index| {
                if index % 11 == 0 {
                    0.25
                } else if index % 17 == 0 {
                    0.0
                } else {
                    1.0
                }
            })
            .collect::<Vec<_>>();
        let expected =
            mace_mh1_interaction_equivariant_nonlin(&input, &output_mask, "test.nonlin").unwrap();
        let (actual, sigmoid_cache) = mace_mh1_interaction_equivariant_nonlin_with_sigmoid_cache(
            &input,
            &output_mask,
            "test.nonlin.cached",
        )
        .unwrap();
        assert_slices_close_abs(
            "cached equivariant nonlin forward",
            &actual,
            &expected,
            1.0e-14,
        );

        let bar_output = (0..rows * MACE_MH1_INTERACTION0_OUT_DIM)
            .map(|index| ((index % 31) as f64 - 15.0) * 0.0078125)
            .collect::<Vec<_>>();
        let mut expected_bar = vec![0.0; input.len()];
        mace_mh1_interaction_equivariant_nonlin_vjp_input(
            &input,
            &output_mask,
            "test.nonlin.vjp",
            &bar_output,
            &mut expected_bar,
        )
        .unwrap();
        let mut actual_bar = vec![0.0; input.len()];
        mace_mh1_interaction_equivariant_nonlin_vjp_input_with_sigmoid_cache(
            &input,
            &output_mask,
            "test.nonlin.cached_vjp",
            &bar_output,
            &mut actual_bar,
            Some(&sigmoid_cache),
        )
        .unwrap();
        assert_slices_close_abs(
            "cached equivariant nonlin VJP",
            &actual_bar,
            &expected_bar,
            1.0e-14,
        );

        let mut direction = vec![0.0; input.len()];
        for (index, value) in [
            (3, 0.5),
            (271, -0.25),
            (512 + 7, 0.375),
            (2048 + 11, -0.125),
            (1024 + 13, 0.3125),
            (3584 + 17, -0.1875),
            (1536 + 19, 0.21875),
            (6144 + 23, -0.15625),
        ] {
            direction[index] = value;
        }
        let objective = |probe: &[f64]| -> f64 {
            mace_mh1_interaction_equivariant_nonlin(probe, &output_mask, "test.nonlin.fd")
                .unwrap()
                .iter()
                .zip(&bar_output)
                .map(|(&value, &bar)| value * bar)
                .sum::<f64>()
        };
        let epsilon = 1.0e-6;
        let mut plus = input.clone();
        let mut minus = input.clone();
        for ((plus_value, minus_value), &direction_value) in
            plus.iter_mut().zip(&mut minus).zip(&direction)
        {
            *plus_value += epsilon * direction_value;
            *minus_value -= epsilon * direction_value;
        }
        let finite_difference = (objective(&plus) - objective(&minus)) / (2.0 * epsilon);
        let adjoint = actual_bar
            .iter()
            .zip(&direction)
            .map(|(&bar, &direction_value)| bar * direction_value)
            .sum::<f64>();
        assert!(
            (adjoint - finite_difference).abs() <= 2.0e-7,
            "cached equivariant nonlin VJP directional FD expected {finite_difference:.12e}, got {adjoint:.12e}"
        );
    }

    #[test]
    fn edge_mlp_f32_promoted_boundaries_match_f64_reference() {
        let runtime = edge_mlp_test_runtime();
        let node_count = 3;
        let edge_count = 3;
        let edge_input = MaceMh1EdgeInputBoundary {
            edge_count,
            edge_src: vec![0, 1, 2],
            edge_dst: vec![1, 2, 0],
            edge_vectors: vec![[0.0, 0.0, 0.0]; edge_count],
            edge_distances: vec![1.0, 1.5, 2.0],
            edge_src_atomic_numbers: vec![1, 6, 8],
            edge_dst_atomic_numbers: vec![6, 8, 1],
            edge_attrs: Vec::new(),
            edge_feats: (0..edge_count * MACE_MH1_NUM_BESSEL)
                .map(|index| ((index % 17) as f64 - 8.0) * 1.25e-2)
                .collect(),
            edge_cutoff: vec![0.25, 0.75, 1.0],
            pair_node_energy: vec![0.0; node_count],
        };
        let source_embedding = (0..node_count * MACE_MH1_NODE_CHANNELS)
            .map(|index| ((index % 31) as f64 - 15.0) * 1.0e-3)
            .collect::<Vec<_>>();
        let target_embedding = (0..node_count * MACE_MH1_NODE_CHANNELS)
            .map(|index| ((index % 29) as f64 - 14.0) * 1.2e-3)
            .collect::<Vec<_>>();

        let interaction0 = MaceMh1Interaction0InputBoundary {
            source_embedding: source_embedding.clone(),
            target_embedding: target_embedding.clone(),
            linear_up: Vec::new(),
            skip_connection: Vec::new(),
            forward_cache_f32: None,
        };
        let interaction0_f64 = runtime
            .interaction0_edge_mlp_boundary_with_forward_cache(&edge_input, &interaction0, false)
            .unwrap();
        let interaction0_f32 = runtime
            .interaction0_edge_mlp_boundary_f32_promoted(&edge_input, &interaction0)
            .unwrap();
        assert_slices_close_abs(
            "interaction0 f32-promoted augmented",
            &interaction0_f32.augmented_edge_feats,
            &interaction0_f64.augmented_edge_feats,
            1.0e-8,
        );
        assert_slices_close_abs(
            "interaction0 f32-promoted conv_tp_weights",
            &interaction0_f32.conv_tp_weights,
            &interaction0_f64.conv_tp_weights,
            5.0e-6,
        );
        assert_slices_close_abs(
            "interaction0 f32-promoted edge_density",
            &interaction0_f32.edge_density,
            &interaction0_f64.edge_density,
            5.0e-6,
        );

        let interaction1 = MaceMh1Interaction1InputBoundary {
            source_embedding,
            target_embedding,
            linear_up: Vec::new(),
            skip_connection: Vec::new(),
            forward_cache_f32: None,
        };
        let interaction1_f64 = runtime
            .interaction1_edge_mlp_boundary_with_forward_cache(&edge_input, &interaction1, false)
            .unwrap();
        let interaction1_f32 = runtime
            .interaction1_edge_mlp_boundary_f32_promoted(&edge_input, &interaction1)
            .unwrap();
        assert_slices_close_abs(
            "interaction1 f32-promoted augmented",
            &interaction1_f32.augmented_edge_feats,
            &interaction1_f64.augmented_edge_feats,
            1.0e-8,
        );
        assert_slices_close_abs(
            "interaction1 f32-promoted conv_tp_weights",
            &interaction1_f32.conv_tp_weights,
            &interaction1_f64.conv_tp_weights,
            5.0e-6,
        );
        assert_slices_close_abs(
            "interaction1 f32-promoted edge_density",
            &interaction1_f32.edge_density,
            &interaction1_f64.edge_density,
            5.0e-6,
        );
    }

    #[test]
    fn edge_mlp_layer_vjp_f32_bridge_handles_zero_cutoff_edges() {
        // Regression test for the FP32 force bridge with an edge at distance >= r_max.
        //
        // On the production FP32 route the edge-MLP boundary is built with
        // `materialize_f64_sidecars = false`, which zeroes `augmented_edge_feats`
        // whenever a forward cache is captured. When an edge's cutoff is exactly 0
        // (distance >= r_max), the bridge VJP must recover the pre-cutoff Conv-TP
        // weights / density from the forward cache rather than re-running the edge
        // MLP on the (zeroed) augmented features. The result must therefore be
        // independent of whether the f64 sidecars were materialized.
        let runtime = edge_mlp_test_runtime();
        let node_count = 3;
        let edge_count = 3;
        let edge_input = MaceMh1EdgeInputBoundary {
            edge_count,
            edge_src: vec![0, 1, 2],
            edge_dst: vec![1, 2, 0],
            edge_vectors: vec![[0.0, 0.0, 0.0]; edge_count],
            edge_distances: vec![1.0, 6.0, 2.0],
            edge_src_atomic_numbers: vec![1, 6, 8],
            edge_dst_atomic_numbers: vec![6, 8, 1],
            edge_attrs: Vec::new(),
            edge_feats: (0..edge_count * MACE_MH1_NUM_BESSEL)
                .map(|index| ((index % 17) as f64 - 8.0) * 1.25e-2)
                .collect(),
            // Middle edge is beyond r_max -> cutoff exactly 0; the others are inside.
            edge_cutoff: vec![0.6, 0.0, 1.0],
            pair_node_energy: vec![0.0; node_count],
        };
        assert!(
            edge_input.edge_cutoff.contains(&0.0),
            "test must exercise a zero-cutoff edge"
        );
        let source_embedding = (0..node_count * MACE_MH1_NODE_CHANNELS)
            .map(|index| ((index % 31) as f64 - 15.0) * 1.0e-3)
            .collect::<Vec<_>>();
        let target_embedding = (0..node_count * MACE_MH1_NODE_CHANNELS)
            .map(|index| ((index % 29) as f64 - 14.0) * 1.2e-3)
            .collect::<Vec<_>>();
        let interaction0 = MaceMh1Interaction0InputBoundary {
            source_embedding,
            target_embedding,
            linear_up: Vec::new(),
            skip_connection: Vec::new(),
            forward_cache_f32: None,
        };

        // Production-style boundary: f32 forward cache populated. Depending on
        // the ConvTP output mask, the f64 sidecars may still be materialized for
        // fallback shape compatibility, so this test compares behavior rather
        // than requiring a particular sidecar storage choice.
        let boundary_zeroed = runtime
            .interaction0_edge_mlp_boundary_f32_promoted_with_sidecars(
                &edge_input,
                &interaction0,
                false,
            )
            .unwrap();
        assert!(
            boundary_zeroed.forward_cache_f32.is_some(),
            "small input must capture the f32 forward cache"
        );
        // Reference boundary: real f64 sidecars (augmented features populated).
        let boundary_real = runtime
            .interaction0_edge_mlp_boundary_f32_promoted_with_sidecars(
                &edge_input,
                &interaction0,
                true,
            )
            .unwrap();

        let input_dim = MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM;
        let hidden_dim = MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM;
        let tp_weight_dim = MACE_MH1_INTERACTION0_TP_WEIGHT_DIM;
        let bar_cutoff_conv_tp_weights = (0..edge_count * tp_weight_dim)
            .map(|index| ((index % 13) as f32 - 6.0) * 1.0e-2)
            .collect::<Vec<_>>();
        let bar_cutoff_edge_density = (0..edge_count)
            .map(|edge| (edge as f32 + 1.0) * 0.5)
            .collect::<Vec<_>>();

        let run_bridge = |boundary: &MaceMh1Interaction0EdgeMlpBoundary| {
            let mut bar_edge_cutoff = vec![0.0_f32; edge_count];
            let mut bar_augmented = vec![0.0_f32; edge_count * input_dim];
            runtime
                .edge_mlp_layer_vjp_f32_bridge(
                    "interactions.0",
                    input_dim,
                    hidden_dim,
                    tp_weight_dim,
                    &edge_input,
                    &boundary.augmented_edge_feats,
                    &boundary.conv_tp_weights,
                    &boundary.edge_density,
                    boundary.forward_cache_f32.as_deref(),
                    &bar_cutoff_conv_tp_weights,
                    &bar_cutoff_edge_density,
                    &mut bar_edge_cutoff,
                    &mut bar_augmented,
                )
                .unwrap();
            (bar_edge_cutoff, bar_augmented)
        };

        let (cutoff_zeroed, augmented_zeroed) = run_bridge(&boundary_zeroed);
        let (cutoff_real, augmented_real) = run_bridge(&boundary_real);
        let to_f64 = |values: &[f32]| values.iter().map(|&v| f64::from(v)).collect::<Vec<_>>();

        // The production (zeroed-sidecar) bridge must match the real-sidecar bridge.
        // Before the fix, bar_edge_cutoff for the non-zero-cutoff edges was computed
        // from an MLP-of-zeros and diverged far beyond fp32 rounding.
        assert_slices_close_abs(
            "f32 bridge bar_edge_cutoff with zero-cutoff edge",
            &to_f64(&cutoff_zeroed),
            &to_f64(&cutoff_real),
            1.0e-5,
        );
        assert_slices_close_abs(
            "f32 bridge bar_augmented with zero-cutoff edge",
            &to_f64(&augmented_zeroed),
            &to_f64(&augmented_real),
            1.0e-5,
        );
    }

    #[test]
    fn edge_mlp_layer_vjp_f32_bridge_zero_cutoff_matches_finite_difference() {
        let runtime = edge_mlp_test_runtime();
        let node_count = 3;
        let edge_count = 3;
        let edge_input = MaceMh1EdgeInputBoundary {
            edge_count,
            edge_src: vec![0, 1, 2],
            edge_dst: vec![1, 2, 0],
            edge_vectors: vec![[0.0, 0.0, 0.0]; edge_count],
            edge_distances: vec![1.0, 6.0, 2.0],
            edge_src_atomic_numbers: vec![1, 6, 8],
            edge_dst_atomic_numbers: vec![6, 8, 1],
            edge_attrs: Vec::new(),
            edge_feats: (0..edge_count * MACE_MH1_NUM_BESSEL)
                .map(|index| ((index % 17) as f64 - 8.0) * 1.25e-2)
                .collect(),
            edge_cutoff: vec![0.6, 0.0, 1.0],
            pair_node_energy: vec![0.0; node_count],
        };
        let source_embedding = (0..node_count * MACE_MH1_NODE_CHANNELS)
            .map(|index| ((index % 31) as f64 - 15.0) * 1.0e-3)
            .collect::<Vec<_>>();
        let target_embedding = (0..node_count * MACE_MH1_NODE_CHANNELS)
            .map(|index| ((index % 29) as f64 - 14.0) * 1.2e-3)
            .collect::<Vec<_>>();
        let interaction0 = MaceMh1Interaction0InputBoundary {
            source_embedding,
            target_embedding,
            linear_up: Vec::new(),
            skip_connection: Vec::new(),
            forward_cache_f32: None,
        };
        let boundary = runtime
            .interaction0_edge_mlp_boundary_f32_promoted_with_sidecars(
                &edge_input,
                &interaction0,
                false,
            )
            .unwrap();
        assert!(boundary.forward_cache_f32.is_some());

        let input_dim = MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM;
        let hidden_dim = MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM;
        let tp_weight_dim = MACE_MH1_INTERACTION0_TP_WEIGHT_DIM;
        let bar_cutoff_conv_tp_weights = (0..edge_count * tp_weight_dim)
            .map(|index| ((index % 13) as f32 - 6.0) * 1.0e-2)
            .collect::<Vec<_>>();
        let bar_cutoff_edge_density = (0..edge_count)
            .map(|edge| (edge as f32 + 1.0) * 0.5)
            .collect::<Vec<_>>();
        let mut bar_edge_cutoff = vec![0.0_f32; edge_count];
        let mut bar_augmented = vec![0.0_f32; edge_count * input_dim];
        runtime
            .edge_mlp_layer_vjp_f32_bridge(
                "interactions.0",
                input_dim,
                hidden_dim,
                tp_weight_dim,
                &edge_input,
                &boundary.augmented_edge_feats,
                &boundary.conv_tp_weights,
                &boundary.edge_density,
                boundary.forward_cache_f32.as_deref(),
                &bar_cutoff_conv_tp_weights,
                &bar_cutoff_edge_density,
                &mut bar_edge_cutoff,
                &mut bar_augmented,
            )
            .unwrap();
        let mut bar_edge_feats = vec![0.0_f32; edge_input.edge_feats.len()];
        decompose_edge_mlp_augmented_bars_f32_radial_only(
            "interactions.0.edge_mlp.zero_cutoff_fd",
            input_dim,
            &edge_input,
            &bar_augmented,
            &mut bar_edge_feats,
        )
        .unwrap();

        let objective = |probe: &MaceMh1EdgeInputBoundary| -> f64 {
            let boundary = runtime
                .interaction0_edge_mlp_boundary_f32_promoted_with_sidecars(
                    probe,
                    &interaction0,
                    false,
                )
                .unwrap();
            let cache = boundary.forward_cache_f32.as_deref().unwrap();
            cache
                .cutoff_conv_tp_weights
                .iter()
                .zip(&bar_cutoff_conv_tp_weights)
                .map(|(&value, &bar)| f64::from(value * bar))
                .sum::<f64>()
                + cache
                    .cutoff_edge_density
                    .iter()
                    .zip(&bar_cutoff_edge_density)
                    .map(|(&value, &bar)| f64::from(value * bar))
                    .sum::<f64>()
        };
        let epsilon = 1.0e-3;
        let fd_tolerance = 1.0e-6;
        for index in [0, 7, MACE_MH1_NUM_BESSEL, MACE_MH1_NUM_BESSEL + 5] {
            let mut plus = edge_input.clone();
            plus.edge_feats[index] += epsilon;
            let mut minus = edge_input.clone();
            minus.edge_feats[index] -= epsilon;
            let finite_difference = (objective(&plus) - objective(&minus)) / (2.0 * epsilon);
            let actual = f64::from(bar_edge_feats[index]);
            assert!(
                (actual - finite_difference).abs() <= fd_tolerance,
                "f32 bridge zero-cutoff edge_feats[{index}] expected {finite_difference:.8e}, got {actual:.8e}"
            );
        }
        for (index, &actual_f32) in bar_edge_cutoff.iter().enumerate().take(edge_count) {
            if edge_input.edge_cutoff[index] == 0.0 {
                // The force bridge treats a cutoff == 0 row as outside the radial
                // support and skips the synthetic cutoff-scalar derivative. The
                // physical distance derivative is zero beyond r_max, while a
                // central difference around the standalone cutoff scalar would
                // probe an invalid negative-cutoff scaling.
                assert!(
                    actual_f32 == 0.0,
                    "f32 bridge zero-cutoff edge_cutoff[{index}] must remain exactly zero, got {actual_f32:.8e}"
                );
                continue;
            }
            let mut plus = edge_input.clone();
            plus.edge_cutoff[index] += epsilon;
            let mut minus = edge_input.clone();
            minus.edge_cutoff[index] -= epsilon;
            let finite_difference = (objective(&plus) - objective(&minus)) / (2.0 * epsilon);
            let actual = f64::from(actual_f32);
            assert!(
                (actual - finite_difference).abs() <= fd_tolerance,
                "f32 bridge zero-cutoff edge_cutoff[{index}] expected {finite_difference:.8e}, got {actual:.8e}"
            );
        }
    }

    #[cfg(feature = "parallel")]
    #[test]
    fn radial_cached_f32_bridge_handles_zero_cutoff_edges() {
        // The radial-cached f32 bridge recovers pre-cutoff Conv-TP weights / density
        // by dividing the cached post-cutoff values by the edge cutoff. A cutoff == 0
        // edge (distance >= r_max) must be skipped to avoid a 0/0 -> NaN, and the
        // result must match the general bridge (which the dispatcher routes to when a
        // zero-cutoff edge is present) within fp32 rounding.
        let runtime = edge_mlp_test_runtime();
        let node_count = 3;
        let edge_count = 3;
        let edge_input = MaceMh1EdgeInputBoundary {
            edge_count,
            edge_src: vec![0, 1, 2],
            edge_dst: vec![1, 2, 0],
            edge_vectors: vec![[0.0, 0.0, 0.0]; edge_count],
            edge_distances: vec![1.0, 6.0, 2.0],
            edge_src_atomic_numbers: vec![1, 6, 8],
            edge_dst_atomic_numbers: vec![6, 8, 1],
            edge_attrs: Vec::new(),
            edge_feats: (0..edge_count * MACE_MH1_NUM_BESSEL)
                .map(|index| ((index % 17) as f64 - 8.0) * 1.25e-2)
                .collect(),
            // Middle edge is beyond r_max -> cutoff exactly 0; the others are inside.
            edge_cutoff: vec![0.6, 0.0, 1.0],
            pair_node_energy: vec![0.0; node_count],
        };
        let source_embedding = (0..node_count * MACE_MH1_NODE_CHANNELS)
            .map(|index| ((index % 31) as f64 - 15.0) * 1.0e-3)
            .collect::<Vec<_>>();
        let target_embedding = (0..node_count * MACE_MH1_NODE_CHANNELS)
            .map(|index| ((index % 29) as f64 - 14.0) * 1.2e-3)
            .collect::<Vec<_>>();
        let interaction0 = MaceMh1Interaction0InputBoundary {
            source_embedding,
            target_embedding,
            linear_up: Vec::new(),
            skip_connection: Vec::new(),
            forward_cache_f32: None,
        };

        // Real f64 sidecars + populated f32 forward cache (captured regardless of
        // sidecar materialization for small inputs).
        let boundary = runtime
            .interaction0_edge_mlp_boundary_f32_promoted_with_sidecars(
                &edge_input,
                &interaction0,
                true,
            )
            .unwrap();
        assert!(
            boundary.forward_cache_f32.is_some(),
            "small input must capture the f32 forward cache"
        );
        let cache = boundary.forward_cache_f32.as_deref().unwrap();

        let make_dims = || MaceMh1EdgeMlpDims {
            input_dim: MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
            hidden_dim: MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM,
            tp_weight_dim: MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
        };
        let bar_cutoff_conv_tp_weights = (0..edge_count * MACE_MH1_INTERACTION0_TP_WEIGHT_DIM)
            .map(|index| ((index % 13) as f32 - 6.0) * 1.0e-2)
            .collect::<Vec<_>>();
        let bar_cutoff_edge_density = (0..edge_count)
            .map(|edge| (edge as f32 + 1.0) * 0.5)
            .collect::<Vec<_>>();

        // Directly exercise the radial-cached path with a zero-cutoff edge present.
        let radial = runtime
            .edge_mlp_layer_vjp_and_decompose_f32_bridge_radial_cached(
                "interactions.0",
                make_dims(),
                &edge_input,
                cache,
                &bar_cutoff_conv_tp_weights,
                &bar_cutoff_edge_density,
            )
            .unwrap();
        assert!(
            radial
                .bar_edge_feats
                .iter()
                .chain(radial.bar_edge_cutoff.iter())
                .all(|v| v.is_finite()),
            "radial-cached zero-cutoff bridge must not produce NaN/inf"
        );

        // Reference: the dispatcher routes a zero-cutoff input to the general bridge.
        let reference = runtime
            .edge_mlp_layer_vjp_and_decompose_f32_bridge(
                "interactions.0",
                make_dims(),
                &edge_input,
                &boundary.augmented_edge_feats,
                &boundary.conv_tp_weights,
                &boundary.edge_density,
                boundary.forward_cache_f32.as_deref(),
                &bar_cutoff_conv_tp_weights,
                &bar_cutoff_edge_density,
            )
            .unwrap();

        let to_f64 = |values: &[f32]| values.iter().map(|&v| f64::from(v)).collect::<Vec<_>>();
        assert_slices_close_abs(
            "radial-cached vs general bridge bar_edge_feats (zero cutoff)",
            &to_f64(&radial.bar_edge_feats),
            &to_f64(&reference.bar_edge_feats),
            1.0e-4,
        );
        assert_slices_close_abs(
            "radial-cached vs general bridge bar_edge_cutoff (zero cutoff)",
            &to_f64(&radial.bar_edge_cutoff),
            &to_f64(&reference.bar_edge_cutoff),
            1.0e-4,
        );
    }

