    fn assert_projected_linear0_all_one_mask_matches_materialized_sidecars() {
        let runtime = edge_mlp_test_runtime_with_interaction0_all_one_conv_tp_mask();
        let node_count = 5;
        let edge_count = 7;
        let edge_input = MaceMh1EdgeInputBoundary {
            edge_count,
            edge_src: (0..edge_count).map(|edge| edge % node_count).collect(),
            edge_dst: (0..edge_count)
                .map(|edge| (edge * 3 + 1) % node_count)
                .collect(),
            edge_vectors: vec![[0.0, 0.0, 0.0]; edge_count],
            edge_distances: (0..edge_count)
                .map(|edge| 0.85 + (edge % 5) as f64 * 0.21)
                .collect(),
            edge_src_atomic_numbers: (0..edge_count)
                .map(|edge| if edge % 2 == 0 { 6 } else { 8 })
                .collect(),
            edge_dst_atomic_numbers: (0..edge_count)
                .map(|edge| if edge % 3 == 0 { 1 } else { 6 })
                .collect(),
            edge_attrs: Vec::new(),
            edge_feats: (0..edge_count * MACE_MH1_NUM_BESSEL)
                .map(|index| ((index % 23) as f64 - 11.0) * 7.5e-3)
                .collect(),
            edge_cutoff: (0..edge_count)
                .map(|edge| 0.4 + (edge % 7) as f64 * 0.055)
                .collect(),
            pair_node_energy: vec![0.0; node_count],
        };
        let source_embedding = (0..node_count * MACE_MH1_NODE_CHANNELS)
            .map(|index| ((index % 37) as f64 - 18.0) * 1.1e-4)
            .collect::<Vec<_>>();
        let target_embedding = (0..node_count * MACE_MH1_NODE_CHANNELS)
            .map(|index| ((index % 41) as f64 - 20.0) * 9.0e-5)
            .collect::<Vec<_>>();
        let interaction0 = MaceMh1Interaction0InputBoundary {
            source_embedding,
            target_embedding,
            linear_up: Vec::new(),
            skip_connection: Vec::new(),
            forward_cache_f32: None,
        };

        let projected = runtime
            .interaction0_edge_mlp_boundary_f32_promoted_with_sidecars(
                &edge_input,
                &interaction0,
                false,
            )
            .unwrap();
        assert!(
            projected.forward_cache_f32.is_some(),
            "projected all-one-mask path must capture the f32 forward cache"
        );
        assert!(
            projected.augmented_edge_feats.is_empty()
                && projected.conv_tp_weights.is_empty()
                && projected.edge_density.is_empty(),
            "projected all-one-mask path should not materialize f64 sidecars"
        );

        let reference = runtime
            .interaction0_edge_mlp_boundary_f32_promoted_with_sidecars(
                &edge_input,
                &interaction0,
                true,
            )
            .unwrap();
        assert_eq!(
            reference.conv_tp_weights.len(),
            edge_count * MACE_MH1_INTERACTION0_TP_WEIGHT_DIM
        );
        assert_eq!(reference.edge_density.len(), edge_count);

        let cache = projected.forward_cache_f32.as_deref().unwrap();
        let to_f64 = |values: &[f32]| values.iter().map(|&v| f64::from(v)).collect::<Vec<_>>();
        assert_slices_close_abs(
            "projected linear0 all-one-mask cutoff Conv-TP weights",
            &to_f64(&cache.cutoff_conv_tp_weights),
            &reference.conv_tp_weights,
            5.0e-5,
        );
        assert_slices_close_abs(
            "projected linear0 all-one-mask cutoff edge density",
            &to_f64(&cache.cutoff_edge_density),
            &reference.edge_density,
            5.0e-5,
        );
        let edge_feats_f32 = edge_input
            .edge_feats
            .iter()
            .map(|&value| value as f32)
            .collect::<Vec<_>>();
        let source_embedding_f32 = interaction0
            .source_embedding
            .iter()
            .map(|&value| value as f32)
            .collect::<Vec<_>>();
        let target_embedding_f32 = interaction0
            .target_embedding
            .iter()
            .map(|&value| value as f32)
            .collect::<Vec<_>>();
        let direct_projected_linear0 = runtime
            .edge_mlp_projected_linear0_f32(
                "interactions.0.conv_tp_weights.net",
                &edge_input,
                &edge_feats_f32,
                &source_embedding_f32,
                &target_embedding_f32,
                node_count,
                node_count,
                MaceMh1EdgeMlpDims {
                    input_dim: MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM,
                    hidden_dim: MACE_MH1_INTERACTION0_EDGE_MLP_HIDDEN_DIM,
                    tp_weight_dim: MACE_MH1_INTERACTION0_TP_WEIGHT_DIM,
                },
            )
            .unwrap();
        assert_slices_close_abs(
            "projected linear0 cache rows",
            &to_f64(&cache.conv_tp_weights.linear0),
            &to_f64(&direct_projected_linear0),
            0.0,
        );
    }

