    fn assert_rows_close(actual: &[Vec<f64>], expected: &[Vec<f64>], tolerance: f64, name: &str) {
        assert_eq!(actual.len(), expected.len(), "{name} row count");
        for (row, (actual_row, expected_row)) in actual.iter().zip(expected).enumerate() {
            assert_eq!(
                actual_row.len(),
                expected_row.len(),
                "{name} row {row} width"
            );
            for (col, (&actual_value, &expected_value)) in
                actual_row.iter().zip(expected_row).enumerate()
            {
                let delta = (actual_value - expected_value).abs();
                assert!(
                    delta <= tolerance,
                    "{name}[{row}][{col}] expected {expected_value:.16e}, got {actual_value:.16e}, delta {delta:.3e}"
                );
            }
        }
    }

