    fn reference_fixture_structure(value: &Value) -> Structure {
        let structure_json = &value["structure"];
        structure_from_atoms_json(structure_json)
    }

    fn structure_from_atoms_json(structure_json: &Value) -> Structure {
        use crate::geometry::Cell;

        let species = structure_json["atomic_numbers"]
            .as_array()
            .unwrap()
            .iter()
            .map(|value| symbol_for_atomic_number(value.as_u64().unwrap() as u8))
            .collect::<Vec<_>>();
        let positions = structure_json["positions"]
            .as_array()
            .unwrap()
            .iter()
            .map(json_vec3)
            .collect::<Vec<_>>();
        let pbc = json_bool3(&structure_json["pbc"]);
        let structure = Structure::new(species, positions);
        if pbc.iter().any(|enabled| *enabled) {
            let cell_rows = structure_json["cell"]
                .as_array()
                .unwrap()
                .iter()
                .map(json_vec3)
                .collect::<Vec<_>>();
            structure.with_cell(Cell::new([cell_rows[0], cell_rows[1], cell_rows[2]]), pbc)
        } else {
            structure
        }
    }

