        edge_boundary.edge_feats = Vec::new();
        forward.edge_boundary = edge_boundary;
        forward.interaction0 = interaction0;
        forward.edge_mlp0 = edge_mlp0;
        forward.conv_tp0 = conv_tp0;
        forward.post_scatter0 = post_scatter0;
