    #[allow(clippy::too_many_arguments)]
    fn edge_input_test_forward_cache(
        runtime: &MaceMh1RuntimeState,
        head_index: usize,
        head_scale: f64,
        node_count: usize,
        edge_src: Vec<usize>,
        edge_dst: Vec<usize>,
        edge_vectors: Vec<[f64; 3]>,
        edge_src_atomic_numbers: Vec<usize>,
        edge_dst_atomic_numbers: Vec<usize>,
        interaction0_source_embedding: Vec<f64>,
        interaction0_target_embedding: Vec<f64>,
        interaction0_linear_up: Vec<f64>,
        interaction0_skip_connection: Vec<f64>,
        interaction1_source_embedding: Vec<f64>,
        interaction1_target_embedding: Vec<f64>,
        interaction1_linear_up: Vec<f64>,
    ) -> Result<MaceMh1ForwardCache, MaceMh1Error> {
        let edge_count = edge_dst.len();
        if edge_src.len() != edge_count
            || edge_vectors.len() != edge_count
            || edge_src_atomic_numbers.len() != edge_count
            || edge_dst_atomic_numbers.len() != edge_count
        {
            return Err(invalid("edge input test edge metadata length mismatch"));
        }
        let sh_plan = SphericalHarmonicsPlan::component(L_MAX, true)?;
        let mut edge_attrs = vec![0.0; edge_count * MACE_MH1_SH_DIM];
        let mut edge_feats = vec![0.0; edge_count * MACE_MH1_NUM_BESSEL];
        let mut edge_cutoff = vec![0.0; edge_count];
        let mut edge_distances = vec![0.0; edge_count];
        let mut pair_node_energy = vec![0.0; node_count];
        let pair_cutoff_p = runtime.positive_usize_scalar("pair_repulsion_fn.p")?;
        let pair_coefficients = runtime.f64_tensor("pair_repulsion_fn.c", &[4])?;
        let pair_a_exp = runtime.f64_scalar("pair_repulsion_fn.a_exp")?;
        let pair_a_prefactor = runtime.f64_scalar("pair_repulsion_fn.a_prefactor")?;
        let pair_covalent_radii = runtime.f64_tensor("pair_repulsion_fn.covalent_radii", &[119])?;
        for edge in 0..edge_count {
            let vector = edge_vectors[edge];
            let distance =
                (vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2]).sqrt();
            edge_distances[edge] = distance;
            sh_plan.forward(
                vector,
                &mut edge_attrs[edge * MACE_MH1_SH_DIM..(edge + 1) * MACE_MH1_SH_DIM],
            )?;
            edge_cutoff[edge] = runtime.radial_embedding_forward(
                distance,
                edge_src_atomic_numbers[edge],
                edge_dst_atomic_numbers[edge],
                &mut edge_feats[edge * MACE_MH1_NUM_BESSEL..(edge + 1) * MACE_MH1_NUM_BESSEL],
            )?;
            let dst = edge_dst[edge];
            if dst >= node_count {
                return Err(invalid("edge input test dst out of range"));
            }
            pair_node_energy[dst] += mace_zbl_edge_energy_forward_from_parts(
                distance,
                edge_src_atomic_numbers[edge],
                edge_dst_atomic_numbers[edge],
                pair_cutoff_p,
                pair_coefficients,
                pair_a_exp,
                pair_a_prefactor,
                pair_covalent_radii,
            )?
            .value;
        }

        let mut forward = edge_mlp_test_forward_cache(
            runtime,
            head_index,
            head_scale,
            pair_node_energy,
            edge_src,
            edge_dst,
            edge_attrs,
            edge_feats,
            edge_cutoff,
            interaction0_source_embedding,
            interaction0_target_embedding,
            interaction0_linear_up,
            interaction0_skip_connection,
            interaction1_source_embedding,
            interaction1_target_embedding,
            interaction1_linear_up,
        )?;
        forward.edge_boundary.edge_vectors = edge_vectors;
        forward.edge_boundary.edge_distances = edge_distances;
        forward.edge_boundary.edge_src_atomic_numbers = edge_src_atomic_numbers;
        forward.edge_boundary.edge_dst_atomic_numbers = edge_dst_atomic_numbers;
        Ok(forward)
    }

    fn edge_input_test_energy(
        runtime: &MaceMh1RuntimeState,
        forward: &MaceMh1ForwardCache,
    ) -> Result<f64, MaceMh1Error> {
        let rebuilt = edge_input_test_rebuild(runtime, forward)?;
        tail_test_energy(runtime, &rebuilt)
    }

    fn edge_input_test_rebuild(
        runtime: &MaceMh1RuntimeState,
        forward: &MaceMh1ForwardCache,
    ) -> Result<MaceMh1ForwardCache, MaceMh1Error> {
        edge_input_test_forward_cache(
            runtime,
            forward.head_index,
            forward.head_scale,
            forward.type_ids.len(),
            forward.edge_boundary.edge_src.clone(),
            forward.edge_boundary.edge_dst.clone(),
            forward.edge_boundary.edge_vectors.clone(),
            forward.edge_boundary.edge_src_atomic_numbers.clone(),
            forward.edge_boundary.edge_dst_atomic_numbers.clone(),
            forward.interaction0.source_embedding.clone(),
            forward.interaction0.target_embedding.clone(),
            forward.interaction0.linear_up.clone(),
            forward.interaction0.skip_connection.clone(),
            forward.interaction1.source_embedding.clone(),
            forward.interaction1.target_embedding.clone(),
            forward.interaction1.linear_up.clone(),
        )
    }

