    #[test]
    fn edge_mlp_vjp_matches_finite_difference() {
        let runtime = edge_mlp_test_runtime();
        let node_count = 2;
        let edge_count = 2;
        let head_index = 4;
        let head_scale = 0.93;
        let forward = edge_mlp_test_forward_cache(
            &runtime,
            head_index,
            head_scale,
            vec![0.04, -0.02],
            vec![0, 1],
            vec![1, 0],
            tail_test_pattern_values(edge_count * MACE_MH1_SH_DIM, 13, 4.0e-3),
            tail_test_pattern_values(edge_count * MACE_MH1_NUM_BESSEL, 11, 1.5e-2),
            vec![0.74, 1.11],
            tail_test_pattern_values(node_count * MACE_MH1_NODE_CHANNELS, 17, 1.0e-4),
            tail_test_pattern_values(node_count * MACE_MH1_NODE_CHANNELS, 19, 1.1e-4),
            tail_test_pattern_values(node_count * MACE_MH1_INTERACTION0_CHANNELS, 23, 7.0e-4),
            product_test_interaction0_skip_connection(node_count),
            tail_test_pattern_values(node_count * MACE_MH1_NODE_CHANNELS, 29, 8.0e-5),
            tail_test_pattern_values(node_count * MACE_MH1_NODE_CHANNELS, 31, 9.0e-5),
            tail_test_pattern_values(node_count * MACE_MH1_INTERACTION1_CHANNELS, 37, 6.0e-4),
        )
        .unwrap();

        let vjp = runtime.edge_mlp_vjp(&forward).unwrap();
        assert_eq!(vjp.bar_edge_feats.len(), edge_count * MACE_MH1_NUM_BESSEL);
        assert_eq!(vjp.bar_edge_cutoff.len(), edge_count);
        assert_eq!(
            vjp.bar_edge_mlp0_augmented_edge_feats.len(),
            edge_count * MACE_MH1_INTERACTION0_EDGE_MLP_INPUT_DIM
        );
        assert_eq!(
            vjp.bar_edge_mlp1_augmented_edge_feats.len(),
            edge_count * MACE_MH1_INTERACTION1_EDGE_MLP_INPUT_DIM
        );
        assert_eq!(
            vjp.bar_interaction0_source_embedding.len(),
            node_count * MACE_MH1_NODE_CHANNELS
        );
        assert_eq!(
            vjp.bar_interaction1_target_embedding.len(),
            node_count * MACE_MH1_NODE_CHANNELS
        );

        let epsilon = 1.0e-6;
        for index in [0, 9, 10, 19] {
            let finite_difference = edge_mlp_test_finite_difference(
                &runtime,
                &forward,
                epsilon,
                |plus| plus.edge_boundary.edge_feats[index] += epsilon,
                |minus| minus.edge_boundary.edge_feats[index] -= epsilon,
            );
            let actual = vjp.bar_edge_feats[index];
            assert!(
                (actual - finite_difference).abs() <= 2.0e-7,
                "edge_feats[{index}] expected {finite_difference:.16e}, got {actual:.16e}"
            );
        }

        for index in 0..edge_count {
            let finite_difference = edge_mlp_test_finite_difference(
                &runtime,
                &forward,
                epsilon,
                |plus| plus.edge_boundary.edge_cutoff[index] += epsilon,
                |minus| minus.edge_boundary.edge_cutoff[index] -= epsilon,
            );
            let actual = vjp.bar_edge_cutoff[index];
            assert!(
                (actual - finite_difference).abs() <= 2.0e-7,
                "edge_cutoff[{index}] expected {finite_difference:.16e}, got {actual:.16e}"
            );
        }

        for index in [0, 511, 512] {
            let finite_difference = edge_mlp_test_finite_difference(
                &runtime,
                &forward,
                epsilon,
                |plus| plus.interaction0.source_embedding[index] += epsilon,
                |minus| minus.interaction0.source_embedding[index] -= epsilon,
            );
            let actual = vjp.bar_interaction0_source_embedding[index];
            assert!(
                (actual - finite_difference).abs() <= 2.0e-7,
                "interaction0 source_embedding[{index}] expected {finite_difference:.16e}, got {actual:.16e}"
            );
        }

        for index in [0, 511, 512] {
            let finite_difference = edge_mlp_test_finite_difference(
                &runtime,
                &forward,
                epsilon,
                |plus| plus.interaction0.target_embedding[index] += epsilon,
                |minus| minus.interaction0.target_embedding[index] -= epsilon,
            );
            let actual = vjp.bar_interaction0_target_embedding[index];
            assert!(
                (actual - finite_difference).abs() <= 2.0e-7,
                "interaction0 target_embedding[{index}] expected {finite_difference:.16e}, got {actual:.16e}"
            );
        }

        for index in [0, 511, 512] {
            let finite_difference = edge_mlp_test_finite_difference(
                &runtime,
                &forward,
                epsilon,
                |plus| plus.interaction1.source_embedding[index] += epsilon,
                |minus| minus.interaction1.source_embedding[index] -= epsilon,
            );
            let actual = vjp.bar_interaction1_source_embedding[index];
            assert!(
                (actual - finite_difference).abs() <= 2.0e-7,
                "interaction1 source_embedding[{index}] expected {finite_difference:.16e}, got {actual:.16e}"
            );
        }

        for index in [0, 511, 512] {
            let finite_difference = edge_mlp_test_finite_difference(
                &runtime,
                &forward,
                epsilon,
                |plus| plus.interaction1.target_embedding[index] += epsilon,
                |minus| minus.interaction1.target_embedding[index] -= epsilon,
            );
            let actual = vjp.bar_interaction1_target_embedding[index];
            assert!(
                (actual - finite_difference).abs() <= 2.0e-7,
                "interaction1 target_embedding[{index}] expected {finite_difference:.16e}, got {actual:.16e}"
            );
        }
    }

    #[test]
    fn edge_input_vjp_matches_finite_difference() {
        let runtime = edge_mlp_test_runtime();
        let node_count = 2;
        let edge_count = 2;
        let head_index = 5;
        let head_scale = 1.08;
        let forward = edge_input_test_forward_cache(
            &runtime,
            head_index,
            head_scale,
            node_count,
            vec![0, 1],
            vec![1, 0],
            vec![[1.12, -0.31, 0.44], [-0.73, 1.21, 0.28]],
            vec![6, 8],
            vec![8, 6],
            tail_test_pattern_values(node_count * MACE_MH1_NODE_CHANNELS, 17, 1.0e-4),
            tail_test_pattern_values(node_count * MACE_MH1_NODE_CHANNELS, 19, 1.1e-4),
            tail_test_pattern_values(node_count * MACE_MH1_INTERACTION0_CHANNELS, 23, 7.0e-4),
            product_test_interaction0_skip_connection(node_count),
            tail_test_pattern_values(node_count * MACE_MH1_NODE_CHANNELS, 29, 8.0e-5),
            tail_test_pattern_values(node_count * MACE_MH1_NODE_CHANNELS, 31, 9.0e-5),
            tail_test_pattern_values(node_count * MACE_MH1_INTERACTION1_CHANNELS, 37, 6.0e-4),
        )
        .unwrap();

        let vjp = runtime.edge_input_vjp(&forward).unwrap();
        assert_eq!(vjp.bar_edge_vectors.len(), edge_count);
        assert_eq!(vjp.bar_edge_distances.len(), edge_count);
        assert!(vjp
            .edge_mlp
            .bar_edge_feats
            .iter()
            .any(|value| *value != 0.0));

        let epsilon = 1.0e-6;
        for (edge, component) in [(0, 0), (0, 1), (1, 0), (1, 2)] {
            let finite_difference =
                edge_input_test_finite_difference(&runtime, &forward, epsilon, edge, component);
            let actual = vjp.bar_edge_vectors[edge][component];
            assert!(
                (actual - finite_difference).abs() <= 4.0e-7,
                "edge_vector[{edge}][{component}] expected {finite_difference:.16e}, got {actual:.16e}"
            );
        }
    }

