    #[test]
    fn equivariant_linear_blas_matches_scalar_reference() {
        let rows = 3;
        let input_dim = 5;
        let output_dim = 6;
        let instruction = MaceMh1EquivariantLinearInstruction {
            input_offset: 1,
            output_offset: 2,
            weight_offset: 0,
            input_features: 2,
            output_features: 2,
            dim: 2,
        };
        let instructions = [instruction];
        let path_weights = [1.0 / (instruction.input_features as f64).sqrt()];
        let input = (0..rows * input_dim)
            .map(|index| index as f64 * 0.125 - 0.5)
            .collect::<Vec<_>>();
        let weight = [0.5, -0.25, 1.25, 0.75];
        let output_mask = [1.0, 0.5, 1.0, 0.0, 1.0, -0.25];

        let mut expected = vec![0.25; rows * output_dim];
        for row in 0..rows {
            let input_row = &input[row * input_dim..(row + 1) * input_dim];
            let expected_row = &mut expected[row * output_dim..(row + 1) * output_dim];
            for out_feature in 0..instruction.output_features {
                for component in 0..instruction.dim {
                    let mut value = 0.0;
                    for in_feature in 0..instruction.input_features {
                        let input_index =
                            instruction.input_offset + in_feature * instruction.dim + component;
                        let weight_index = in_feature * instruction.output_features + out_feature;
                        value += input_row[input_index] * weight[weight_index];
                    }
                    let output_index =
                        instruction.output_offset + out_feature * instruction.dim + component;
                    expected_row[output_index] +=
                        value * path_weights[0] * output_mask[output_index];
                }
            }
        }

        let mut actual = vec![0.25; rows * output_dim];
        mace_mh1_equivariant_linear_blas(
            &input,
            &weight,
            &output_mask,
            &instructions,
            &path_weights,
            rows,
            input_dim,
            output_dim,
            &mut actual,
        );
        for (actual, expected) in actual.iter().zip(&expected) {
            assert_close(*actual, *expected);
        }

        let bar_out = (0..rows * output_dim)
            .map(|index| 0.75 - index as f64 * 0.0625)
            .collect::<Vec<_>>();
        let mut expected_bar_input = vec![0.125; rows * input_dim];
        for row in 0..rows {
            let output_row = &bar_out[row * output_dim..(row + 1) * output_dim];
            let input_row = &mut expected_bar_input[row * input_dim..(row + 1) * input_dim];
            for out_feature in 0..instruction.output_features {
                for component in 0..instruction.dim {
                    let output_index =
                        instruction.output_offset + out_feature * instruction.dim + component;
                    let bar =
                        output_row[output_index] * path_weights[0] * output_mask[output_index];
                    for in_feature in 0..instruction.input_features {
                        let input_index =
                            instruction.input_offset + in_feature * instruction.dim + component;
                        let weight_index = in_feature * instruction.output_features + out_feature;
                        input_row[input_index] += bar * weight[weight_index];
                    }
                }
            }
        }

        let mut actual_bar_input = vec![0.125; rows * input_dim];
        mace_mh1_equivariant_linear_vjp_input_blas(
            &weight,
            &output_mask,
            &instructions,
            &path_weights,
            rows,
            input_dim,
            output_dim,
            &bar_out,
            &mut actual_bar_input,
        );
        for (actual, expected) in actual_bar_input.iter().zip(&expected_bar_input) {
            assert_close(*actual, *expected);
        }
    }

