    #[test]
    fn equivariant_linear_vjp_blas_fuses_contiguous_all_one_groups() {
        let rows = 4;
        let input_dim = 16;
        let output_dim = 10;
        let instructions = [
            MaceMh1EquivariantLinearInstruction {
                input_offset: 0,
                output_offset: 1,
                weight_offset: 0,
                input_features: 2,
                output_features: 3,
                dim: 1,
            },
            MaceMh1EquivariantLinearInstruction {
                input_offset: 2,
                output_offset: 1,
                weight_offset: 6,
                input_features: 2,
                output_features: 3,
                dim: 1,
            },
            MaceMh1EquivariantLinearInstruction {
                input_offset: 4,
                output_offset: 5,
                weight_offset: 12,
                input_features: 2,
                output_features: 2,
                dim: 2,
            },
            MaceMh1EquivariantLinearInstruction {
                input_offset: 8,
                output_offset: 5,
                weight_offset: 16,
                input_features: 2,
                output_features: 2,
                dim: 2,
            },
            MaceMh1EquivariantLinearInstruction {
                input_offset: 12,
                output_offset: 5,
                weight_offset: 20,
                input_features: 2,
                output_features: 2,
                dim: 2,
            },
        ];
        let path_weights = mace_mh1_equivariant_linear_path_weights(&instructions);
        let weight_len = mace_mh1_equivariant_linear_weight_len(&instructions);
        let weight = (0..weight_len)
            .map(|index| index as f64 * 0.03125 - 0.375)
            .collect::<Vec<_>>();
        let bar_out = (0..rows * output_dim)
            .map(|index| 0.25 - index as f64 * 0.0078125)
            .collect::<Vec<_>>();
        let output_mask = vec![1.0; output_dim];
        let mut expected = vec![0.0625; rows * input_dim];
        for row in 0..rows {
            let output_row = &bar_out[row * output_dim..(row + 1) * output_dim];
            let input_row = &mut expected[row * input_dim..(row + 1) * input_dim];
            for (instruction, &path_weight) in instructions.iter().zip(&path_weights) {
                for out_feature in 0..instruction.output_features {
                    for component in 0..instruction.dim {
                        let output_index =
                            instruction.output_offset + out_feature * instruction.dim + component;
                        let bar = output_row[output_index] * path_weight;
                        for in_feature in 0..instruction.input_features {
                            let input_index =
                                instruction.input_offset + in_feature * instruction.dim + component;
                            let weight_index = instruction.weight_offset
                                + in_feature * instruction.output_features
                                + out_feature;
                            input_row[input_index] += bar * weight[weight_index];
                        }
                    }
                }
            }
        }

        let mut actual = vec![0.0625; rows * input_dim];
        mace_mh1_equivariant_linear_vjp_input_blas(
            &weight,
            &output_mask,
            &instructions,
            &path_weights,
            rows,
            input_dim,
            output_dim,
            &bar_out,
            &mut actual,
        );

        for (actual, expected) in actual.iter().zip(&expected) {
            assert_close(*actual, *expected);
        }
    }

