    #[test]
    fn equivariant_linear_blas_f32_matches_scalar_reference_at_dispatch_size() {
        let rows = 17;
        let input_dim = 20;
        let output_dim = 18;
        let instruction = MaceMh1EquivariantLinearInstruction {
            input_offset: 2,
            output_offset: 4,
            weight_offset: 0,
            input_features: 3,
            output_features: 4,
            dim: 2,
        };
        let instructions = [instruction];
        let path_weights = [1.0_f32 / (instruction.input_features as f32).sqrt()];
        let input = (0..rows * input_dim)
            .map(|index| ((index % 37) as f32 - 18.0) * 0.0125)
            .collect::<Vec<_>>();
        let weight = (0..instruction.input_features * instruction.output_features)
            .map(|index| ((index % 11) as f32 - 5.0) * 0.03125)
            .collect::<Vec<_>>();
        let output_mask = (0..output_dim)
            .map(|index| if index % 5 == 0 { 0.5_f32 } else { 1.0 })
            .collect::<Vec<_>>();

        let mut expected = vec![0.125_f32; rows * output_dim];
        for row in 0..rows {
            let input_row = &input[row * input_dim..(row + 1) * input_dim];
            let expected_row = &mut expected[row * output_dim..(row + 1) * output_dim];
            for out_feature in 0..instruction.output_features {
                for component in 0..instruction.dim {
                    let mut value = 0.0_f32;
                    for in_feature in 0..instruction.input_features {
                        let input_index =
                            instruction.input_offset + in_feature * instruction.dim + component;
                        let weight_index = in_feature * instruction.output_features + out_feature;
                        value += input_row[input_index] * weight[weight_index];
                    }
                    let output_index =
                        instruction.output_offset + out_feature * instruction.dim + component;
                    expected_row[output_index] +=
                        value * path_weights[0] * output_mask[output_index];
                }
            }
        }

        let mut actual = vec![0.125_f32; rows * output_dim];
        mace_mh1_equivariant_linear_blas_f32(
            &input,
            &weight,
            &output_mask,
            &instructions,
            &path_weights,
            rows,
            input_dim,
            output_dim,
            &mut actual,
        );
        for (index, (&actual, &expected)) in actual.iter().zip(&expected).enumerate() {
            let delta = (actual - expected).abs();
            assert!(
                delta <= 2.0e-5,
                "f32 BLAS forward[{index}] expected {expected:.8e}, got {actual:.8e}, delta {delta:.3e}"
            );
        }

        let bar_out = (0..rows * output_dim)
            .map(|index| ((index % 41) as f32 - 20.0) * 0.01)
            .collect::<Vec<_>>();
        let mut expected_bar_input = vec![0.0625_f32; rows * input_dim];
        for row in 0..rows {
            let output_row = &bar_out[row * output_dim..(row + 1) * output_dim];
            let input_row = &mut expected_bar_input[row * input_dim..(row + 1) * input_dim];
            for out_feature in 0..instruction.output_features {
                for component in 0..instruction.dim {
                    let output_index =
                        instruction.output_offset + out_feature * instruction.dim + component;
                    let bar =
                        output_row[output_index] * path_weights[0] * output_mask[output_index];
                    for in_feature in 0..instruction.input_features {
                        let input_index =
                            instruction.input_offset + in_feature * instruction.dim + component;
                        let weight_index = in_feature * instruction.output_features + out_feature;
                        input_row[input_index] += bar * weight[weight_index];
                    }
                }
            }
        }

        let mut actual_bar_input = vec![0.0625_f32; rows * input_dim];
        mace_mh1_equivariant_linear_vjp_input_blas_f32(
            &weight,
            &output_mask,
            &instructions,
            &path_weights,
            rows,
            input_dim,
            output_dim,
            &bar_out,
            &mut actual_bar_input,
        );
        for (index, (&actual, &expected)) in
            actual_bar_input.iter().zip(&expected_bar_input).enumerate()
        {
            let delta = (actual - expected).abs();
            assert!(
                delta <= 2.0e-5,
                "f32 BLAS VJP input[{index}] expected {expected:.8e}, got {actual:.8e}, delta {delta:.3e}"
            );
        }
    }

